    public function userLogin(Request $request) {
        $validate = Validator::make($request->all(), [
            'email' => 'required|string|email',
            'password' => 'required|string',
            // 'remember_me' => 'boolean'
        ]);
        if ($validate->fails()) {
            $errors = $validate->errors();
            if ($errors->has('email')) {
                $responce['message'] = $errors->first('email');
            } elseif ($errors->has('password')) {
                $responce['message'] = $errors->first('password');
            }
            $responce['status'] = 0;
        } else {
            $credentials = request(['email', 'password']);
            if (Auth::attempt($credentials)) {
                $user = $request->user();
                if ($user->create_account_approval == 0) {
                    $responce['status'] = 0;
                    $responce['message'] = 'These credentials do not match our records.';
                } else {
                    if ($user->status == 1) {
                        $user->wrong_attempts = 0;
                        $user->save();
                        $tokenResult = $user->createToken('Personal Access Token');
                        $token = $tokenResult->token;
                        // if ($request->remember_me) {
                            $token->expires_at = Carbon::now()->addMinute(10);
                        // }
                        $token->save();
                        $responce['status'] = 1;
                        $responce['message'] = "Welcome ". $user->first_name;
                        $responce['token'] = $tokenResult->accessToken;
                        $responce['token_expire'] = Carbon::parse($tokenResult->token->expires_at)->toDateTimeString();
                    } elseif (empty($user->email_verified_at)) {
                        $responce['status'] = 0;
                        $responce['message'] = "Please verfify your email address before login.";
                    } else {
                        $responce['status'] = 0;
                        $responce['message'] = "Your account is deactivated. Please contact admin to activate your account.";
                    }
                }
            } else {
                $Userdata = User::where('email', $request->email)->first();
                if (!empty($Userdata)) {
                    if ($Userdata->status == 1) {
                        $Userdata->wrong_attempts += 1;
                        if ($Userdata->wrong_attempts >= 3 ) {
                            $Userdata->status = 0;
                        }
                        $Userdata->save();
                        $responce['status'] = 0;
                        $responce['message'] = "These credentials do not match our records.";
                    } else {
                        $responce['status'] = 0;
                        $responce['message'] = "Your account is deactivated. Please contact admin to activate your account.";
                    }
                } else {
                    $TmpUser = TmpUser::where('email', $request->email)->first();
                    if (!empty($TmpUser)) {
                        if ($TmpUser->attempt >= 3) {
                            $responce['status'] = 0;
                            $responce['message'] = "Your account is deactivated. Please contact admin to activate your account.";
                        } else {
                            $TmpUser->attempt += 1;
                            $TmpUser->save();
                            $responce['status'] = 0;
                            $responce['message'] = "These credentials do not match our records.";
                        }
                    } else {
                        DB::table('temp_users')->insert([
                            'email' => $request->email,
                            'attempt' => 1,
                            'created_at' => date("Y-m-d H:i:s")
                        ]);
                        $responce['status'] = 0;
                        $responce['message'] = "These credentials do not match our records.";
                    }
                }
            }
        }
        return response()->json($responce);
    }

    public function userLogout(Request $request) {
        $responce['status'] = 1;
        $responce['message'] = "Logout successful";

        $request->user()->token()->revoke();
        return response()->json($responce);
    }

    public function userSignup(Request $request) {
        $Check = $lastId = 0;
        $GuestUser = User::where('create_account_approval', 0)
                        ->where(function ($query) use($request) {
                            $query->where('email', $request->email);
                            $query->orWhere('phone', $request->phone);
                        })
                        ->first();
        if (!empty($GuestUser)) {
            $ExistUser = User::where('create_account_approval', 1)
                        ->where(function ($query) use($request) {
                            $query->where('email', $request->email);
                            $query->orWhere('phone', $request->phone);
                        })
                        ->first();
            if (!empty($ExistUser)) {
                if ($ExistUser->email == $request->email) {
                    $responce['message'] = 'An account with this email already exist. Please use different email.';
                }
                elseif ($ExistUser->phone == $request->phone) {
                    $responce['message'] = 'An account with this phone number already exist. Please use different phone number.';
                }
                $responce['status'] = 0;
                return response()->json($responce);
            }
            $validate = Validator::make($request->all(), [
                'first_name' => 'required|string|min:3|max:64',
                'last_name' => 'required|string|min:3|max:64',
                'email' => 'required|email',
                'password' => 'required|string|min:6|confirmed',
                'phone' => 'required|digits:10',
            ]);

            if ($validate->fails()) {
                $responce['status'] = 0;

                // Error messages
                $errors = $validate->errors();
                if ($errors->has('email')) {
                    $responce['message'] = $errors->first('email');
                } elseif ($errors->has('first_name')) {
                    $responce['message'] = $errors->first('first_name');
                } elseif ($errors->has('last_name')) {
                    $responce['message'] = $errors->first('last_name');
                } elseif ($errors->has('password')) {
                    $responce['message'] = $errors->first('password');
                } elseif ($errors->has('phone')) {
                    $responce['message'] = $errors->first('phone');
                }
                return response()->json($responce);
            } else {
                $GuestUser->first_name = $request->first_name;
                $GuestUser->last_name = $request->last_name;
                $GuestUser->email = $request->email;
                $GuestUser->phone = $request->phone;
                $GuestUser->password = bcrypt($request->password);
                $GuestUser->create_account_approval = 1;
                $GuestUser->status = 0;
                $GuestUser->save();

                $Check = 1;
                $lastId = $GuestUser->id;
            }
        } else {
            $validate = Validator::make($request->all(), [
                'first_name' => 'required|string|min:3|max:64',
                'last_name' => 'required|string|min:3|max:64',
                'email' => 'required|email|unique:users',
                'password' => 'required|string|min:6|confirmed',
                'phone' => 'required|digits:10|unique:users',
            ]);

            if ($validate->fails()) {
                $responce['status'] = 0;

                // Error messages
                $errors = $validate->errors();
                if ($errors->has('email')) {
                    $responce['message'] = 'An account with this email already exist. Please use different email.';
                } elseif ($errors->has('first_name')) {
                    $responce['message'] = $errors->first('first_name');
                } elseif ($errors->has('last_name')) {
                    $responce['message'] = $errors->first('last_name');
                } elseif ($errors->has('password')) {
                    $responce['message'] = $errors->first('password');
                } elseif ($errors->has('phone')) {
                    $responce['message'] = 'An account with this phone number already exist. Please use different phone number.';
                }
                return response()->json($responce);
            } else {
                $user = new User([
                    'first_name' => $request->first_name,
                    'last_name' => $request->last_name,
                    'email' => $request->email,
                    'phone' => $request->phone,
                    'password' => bcrypt($request->password),
                    'vendor_id' => 0,
                    'status' => 0,
                    'create_account_approval' => 1,
                    'role' => 4,
                    'access_type' => 'customer',
                    'login_type' => 'email'
                ]);
                $user->save();

                $lastId = $user->id;
                $Check = 1;
            }
        }
        if ($Check == 1) {
            // Send email verifictaion link to user
            $token = Str::random(155);
            $verify_link = $this->frontendUrl .'verify/'. $token . '?email=' . $request->email;
            $admin = User::where('role', 1)->first();

            $UserTemplete = EmailTemplate::where('ref_code', 'RegistrationSuccessToUser')->first();
            $Message = str_replace(array("~firstname~", "~lastname~", "~website_url~", "~verify_link~", "~site_url~"), array($request->first_name, $request->last_name, $this->frontendUrl, $verify_link, $this->site), $UserTemplete->source);
            $Subject = $UserTemplete->subject;
            Mail::to($request->email)
                ->bcc($admin->email)
                ->send(new \App\Mail\RegistrationMailUser($Message, $Subject));

            // Send mail to admin
            $AdminTemplete = EmailTemplate::where('ref_code', 'RegistrationSuccessToAdmin')->first();

            $Message = str_replace(array("~firstname~", "~lastname~", "~email~", "~website_url~", "~site_url~"), array($request->first_name, $request->last_name, $request->email, $this->frontendUrl, $this->site), $AdminTemplete->source);
            $Subject = $AdminTemplete->subject;
            $OtdcMail = User::find(1);
            Mail::to($admin->email)->send(new \App\Mail\RegistrationMailUser($Message, $Subject));

            // Save email log
            $EmailLog = DB::table('email_logs')->insert([
                'user_id' => $lastId,
                'email' => $request->email,
                'subject' => $UserTemplete->subject,
                'email_content' => $UserTemplete->source,
                'created_at' => date('Y-m-d H:i:s')
            ]);

            $SmsTemplate = SmsTemplate::where('ref_code', 'RegistrationSuccess')->first();
            $msg = str_replace(array("~var1~", "~var2~", "~var3~", "~var4~"), array($request->first_name .",\n", "\n", "\nOTDC", "\n\n"), $SmsTemplate->source);
            parent::sendSms($request->phone, $msg, $SmsTemplate->templete_id);

            $newUser = User::find($lastId);
            $newUser->verification_token = $token;
            $newUser->save();
            // $tokenResult = $newUser->createToken('Personal Access Token');
            // $token = $tokenResult->token;

            // $responce['token'] = $tokenResult->accessToken;
            // $responce['token_expire'] = Carbon::parse($tokenResult->token->expires_at)->toDateTimeString();
            $responce['status'] = 1;
            $responce['message'] = 'Registration Successful. please verify your email to login.';
        } else {
            $responce['status'] = 0;
            $responce['message'] = 'Unable to register please try again.';
        }
        return response()->json($responce);
    }

    public function vendorSignup(Request $request) {
        if (isset($request->request_type) && $request->request_type == 'submit_prebooking_registration') {
            // return response()->json($request->all());
            $validate = Validator::make($request->all(), [
                'service_name' => 'required|string',
                'adult' => 'required|numeric',
                'child' => 'required|numeric',
                'first_name' => 'required|string',
                'last_name' => 'required|string',
                'gender' => 'required|string',
                'email' => 'required|email|unique:prebookings',
                'phone' => 'required|digits:10|unique:prebookings',
                'city' => 'required|string',
                'state' => 'required|string',
                'country' => 'required|string',
                'identity_proof' => 'required|string',
                'type_of_experience' => 'required|string',
                'year_of_experience' => 'required|numeric',
                'publication' => 'required|string',
                'social_media_handle' => 'required|string',
                'social_media_handle_url' => 'nullable|string',
                'description_experience' => 'required|string',
                'identity_proof_image.*' => 'required|mimes:jpeg,png,jpg'
            ]);
            if ($validate->fails()) {
                $responce['status'] = 0;
                // Error messages
                $errors = $validate->errors();
                if ($errors->has('service_name')) {
                    $responce['message'] = $errors->first('service_name');
                } elseif ($errors->has('adult')) {
                    $responce['message'] = $errors->first('adult');
                } elseif ($errors->has('child')) {
                    $responce['message'] = $errors->first('child');
                } elseif ($errors->has('first_name')) {
                    $responce['message'] = $errors->first('first_name');
                } elseif ($errors->has('last_name')) {
                    $responce['message'] = $errors->first('last_name');
                } elseif ($errors->has('gender')) {
                    $responce['message'] = $errors->first('gender');
                } elseif ($errors->has('email')) {
                    $responce['message'] = 'Sorry! You have already registered with this email.';
                } elseif ($errors->has('phone')) {
                    $responce['message'] = 'Sorry! You have already registered with this phone number.';
                } elseif ($errors->has('city')) {
                    $responce['message'] = $errors->first('city');
                } elseif ($errors->has('state')) {
                    $responce['message'] = $errors->first('state');
                } elseif ($errors->has('country')) {
                    $responce['message'] = $errors->first('country');
                } elseif ($errors->has('identity_proof')) {
                    $responce['message'] = $errors->first('identity_proof');
                } elseif ($errors->has('type_of_experience')) {
                    $responce['message'] = $errors->first('type_of_experience');
                } elseif ($errors->has('year_of_experience')) {
                    $responce['message'] = $errors->first('year_of_experience');
                } elseif ($errors->has('publication')) {
                    $responce['message'] = $errors->first('publication');
                } elseif ($errors->has('social_media_handle')) {
                    $responce['message'] = $errors->first('social_media_handle');
                } elseif ($errors->has('social_media_handle_url')) {
                    $responce['message'] = $errors->first('social_media_handle_url');
                } elseif ($errors->has('description_experience')) {
                    $responce['message'] = $errors->first('description_experience');
                } elseif ($errors->has('identity_proof_image')) {
                    $responce['message'] = $errors->first('identity_proof_image');
                }
            } else {
                // return response()->json($request->all());
                $UploadDir = 'images/vendor/';
                $allowed_formats = array('png', 'jpeg', 'jpg');
                $identity_image = array();
                $prop_images = json_decode($request->identity_proof_image, 1);
                if (!empty($prop_images)) {
                    foreach ($prop_images as $file) {
                        $mime_type = explode('/', mime_content_type($file))[1];
