                    // Send mail to admin
                    $AdminTemplete = EmailTemplate::where('ref_code', 'VendorRegistrationSuccessToAdmin')->first();
                    $AdminMailId = DB::select("SELECT * FROM users WHERE role = '1' ");
                    $Message = str_replace(array("~firstname~", "~lastname~", "~email~", "~phone~", "~enterprise~", "~website_url~", "~site_url~"), array($request->first_name, $request->last_name, $request->email, $request->phone, $request->name_of_enteprise, $this->frontendUrl, $this->site), $AdminTemplete->source);
                    $Subject = $AdminTemplete->subject;
                    $OtdcMail = User::find(1);
                    //$replyTo = $request->email;
                    /* Mail::to($admin->email)
                    ->bcc($OtdcMail->email)
                    ->send(new \App\Mail\RegistrationMailUser($Message, $Subject, $replyTo)); */

                    $responce['status'] = 1;
                    $responce['message'] = 'Registration Successful. We will contact you soon.';
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Unable to register please try after some time.';
