    public function registerBooking(Request $request) {
        if ($request->request_type == 'send_interest') {
            $validate = Validator::make($request->all(), [
                'service_name' => 'required|string',
                'first_name' => 'required|string',
                'last_name' => 'required|string',
                'gender' => 'required|string',
                'email' => 'required|email|unique:customer_interests',
                'phone' => 'required|digits:10|unique:customer_interests',
                'city' => 'required|string',
                'state' => 'required|string',
                'country' => 'required|string',
            ]);
            if ($validate->fails()) {
                $responce['status'] = 0;
                // Error messages
                $errors = $validate->errors();
                if ($errors->has('first_name')) {
                    $responce['message'] = $errors->first('first_name');
                } elseif ($errors->has('last_name')) {
                    $responce['message'] = $errors->first('last_name');
                } elseif ($errors->has('gender')) {
                    $responce['message'] = $errors->first('gender');
                } elseif ($errors->has('email')) {
                    $responce['message'] = $errors->first('email');
                } elseif ($errors->has('phone')) {
                    $responce['message'] = $errors->first('phone');
                } elseif ($errors->has('city')) {
                    $responce['message'] = $errors->first('city');
                } elseif ($errors->has('state')) {
                    $responce['message'] = $errors->first('state');
                } elseif ($errors->has('country')) {
                    $responce['message'] = $errors->first('country');
                }
            } else {
                $CustomerInterest = new CustomerInterest([
                    'vendor_id' => 6045,
                    'service_name' => $request->service_name,
                    'cust_first_name' => $request->first_name,
                    'cust_last_name' => $request->last_name,
                    'email' => $request->email,
                    'phone' => $request->phone,
                    'cust_gender' => $request->gender,
                    'cust_country' => $request->country,
                    'cust_state' => $request->state,
                    'cust_city' => $request->city,
                ]);
                if ($CustomerInterest->save()) {
                    $LastId = $CustomerInterest->id;
                    $application_no = date('dmy'). '0'. $LastId;
                    CustomerInterest::find($LastId)->update(['application_no' => $application_no]);

                    // Send mail to user
                    $admin = User::where('role', 1)->first();
                    $UserTemplete = EmailTemplate::where('ref_code', 'CustomerInterestRequest')->first();
                    $Message = str_replace(array("~firstname~", "~lastname~", "~applicationno~", "~website_url~", "~site_url~"), array($request->first_name, $request->last_name, $application_no, $this->frontendUrl, $this->site), $UserTemplete->source);
                    $Subject = $request->service_name .' '. $UserTemplete->subject;
                    Mail::to($request->email)
                    ->bcc($admin->email)
                    ->send(new \App\Mail\RegistrationMailUser($Message, $Subject));

                    $responce['status'] = 1;
                    $responce['message'] = 'Your request sent successfully.';
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Unable to send request. Please try again.';
                }
            }
        }

        return response()->json($responce);
    }

