    public function verifyEmail(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'verify_user_email') {

            $isValid = false;
            $message = '';
            $email = $request->email;
            $token = $request->token;
            $UserDetails = User::where('email', $email)->first();
            if (!empty($UserDetails)) {
                if ($UserDetails->verification_token == $token && $UserDetails->status != 1) {
                    $isValid = true;
                    $message = 'Email verified successfully. You can login to Odisha Tourism.';
                    $UserDetails->email_verified_at = date("Y-m-d H:i:s");
                    $UserDetails->status = 1;
                    $UserDetails->save();
                    $responce['status'] = 1;
                } elseif ($UserDetails->verification_token == $token && $UserDetails->status == 1) {
                    $responce['status'] = 2;
                    $message = 'Email already verified.';
                } else {
                    $responce['status'] = 0;
                    $message = 'Invalid token in url parameter.';
                }
            } else {
                $responce['status'] = 0;
                $message = 'Invalid email id in url parameter.';
            }
            $responce['message'] = $message;
        }
        return response()->json($responce);
    }

    public function userDetails(Request $request) {
