        $responce['message'] = 'User details';
        $user = $request->user();
        $City = City::pluck('name', 'id')->toArray();
        $State = State::pluck('name', 'id')->toArray();
        $Country = Country::pluck('name', 'id')->toArray();
        $user->photo = !empty($user->photo) ? $this->site . $user->photo : $this->site .'images/profile/no-image.png';
        $user->country_name = (!empty($user->country) && isset($Country[$user->country])) ? $Country[$user->country] : '';
        $user->state_name = (!empty($user->state) && isset($State[$user->state])) ? $State[$user->state] : '';
        $user->city_name = (!empty($user->city) && isset($City[$user->city])) ? $City[$user->city] : '';

        $user->last_name = strlen($user->last_name) ? $user->last_name : '';
        $user->phone = strlen($user->phone) ? $user->phone : '';
        $user->pincode = strlen($user->pincode) ? $user->pincode : '';
        $user->address = strlen($user->address) ? $user->address : '';
        $user->address2 = strlen($user->address2) ? $user->address2 : '';
        $user->birth_date = strlen($user->birth_date) ? $user->birth_date : '';
        $user->gender = strlen($user->gender) ? $user->gender : '';
        $user->gst_company_name = strlen($user->gst_company_name) ? $user->gst_company_name : '';
        $user->gst_company_address = strlen($user->gst_company_address) ? $user->gst_company_address : '';

        $responce['profile_data'] = $user;

        return response()->json($responce);
    }

