                // file_put_contents($file, base64_decode($image));
                // $image = Image::make($file)->resize(100,100);

                $file_name = 'images/profile/' . uniqid() . '.png';
                $image_base64 = base64_decode($request->photo);
                $file = public_path($file_name);
                file_put_contents($file, $image_base64);
                $this->image_resize(360, 220, $file_name);

                $user->photo = $file_name;

                $user->save();

                $responce['status'] = 1;
                $responce['message'] = "Profile image updated successfully.";
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user";
            }
        }
        elseif ($request->request_type == 'change_password') {
            $responce['message'] = '';
            $user = $request->user();
            if (!Hash::check($request->current_password, $user->password)) {
                $responce['status'] = 0;
                $responce['message'] = "Invalid current password";
            } elseif ($request->password != $request->confirm_password) {
                $responce['status'] = 0;
                $responce['message'] = "Password and confirm password mismatch";
            } else {
                $user->password = bcrypt($request->password);
                $user->save();
                $responce['status'] = 1;
                $responce['message'] = "Password changed successfully.";
            }
        }
        elseif ($request->request_type == 'delete_my_account') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $user->status = 0;
                if ($user->save()) {
                    $responce['status'] = 1;
                    $responce['message'] = "Your account deactivated successfully.";
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = "Unable to delete your profile. Please try after some time.";
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user";
            }
        }
        return response()->json($responce);
    }

    public function forgotPassword(Request $request) {
        $validate = Validator::make($request->all(), [
            'email' => 'required|string|email',
            'recaptcha' => 'required|string',
        ]);

        if ($validate->fails()) {
            $responce['status'] = 0;

            // Error messages
            $errors = $validate->errors();
            if ($errors->has('email')) {
                $responce['message'] = $errors->first('email');
            } elseif ($errors->has('recaptcha')) {
                $responce['message'] = $errors->first('recaptcha');
            }
        } else {
            $captcha = $request->recaptcha;
            $secret = env('RECAPTCHA_SECRET_KEY');
            $ip = $_SERVER['REMOTE_ADDR'];
            $action = file_get_contents("https://www.google.com/recaptcha/api/siteverify?secret=$secret&response=$captcha&remoteip=$ip");
            $result = json_decode($action, 1);
            if ($result['success'] == 1) {
                $UserDetails = User::where('email', $request->email)->first();
                if(!empty($UserDetails)) {
                    $token = Str::random(155);
                    $verify_link = $this->frontendUrl .'password/reset/'. $token . '?email=' . $request->email;
                    $admin = User::where('role', 1)->first();

                    // Send forgot password mail to user
                    $ForgotPasswordTemplete = EmailTemplate::where('ref_code', 'ForgotPassword')->first();
                    $Message = str_replace(array("~firstname~", "~lastname~", "~website_url~", "~verify_link~", "~site_url~"), array($UserDetails->first_name, $UserDetails->last_name, $this->frontendUrl, $verify_link, $this->site), $ForgotPasswordTemplete->source);
                    $Subject = $ForgotPasswordTemplete->subject;
                    Mail::to($request->email)
                    ->bcc($admin->email)
                    ->send(new \App\Mail\ForgotPasswordMail($Message, $Subject));

                    $current_date = date('Y-m-d H:i:s');
                    $link_expire = date('Y-m-d H:i:s', strtotime('+2 hour', strtotime($current_date)));
                    DB::insert("INSERT INTO `password_resets`(`email`, `token`, `expire_time`, `created_at`) VALUES ('".$request->email."', '".$token."', '".$link_expire."', '".$current_date."')");

                    // Save email logs
                    DB::insert("INSERT INTO `email_logs`(`user_id`, `email`, `subject`, `email_content`, `created_at`) VALUES ('".$UserDetails->id."', '".$request->email."', '".$Subject."', '".$Message."', '".$current_date."')");

                    $responce['status'] = 1;
                    $responce['message'] = 'A password reset mail is send to your mail id, Please go through this mail for change password';
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'A password reset mail is send to your mail id, Please go through this mail for change password';
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Invalid Captcha. Please try again.';
            }
        }
        return response()->json($responce);
    }

    public function resetPassword(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'token_validation') {
            $responce['message'] = '';
            $isValid = false;
            $message = '';
            $email = $request->email;
            $token = $request->token;
            $UserDetails = User::where('email', $email)->first();
            if (!empty($UserDetails)) {
                $PasswordLinkData = DB::table('password_resets')->where(['token' => $token, 'email' => $email])->first();
                if (!empty($PasswordLinkData)) {
                    if (strtotime($PasswordLinkData->expire_time) > strtotime(date('Y-m-d H:i:s'))) {
                        $isValid = true;
                    } else {
                        $message = 'Password change token is expired.';
                    }
                } else {
                    $message = 'Invalid token in url parameter.';
                }
            } else {
                $message = 'Invalid email id in url parameter.';
            }
            $responce['status'] = ($isValid) ? 1 : 0;
            $responce['message'] = $message;
        }
        elseif ($request->request_type == 'reset_password') {
            $validate = Validator::make($request->all(), [
                'email' => 'required|email',
                'password_reset_token' => 'required|string',
                // 'password' => 'required|min:8|regex:/^(?=.*?[A-Z])(?=.*?[a-z])(?=.*?[0-9])(?=.*?[#?!@$%^&*-]).{8,}$/',
            ]);

            if ($validate->fails()) {
                $responce['status'] = 0;

                // Error messages
                $errors = $validate->errors();
                if ($errors->has('email')) {
                    $responce['message'] = $errors->first('email');
                } elseif ($errors->has('password_reset_token')) {
                    $responce['message'] = $errors->first('password_reset_token');
                }
                // elseif ($errors->has('password')) {
                //     $responce['message'] = $errors->first('password');
                // }
            } else {
                $CurrTime = date('Y-m-d H:i:s');
                $TokenVerify = DB::table('password_resets')->where(['token' => $request->password_reset_token, 'email' => $request->email])
                    ->where('expire_time', '>', $CurrTime)
                    ->first();  //DB::select("SELECT * FROM `password_resets` WHERE `token` = '" . $request->password_reset_token . "' AND `email` = '" . $request->email . "' ");
                if (!empty($TokenVerify)) {
                    if ($TokenVerify->is_validated != 1) {
                        $UserDetails = User::where('email', $request->email)->first();
                        if (!empty($UserDetails)) {
                            $UserDetails->password = bcrypt($request->password);
                            $UserDetails->email_verified_at = date("Y-m-d H:i:s");
                            $UserDetails->save();

                            DB::table('password_resets')->where('id', $TokenVerify->id)->update(['is_validated' => 1, 'execute_time' => $CurrTime]);

                            $responce['status'] = 1;
                            $responce['message'] = 'Password change successful. Please go for login';
                        } else {
                            $responce['status'] = 0;
                            $responce['message'] = 'User not found with the provides email address';
                        }
                    } else {
                        $responce['status'] = 0;
                        $responce['message'] = 'You already used this token url for change password';
                    }
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Token expired or invalid email';
                }
            }
        }
        return response()->json($responce);
    }

    public function getAssets(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if($request->request_type == 'get_all_city') {
            $responce['message'] = '';
            $CityDetails = City::where('state_id', '4013')->OrderBy('name')->pluck('name', 'id');
            if (!empty($CityDetails)) {
                $city = array();
                foreach ($CityDetails as $value) {
                    $city[$value] = $value;
                }
                $responce['status'] = 1;
                $responce['data'] = $city;
            } else {
                $responce['status'] = 1;
                $responce['data'] = array();
            }
        }
        elseif($request->request_type == 'get_city') {
            $responce['message'] = '';
            $HotelCity = MasterHotel::select(DB::raw('DISTINCT(place) AS city'))->where('status', 'publish')->where('vender_id', '!=', '3')->where('vender_id', '!=', '58672')->get()->toArray();
            $RentalCity = MasterCar::select(DB::raw('DISTINCT(city) AS city'))->where('status', 'publish')->get()->toArray();
            $CaravanCity = MasterCaravan::select(DB::raw('DISTINCT(city) AS city'))->where('status', 'publish')->get()->toArray();
            $HallCity = HallProperty::select(DB::raw('DISTINCT(place) AS city'))->where('publish_status', 'PUBLISH')->get()->toArray();
            $TourCity = Tour::select(DB::raw('DISTINCT(city) AS city'))->where('status', 'publish')->where('vendor_id', '!=', '58672')->get()->toArray();
            $TicketCity = Ticket::select(DB::raw('DISTINCT(place) AS city'))->where('status', 'publish')->get()->toArray();
