    public function getProductTotal($id = null) {
        $ParentCategory = CategoryTable::where('parent_id', $id)->get();
        $allChild = array();
        foreach ($ParentCategory as $category) {
            array_push($allChild, $category['id']);
            if (count($category->subcategory)) {
                foreach ($category->subcategory as $category1) {
                    array_push($allChild, $category1['id']);
                    if (count($category->subcategory)) {
                        foreach ($category1->subcategory as $category2) {
                            array_push($allChild, $category2['id']);
                            if (count($category2->subcategory)) {
                                foreach ($category2->subcategory as $category3) {
                                    array_push($allChild, $category3['id']);
                                }
                            }
                        }
                    }
                }
            }
        }
        array_push($allChild, $id);
        $TotalProduct = MerchantProduct::whereIn('category', $allChild)->get()->count();
        //$TotalProduct = MerchantProduct::whereRaw("find_in_set(".$id.",category)")->get()->count();
        return $TotalProduct;
    }

    public function hotelDetails(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'get_hotel_list') {
            $responce['message'] = '';
            // $OtdcHotelQuery = DB::table('master_hotels')
            //         ->select('id', 'name', 'slug', 'feature_image', 'address', 'property', 'star_rate', 'price', 'service_fee', 'map_lat', 'map_lng', 'review_score', 'review_count')
            //         ->where(['status' => 'publish', 'vender_id' => 4]);

            $sort_column = 'vender_id';
            $sort_direction = 'asc';

            $MasterHotelQuery = DB::table('master_hotels')
                    ->select('id', 'name', 'slug', 'feature_image', 'address', 'property', 'star_rate', 'service_fee', 'map_lat', 'map_lng', 'review_score', 'review_count', 'show_price')
                    ->where('status', 'publish');
            if (!empty($request->hotel_star)) {
                $star_rate = json_decode($request->hotel_star, 1);
                $MasterHotelQuery->whereIn('star_rate', $star_rate);
            }
            if (!empty($request->prop_name)) {
                $MasterHotelQuery->where('name', 'like', '%'. $request->prop_name .'%');
            }
            if (!empty($request->property)) {
                $property = json_decode($request->property, 1);
                foreach ($property as $terms) {
                    $MasterHotelQuery->where('property_slug', 'like', '%'. $terms .'%');
                }
            }
            if (!empty($request->review_score)) {
                $reviews = json_decode($request->review_score, 1);
                $MasterHotelQuery->whereIn('review_score', $reviews);
            }
            // if ($request->startPrice != '' && $request->endPrice != '') {
            //     $MasterHotelQuery->whereBetween('price', [$request->startPrice, $request->endPrice]);
            // }
            if (!empty($request->vendorId)) {
                $vendors = json_decode($request->vendorId, 1);
                $MasterHotelQuery->whereIn('vender_id', $vendors);
            } else {
                $MasterHotelQuery->where('vender_id', '!=', 3);
                $MasterHotelQuery->where('vender_id', '!=', 58672);
            }
            if ($request->city != '') {
                $MasterHotelQuery->where('place', 'like', '%'. $request->city .'%');
                // $OtdcHotelQuery->where('city', $request->city);
            }
            if ($request->checkinDate != '' && $request->checkoutDate != '') {
                // $MasterHotelQuery->whereBetween('reservation_from', [$request->checkinDate, $request->checkoutDate]);
            }
            if ($request->sortColumn != '' && $request->direction != '') {
                $sort_column = $request->sortColumn;
                $sort_direction = $request->direction;
            }
            $MasterHotelQuery->orderBy($sort_column, $sort_direction);
            // $OtdcHotel = $OtdcHotelQuery->get();
            // if (!empty($OtdcHotel)) {
            //     foreach ($OtdcHotel as $value1) {
            //         $value1->feature_image = $this->site . $value1->feature_image;
            //         $property = json_decode($value1->property, 1);
            //         $value1->property = $property['Facilities'];
            //     }
            // }
            $take = 10;
            $skip = ($request->pageno == 0) ? $request->pageno : $request->pageno * $take;
            $totalData = $MasterHotelQuery->count();

            $MasterHotel = $MasterHotelQuery->get();  // ->skip($skip)->take($take)
            if (!empty($MasterHotel)) {
                foreach ($MasterHotel as $key => $value) {
                    $value->feature_image = $this->site . $value->feature_image;
                    $property = json_decode($value->property, 1);
                    $value->property = isset($property['Facilities']) ? array_slice($property['Facilities'], 0, 5) : [];
                    $HotelRooms = HotelRoom::where(['hotel_id' => $value->id, 'status' => 'publish'])
                                    ->where('price', '>=', $request->startPrice)
                                    ->where('price', '<=', $request->endPrice)
                                    ->orderBy('price', 'asc')->first();
                    if (!empty($HotelRooms)) {
                        $value->price = number_format($HotelRooms->price, 0);
                        $value->room_name = $HotelRooms->title;
                        $value->adult = $HotelRooms->adults;
                        $value->child = $HotelRooms->children;
                    } else {
                        unset($MasterHotel[$key]);
                        continue;
                    }
                    $value->review_score = !empty($value->review_score) ? round($value->review_score, 2) : 0;
                    $value->review_count = !empty($value->review_count) ? $value->review_count : 0;
                }
            }
            if (!empty($MasterHotel)) {
                $RelatedHotel = array();
                if (isset($request->relatedKey) && !empty($request->relatedKey)) {
                    $RelatedHotel = DB::table('master_hotels')
                    ->select('id', 'name', 'slug', 'feature_image', 'address', 'property', 'star_rate', 'price', 'service_fee', 'map_lat', 'map_lng', 'review_score', 'review_count', 'show_price')
                    ->where('status', 'publish')
                    ->where('name', 'like', '%'. $request->relatedKey .'%')
                    ->where('name', '<>', $request->prop_name)
