                $HotelRooms = HotelRoom::select('id', 'hotel_id', 'title', 'slug', 'image', 'gallery', 'price', 'quantity', 'beds', 'size', 'adults', 'children', 'extra_bed_price', 'extra_bed_allowed', 'property', 'bed_type')->where(['hotel_id' => $MasterHotel->id, 'status' => 'publish'])->orderBy('price', 'ASC')->get()->toArray();
                if (!empty($request->requested_room) && !empty($HotelRooms)) {
