                            if ($room_total >= $total_guests && $total_adults <= ($room['adults'] + $room['extra_bed_allowed'])) {
                                if ($room['adults'] < $total_adults || $room['children'] < $total_child) {
                                    if($total_child == 0) {
                                        $extra_bed = $total_guests - $room['adults'];
                                    } else {
                                        // $extra_bed = $total_guests - ($room['adults'] + $room['children']);
                                        if (($total_adults > $room['adults']) && ($total_child > $room['children'])) {
                                            $extra_bed = ($total_adults + $total_child) - ($room['adults'] + $room['children']);
                                        } elseif ($total_child > $room['children'] && $total_guests > ($room['adults'] + $room['children'])) {
