                            $minAdult = $room['adults'];
                            $maxLoop = $inLoop = (($max_bed - $minAdult) < $minAdult) ? $minAdult : $max_bed - $minAdult;

                            for ($i = 0; $i <= $maxLoop; $i++) {
                                for ($j = 0; $j <= $inLoop; $j++) {
                                    $exbed = 0;
                                    if ($j == 0) {
                                        $exbed = ($minAdult > $room['adults']) ? $minAdult - $room['adults'] : 0;
                                    } else {
