    public function carDetails(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'get_car_list') {
            $responce['message'] = '';
            $sort_column = 'vendor_id';
            $sort_direction = 'asc';

            $MasterCarQuery = DB::table('master_cars')
                    ->select('id', 'title', 'slug', 'feature_image', 'city', 'price_per_km', 'map_lat', 'map_lng', 'review_score', 'review_count', 'passenger', 'gear', 'baggage', 'door', 'quantity', 'show_price')
                    ->where('status', 'publish');

            if(!empty($request->property)) {
                $property = json_decode($request->property, 1);
                foreach ($property as $terms) {
                    $MasterCarQuery->where('property_slug', 'like', '%'. $terms .'%');
                }
            }
            if(!empty($request->review_score)) {
                $reviews = json_decode($request->review_score, 1);
                $MasterCarQuery->whereIn('review_score', $reviews);
            }
            if($request->startPrice != '' && $request->endPrice != '') {
                $MasterCarQuery->whereBetween('price_per_km', [$request->startPrice, $request->endPrice]);
            }
            if ($request->city != '') {
                $MasterCarQuery->where('city', 'like', '%'. $request->city .'%');
            }
            if(!empty($request->vendorId)) {
                $vendors = json_decode($request->vendorId, 1);
                $MasterCarQuery->whereIn('vendor_id', $vendors);
            }
            if(!empty($request->capacity)) {
                $passenger = json_decode($request->capacity, 1);
                $MasterCarQuery->whereIn('passenger', $passenger);
            }
            if (!empty($request->prop_name)) {
                $MasterCarQuery->where('title', 'like', '%'. $request->prop_name    .'%');
            }
            if ($request->sortColumn != '' && $request->direction != '') {
                $sort_column = $request->sortColumn;
                $sort_direction = $request->direction;
            }
            $MasterCarQuery->orderBy($sort_column, $sort_direction);
            $take = 9;
            $skip = ($request->pageno == 0) ? $request->pageno : $request->pageno * $take;
            $totalData = $MasterCarQuery->count();

            $MasterCar = $MasterCarQuery->skip($skip)->take($take)->get()->toArray();

            if (!empty($MasterCar)) {
                foreach ($MasterCar as $key => $value) {
                    $MasterCar[$key]->feature_image = $this->site . $value->feature_image;
                    $value->review_score = !empty($value->review_score) ? round($value->review_score, 2) : 0;
                    $value->review_count = !empty($value->review_count) ? $value->review_count : 0;
                    $value->price_per_km = number_format($value->price_per_km, 0);
                }
                $RelatedCar = array();
                if (!empty(isset($request->relatedKey) && !empty($request->relatedKey))) {
                    $RelatedCar = DB::table('master_cars')
                        ->select('id', 'title', 'slug', 'feature_image', 'city', 'price_per_km', 'map_lat', 'map_lng', 'review_score', 'review_count', 'passenger', 'gear', 'baggage', 'door', 'quantity', 'show_price')
                        ->where('status', 'publish')
                        ->where('title', '<>', $request->prop_name)
                        ->where('title', 'like', '%'. $request->relatedKey .'%')
                        ->get()->toArray();
                    if (!empty($RelatedCar)) {
                        foreach ($RelatedCar as $key => $value) {
                            $RelatedCar[$key]->feature_image = $this->site . $value->feature_image;
                            $value->review_score = !empty($value->review_score) ? round($value->review_score, 2) : 0;
                            $value->review_count = !empty($value->review_count) ? $value->review_count : 0;
                            $value->price_per_km = number_format($value->price_per_km, 0);
                        }
                    }
                }

                $responce['totalPage'] = ceil($totalData/$take);
                $responce['length'] = $totalData;
                $responce['status'] = 1;
                $responce['data'] = $MasterCar;
                $responce['related_data'] = $RelatedCar;
            } else {
                $responce['status'] = 0;
                $responce['status'] = 'No cars available';
            }
            // $responce['banner_image'] = $this->site . 'images/cars/banner-search-space-2.jpg';
        }
        elseif ($request->request_type == 'get_car_details') {
            $responce['message'] = '';
            if (isset($request->slug)) {
                $MasterCar = MasterCar::where(['slug' => $request->slug, 'status' => 'publish'])->first();
            } else {
                $MasterCar = MasterCar::where(['id' => $request->carId, 'status' => 'publish'])->first();
            }
            if (!empty($MasterCar)) {
                $UserData = User::find($MasterCar->vendor_id);
                $MasterCar->vendor_name = $UserData->company;
                $MasterCar->vendor_email = $UserData->email;
                $MasterCar->vendor_image = $this->site . $UserData->photo;
                $MasterCar->member_since = date("M Y", strtotime($UserData->created_at));

                $vendor_profile = VendorProfile::where('vendor_id', $MasterCar->vendor_id)->first();
                if (!empty($vendor_profile)) {
                    $MasterCar->vendor_profile = $vendor_profile->profile_type;
                    if ($vendor_profile->profile_type == 'own') {
                        $MasterCar->vendor_slug = !empty($vendor_profile->profile_url) ? $vendor_profile->profile_url : 'javascript:void(0)';
                    } else {
                        $MasterCar->vendor_slug = $vendor_profile->slug;
                    }
                } else {
                    $MasterCar->vendor_slug = '';
                }

                $MasterCar->feature_image = !empty($MasterCar->feature_image) ? $this->site . $MasterCar->feature_image : $MasterCar->feature_image;
                $MasterCar->banner_image = !empty($MasterCar->banner_image) ? $this->site . $MasterCar->banner_image : $MasterCar->banner_image;
                if (!empty($MasterCar->gallery)) {
                    $hotel_gallery = json_decode($MasterCar->gallery);
                    $MasterCar->gallery = array_map(function($val) { return $this->site . $val; } , $hotel_gallery);
                }
                $MasterCar->faqs = !empty($MasterCar->faqs) ? json_decode($MasterCar->faqs, 1) : $MasterCar->faqs;
                $Property = !empty($MasterCar->property) ? json_decode($MasterCar->property, 1) : [];
                $PropertyApp = array();
                if (!empty($Property)) {
                    foreach ($Property as $key => $parent) {
                        foreach ($parent as $ckey => $val) {
                            $Property[$key][$ckey]['icon'] = !empty($val['icon']) ? $this->site . $val['icon'] : '';
                        }
                        $PropertyApp[] = array(
                            'name' => $key,
                            'data' => $Property[$key]
                        );
                    }
                }
                $MasterCar->property = $Property;
                $MasterCar->property_app = $PropertyApp;

                // if (!empty($MasterCar->property)) {
                //     $property = json_decode($MasterCar->property, 1);
                //     unset($property['Car Type']);
                //     $MasterCar->property = $property;
                // }
                $days = 0;
                $MasterCar->book_date = date("Y-m-d H:i:s", strtotime('+24 hours'));
                if ($request->checkinDate != '' && $request->checkoutDate != '') {
                    if (date("Y-m-d", strtotime($request->checkinDate)) != date("Y-m-d")) {
                        $MasterCar->book_date = date("Y-m-d H:i:s", strtotime($request->checkinDate));
                    }
                    $request->checkinDate = date("Y-m-d", strtotime($request->checkinDate));
                    $request->checkoutDate = date("Y-m-d", strtotime($request->checkoutDate));
                    $BlockedVehicle = BlockedVehicle::where('vehicle_id', $MasterCar->id)
                        ->whereBetween('block_date', [$request->checkinDate, $request->checkoutDate])
                        ->get()->toArray();
                    if(empty($BlockedVehicle)) {
                        if ($request->checkinDate == $request->checkoutDate) {
                            $days = 1;
                        } else {
                            $difference = strtotime($request->checkoutDate) - strtotime($request->checkinDate);
                            $days = round($difference / (60 * 60 * 24));
                        }
                        $quantity_array = array();
                        $cal_day = ($days == 0) ? 1 : $days + 1;
                        for($i = 0; $i < $cal_day; $i++) {
                            $checkDate = date("Y-m-d", strtotime($request->checkinDate .' + '. $i .' days'));
                            $MasterInventory = RentalMasterInventory::where(["date" => $checkDate, "car_id" => $MasterCar->id])->first();
                            if (!empty($MasterInventory)) {
                                array_push($quantity_array, $MasterInventory->total_available);
                            } else {
                                array_push($quantity_array, 0);
                            }
                        }
                        $MasterCar->quantity = min($quantity_array);
                        if ($MasterCar->quantity < 1) {
                            $responce['message'] = 'Vehicle is not available in between the choosen dates. Please choose different dates!';
                        }
                    } else {
                        $MasterCar->quantity = 0;
                        $responce['message'] = 'Vehicle is not available in between the choosen dates. Please choose different dates!';
                    }
                }
                // $MasterCar->book_date = date("Y-m-d", strtotime('+1 days'));

                $responce['status'] = 1;
                $responce['data'] = $MasterCar;
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Car not available';
            }
        }
        elseif ($request->request_type == 'check_car_availability') {
            $responce['message'] = '';
            $MasterCar = MasterCar::find($request->carId);
            if (!empty($MasterCar)) {
                if ($request->checkinDate != '' && $request->checkoutDate != '') {
                    $request->checkinDate = date("Y-m-d", strtotime($request->checkinDate));
                    $request->checkoutDate = date("Y-m-d", strtotime($request->checkoutDate));
                    $BlockedVehicle = BlockedVehicle::where('vehicle_id', $MasterCar->id)
                        ->whereBetween('block_date', [$request->checkinDate, $request->checkoutDate])
                        ->get()->toArray();
                    if(empty($BlockedVehicle)) {
                        if ($request->checkinDate == $request->checkoutDate) {
                            $days = 1;
                        } else {
                            $difference = strtotime($request->checkoutDate) - strtotime($request->checkinDate);
                            $days = round($difference / (60 * 60 * 24));
                        }
                        $quantity_array = array();
                        $cal_day = ($days == 0) ? 1 : $days + 1;
                        for($i = 0; $i < $cal_day; $i++) {
                            $checkDate = date("Y-m-d", strtotime($request->checkinDate .' + '. $i .' days'));
                            $MasterInventory = RentalMasterInventory::where(["date" => $checkDate, "car_id" => $MasterCar->id])->first();
                            if (!empty($MasterInventory)) {
                                array_push($quantity_array, $MasterInventory->total_available);
                            } else {
                                array_push($quantity_array, 0);
                            }
                        }
                        $MasterCar->quantity = min($quantity_array);

                        if ($MasterCar->quantity < 1) {
                            $responce['message'] = 'Vehicle is not available in between the choosen dates. Please choose different dates!';
                        }
                    } else {
                        $MasterCar->quantity = 0;
                        $responce['message'] = 'Vehicle is not available in between the choosen dates. Please choose different dates!';
                    }
                    $responce['status'] = 1;
                    $responce['available_car'] = $MasterCar->quantity;
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Enter valid check-in and check-out date';
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Car not available';
            }
        }
        elseif ($request->request_type == 'get_calculate_price') {
            $responce['message'] = '';
            $CarDetails = MasterCar::find($request->car_id);
            $sub_total_price = $travel_distance = $travel_hour = $halt_hour = $halt_charge = 0;
            $start_date = $end_date = $start_time = $end_time = $drop_location = $pickup_address = $route = '';
            $DayBreak = $route = $price_breakup = array();
            if (!empty($CarDetails)) {
                if ($request->rental_type == 'default') {
                    $DayBreak[] = array(
                        'date' => [
                            'startDate' => $request->checkinDate,
                            'endDate' => $request->checkoutDate
                        ],
                        'day_km' => $request->distance
                    );

                } else {
                    $DayBreak = json_decode($request->day_breakup_details, 1);
                }
                foreach ($DayBreak as $val) {
                    $totalPrice = $totalPriceKm = $totalPriceHr = $totalHour = $totalHaltPrice = $detention_charge = $detention_hour = $extrakm_price = $extrakm = $calculateHr = 0;
                    $difference = strtotime(date("Y-m-d", strtotime($val['date']['endDate']))) - strtotime(date("Y-m-d", strtotime($val['date']['startDate'])));
                    $days = floor($difference / (60 * 60 * 24));

                    $checkinDate = new DateTime($val['date']['startDate']);
                    $checkoutDate = new DateTime($val['date']['endDate']);

                    $interval = $checkinDate->diff($checkoutDate);
                    $totalHour = $interval->format('%h') + ($interval->format('%d') * 24);

                    $travelHr = ceil($val['day_km'] / $CarDetails->dist_cover_per_hour);
                    $cover_day = $days + 1;
                    $cover_distance_day = $val['day_km'] / $cover_day;
                    if ($cover_distance_day >= $CarDetails->max_distance) {
                        $totalPriceKm = $val['day_km'] * $CarDetails->price_per_km;
                        $halthour = $days * $CarDetails->halt_hour;
                        $totalHaltPrice = $days * $CarDetails->price_for_halt;
                        $calculateHr = $totalHour - $halthour;
                        $detention_hour = $totalHour - $travelHr - $halthour;
                        if ($detention_hour > 0) {
                            $detention_charge = $detention_hour * $CarDetails->detention_charge_per_hour;
                        }
                        $totalPrice = ($totalPriceKm + $detention_charge + $totalHaltPrice) * 1;
                    } else {
                        $totalPriceKm = $travelHr * $CarDetails->price_per_hour;
                        $halthour = $days * $CarDetails->halt_hour;
                        $calculateHr = $totalHour - $halthour;
                        if ($val['day_km'] > ($calculateHr * $CarDetails->free_km_per_hour)) {
                            $extrakm = $val['day_km'] - ($calculateHr * $CarDetails->free_km_per_hour);
                        }
                        if ($val['day_km'] > $extrakm) {
                            $extrakm_price = $extrakm * $CarDetails->price_per_km;
                        }
                        $totalPriceHr = $calculateHr * $CarDetails->price_per_hour;
                        $totalHaltPrice = $days * $CarDetails->price_for_halt;
                        $totalPrice = ($totalPriceHr + $totalHaltPrice + $extrakm_price) * 1;
                    }

                    $price_breakup[] = array(
                        "maxKm" => $CarDetails->max_distance,
                        "kmValue" => $val['day_km'],
                        "price_per_km" => $CarDetails->price_per_km,
                        "price_per_hr" => $CarDetails->price_per_hour,
                        "price_for_halt" => $CarDetails->price_for_halt,
                        "totalPriceKm" => $totalPriceKm,
                        "totalPriceHr" => $totalPriceHr,
                        "calculateHr" => $calculateHr,
                        "totalHaltPrice" => $totalHaltPrice,
                        "totalhalt" => $days,
                        "detainationCharge" => $detention_charge,
                        "detainationHour" => $detention_hour,
                        "detention_charge_per_hour" => $CarDetails->detention_charge_per_hour,
                        "per_day_km_covered" => $cover_distance_day,
                        "extrakm_price" => $extrakm_price,
                        "extrakm" => $extrakm,
                        "booking_date" => array(
                          "startDate" => date("d-m-Y h:i a", strtotime($val['date']['startDate'])),
                          "endDate" => date("d-m-Y h:i a", strtotime($val['date']['endDate']))
                        ),
                        "totalPrice" => $totalPrice
                    );
                    $sub_total_price += $totalPrice;
                }
                $responce['status'] = 1;
                $responce['price_breakup'] = $price_breakup;
                $responce['totalPrice'] = $sub_total_price;
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Invalid vehicle id.';
            }
        }
        return response()->json($responce);
    }

    public function postEnquiry(Request $request) {
