    public function contactUs(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'send_contact_mail') {
            $OtdcMail = User::find(1);
            $toAdmin = $OtdcMail->email;
            $unit_name = 'OTDC HO';
            if (!empty($request->contacthotel)) {
                if ($request->contacthotel == 999) {
                    $toAdmin = 'bbsrtu@gmail.com';
                    $unit_name = 'Bbsr Transport';
                }
                elseif ($request->contacthotel == 9999) {
                    $toAdmin = 'transportunitpuri@gmail.com';
                    $unit_name = 'Puri Transport';
                }
                elseif ($request->contacthotel == 9000) {
                    $toAdmin = 'info@odishatourism.gov.in';
                    $unit_name = 'Chilika Bird Festival';
                }
                else {
                    $MasterHotel = MasterHotel::find($request->contacthotel);
                    if (!empty($MasterHotel) && !empty($MasterHotel->contact_email) && $request->contacthotel != 0) {
                        $toAdmin = $MasterHotel->contact_email;
                        if($MasterHotel->vender_id == 3){
                            $toAdmin = 'otdc@panthanivas.com';
                        }
                        $unit_name = $MasterHotel->name;
                    }
                }
            }
            $phoneno = !empty($request->phoneno) ? $request->phoneno : '';
            // send email to admin
            $AdminTemplete = EmailTemplate::where('ref_code', 'conatctUsToAdmin')->first();
            $Message = str_replace(array("~customername~", "~email~", "~phone~", "~message~", "~site_url~"), array($request->name, $request->email, $phoneno, $request->message, $this->site), $AdminTemplete->source);
            $Subject = $AdminTemplete->subject .' - '. $request->name;

            DB::insert("INSERT INTO `contact_us_table`(`email`, `phone`, `name`, `subject`, `content`, `recipient`, `unit_name`, `created_at`) VALUES ('". $request->email ."', '". $phoneno ."', '". $request->name ."', '". $Subject ."', '". $request->message ."', '". $toAdmin ."', '". $unit_name ."', '". date("y-m-d H:i:s") ."')");
            $from_mail = $request->email;
            $from_name = $request->name;
            $admin = User::where('role', 1)->first();
            /* Mail::to($toAdmin)->bcc($admin->email)->send(new \App\Mail\RegistrationMailUser($Message, $Subject)); */

            // send email to customer
            $UserTemplete = EmailTemplate::where('ref_code', 'conatctUsToUser')->first();
            $Message = str_replace(array("~customername~", "~site_url~", "~website_url~"), array($request->name, $this->site, $this->frontendUrl), $UserTemplete->source);
            $Subject = $UserTemplete->subject;
            Mail::to($request->email)
            ->bcc($admin->email)
            ->send(new \App\Mail\RegistrationMailUser($Message, $Subject));

            $responce['status'] = 1;
            $responce['message'] = 'E-mail sent successfully.';
        }
        elseif ($request->request_type == 'subscribe_email') {
            $validate = Validator::make($request->all(), [
                'email' => 'required|string|email|unique:subscriptions',
            ]);
            if ($validate->fails()) {
                $responce['status'] = 0;

                $errors = $validate->errors();
                if ($errors->has('email')) {
                    $responce['message'] = "You have already subscribed to our website.";
                }
            } else {
                $Subscription = new Subscription(['email' => $request->email]);
                if ($Subscription->save()) {
                    $admin = User::where('role', 1)->first();
                    $Subject = "Email subscription";
                    $Message = "Thank you for subscribe our website.";
                    Mail::to($request->email)
                    ->bcc($admin->email)
                    ->send(new \App\Mail\RegistrationMailUser($Message, $Subject));

                    $responce['status'] = 1;
                    $responce['message'] = 'Thank you for subscribe our website.';
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Unable to subscribe our website.';
                }
            }
        }
        return response()->json($responce);
    }

    public function carBooking(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'book_car') {
            $responce['message'] = '';
            $validate = Validator::make($request->all(), [
                'car_id' => 'required|numeric',
                // 'checkinDate' => 'required|string',
                // 'checkoutDate' => 'required|string',
                'total_cars' => 'required|numeric',
                'totalPrice' => 'required|numeric',
                'service_charge' => 'required',
                'distance' => 'numeric',
                'hour' => 'numeric',
                'halt_hour' => 'numeric',
                'halt_charge' => 'numeric'
            ]);

            if ($validate->fails()) {
                $responce['status'] = 0;
                $errors = $validate->errors();
                if ($errors->has('car_id')) {
                    $responce['message'] = $errors->first('car_id');
                } elseif ($errors->has('checkinDate')) {
                    $responce['message'] = $errors->first('checkinDate');
                } elseif ($errors->has('checkoutDate')) {
                    $responce['message'] = $errors->first('checkoutDate');
                } elseif ($errors->has('total_cars')) {
                    $responce['message'] = $errors->first('total_cars');
                } elseif ($errors->has('totalPrice')) {
                    $responce['message'] = $errors->first('totalPrice');
                } elseif ($errors->has('service_charge')) {
                    $responce['message'] = $errors->first('service_charge');
                } elseif ($errors->has('distance')) {
                    $responce['message'] = $errors->first('distance');
                } elseif ($errors->has('hour')) {
                    $responce['message'] = $errors->first('hour');
                }
            } else {
                $user = $request->user();
                $lastIdData = OrderMaster::orderBy('id', 'desc')->first();
                $lastId = !empty($lastIdData) ? $lastIdData->id + 1 : 1;
                $booking_id = 'OT-'. time() .'-'. $request->vendorId .'-'. $lastId;

                $CarDetails = MasterCar::where(['id'=> $request->car_id, 'status' => 'publish'])->first(); //find($request->car_id);
                $totalPrice = $travel_distance = $travel_hour = $halt_hour = $halt_charge =  0;
                $start_date = $end_date = $start_time = $end_time = $drop_location = $pickup_address = $route =  '';
                $DayBreak = $route = array();
                if (!empty($CarDetails)) {
                    if ($request->rental_type == 'default') {
                        $routes = json_decode($request->route_map, 1);
                        $end = end($routes);
                        $DayBreak[] = array(
                            'pickup_city' => $CarDetails->city,
                            'drop_city' => $end['dropPointCity'],
                            'pickup_point' => $request->pickup_address,
                            'drop_point' => $end['dropPonitDetails'],
                            'date' => [
                                'startDate' => $request->checkinDate,
                                'endDate' => $request->checkoutDate
                            ],
                            'day_km' => $request->distance
                        );
                        $start_date = date("Y-m-d", strtotime($request->checkinDate));
                        $end_date = date("Y-m-d", strtotime($request->checkoutDate));
                        $start_time = date("h:i a", strtotime($request->checkinDate));
                        $end_time = date("h:i a", strtotime($request->checkoutDate));
                        $drop_location = $request->drop_location;
                        $pickup_address = $request->pickup_address;
                    }
                    else {
                        $DayBreak = json_decode($request->day_breakup_details, 1);
                        $length = count($DayBreak);
                        $start_date = date("Y-m-d", strtotime($DayBreak[0]['date']['startDate']));
                        $end_date = date("Y-m-d", strtotime($DayBreak[$length - 1]['date']['endDate']));
                        $start_time = date("h:i a", strtotime($DayBreak[0]['date']['startDate']));
                        $end_time = date("h:i a", strtotime($DayBreak[$length - 1]['date']['endDate']));
                        $drop_location = $DayBreak[$length - 1]['drop_city'];
                        $pickup_address = $DayBreak[0]['pickup_point'];
                    }
                    if ($start_date < date("Y-m-d") || $start_date > $end_date) {
                        $responce['status'] = 0;
                        $responce['message'] = 'Invalid check in date.';
                        return response()->json($responce);
                    }
                    $BlockedVehicle = BlockedVehicle::where('vehicle_id', $CarDetails->id)
                        ->whereBetween('block_date', [$start_date, $end_date])
                        ->get()->toArray();
                    if(!empty($BlockedVehicle)) {
                        $responce['status'] = 0;
                        $responce['message'] = 'Sorry! The vehicle is not available for selected dates.';
                        return response()->json($responce);
                    }
                    $route_map = array();$quantity_array = array();
                    $bookFlag = 1;
                    foreach ($DayBreak as $val) {
                        $difference = strtotime(date("Y-m-d", strtotime($val['date']['endDate']))) - strtotime(date("Y-m-d", strtotime($val['date']['startDate'])));
                        $days = floor($difference / (60 * 60 * 24));
                        $checkinDate = new DateTime($val['date']['startDate']);
                        $checkoutDate = new DateTime($val['date']['endDate']);

                        $interval = $checkinDate->diff($checkoutDate);
                        $totalHour = $interval->format('%h') + ($interval->format('%d') * 24);

                        $cal_day = ($days == 0) ? 1 : $days + 1;
                        for($i = 0; $i < $cal_day; $i++) {
                            $checkDate = date("Y-m-d", strtotime($val['date']['startDate'] .' + '. $i .' days'));
                            $MasterInventory = RentalMasterInventory::where(["date" => $checkDate, "car_id" => $CarDetails->id])->first();
                            if (empty($MasterInventory) || (!empty($MasterInventory) && $MasterInventory->total_available < 1)) {
                                $bookFlag = 0;
                                array_push($quantity_array, date("d-m-Y", strtotime($checkDate)));
                            }
                        }

                        $travel_distance += $val['day_km'];
                        $route_map[] = array(
                            'dropPointCity' => $val['drop_city'],
                            'dropPonitDetails' => $val['drop_point']
                        );

                        $travelHr = ceil($val['day_km'] / $CarDetails->dist_cover_per_hour);
                        $cover_day = $days + 1;
                        $cover_distance_day = $val['day_km'] / $cover_day;
                        if ($cover_distance_day >= $CarDetails->max_distance) {
                            $travel_hour += $totalHour;
                            $totalPriceKm = $val['day_km'] * $CarDetails->price_per_km;
                            $halthour = $days * $CarDetails->halt_hour;
                            $halt_hour += $halthour;
                            $totalHaltPrice = $days * $CarDetails->price_for_halt;
                            $halt_charge += $totalHaltPrice;
                            $detention_hour = $totalHour - $travelHr - $halthour;
                            $detention_charge = 0;
                            if ($detention_hour > 0) {
                                $detention_charge = $detention_hour * $CarDetails->detention_charge_per_hour;
                            }
                            $totalPrice += ($totalPriceKm + $detention_charge + $totalHaltPrice) * $request->total_cars;
                        } else {
                            $extrakm = 0;
                            $totalPriceKm = $travelHr * $CarDetails->price_per_hour;
                            $halthour = $days * $CarDetails->halt_hour;
                            $halt_hour += $halthour;
                            $calculateHr = $totalHour - $halthour;
                            $travel_hour += $calculateHr;
                            if ($val['day_km'] > ($calculateHr * $CarDetails->free_km_per_hour)) {
                                $extrakm = $val['day_km'] - ($calculateHr * $CarDetails->free_km_per_hour);
                            }
                            $extrakm_price = 0;
                            if ($val['day_km'] > $extrakm) {
                                $extrakm_price = $extrakm * $CarDetails->price_per_km;
                            }
                            $totalPriceHr = $calculateHr * $CarDetails->price_per_hour;
                            $totalHaltPrice = $days * $CarDetails->price_for_halt;
                            $halt_charge += $totalHaltPrice;
                            $totalPrice += ($totalPriceHr + $totalHaltPrice + $extrakm_price) * $request->total_cars;
                        }
                    }
                    if ($request->rental_type == 'default') {
                        $route = $request->route_map;
                    } else {
                        $route = json_encode($route_map);
                    }
                    if ($bookFlag == 0) {
                        $responce['status'] = 0;
                        $responce['message'] = 'Sorry! The vehicle is not available on date '. implode(", ", $quantity_array);
                        return response()->json($responce);
                    }
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Sorry! The vehicle is not available for booking.';
                    return response()->json($responce);
                }
                if ($totalPrice != floatval($request->totalPrice)) {
                    $responce['status'] = 0;
                    $responce['message'] = 'Sorry! Price is tampered, please try again.';
                    return response()->json($responce);
                }
                $day_for_guide = str_replace('"', '', $request->no_of_days_for_guide);
                $price_breakup = $request->price_breakup;
                // if ($request->rental_type == 'default') {
                //     $price_breakup = json_encode(array(json_decode($request->price_breakup, 1)));
                // }

                $CarBooking = new CarBooking([
                    'booking_id' => $booking_id,
                    'vendor_id' => $CarDetails->vendor_id,
                    'car_id' => $request->car_id,
                    'total_cars' => $request->total_cars,
                    'start_date' => $start_date,
                    'end_date' => $end_date,
                    'start_time' => $start_time,
                    'end_time' => $end_time,
                    'drop_location' => $drop_location,
                    'pickup_address' => $pickup_address,
                    'route' => $route,
                    'price_breakup' => $price_breakup,
                    'trip_type' => $request->tripType,
                    'rental_type' => $request->rental_type,
                    'day_breakup' => json_encode($DayBreak),
                    'travel_distance' => $travel_distance,
                    'travel_hour' => $travel_hour,
                    'halt_hour' => $halt_hour,
                    'halt_charge' => $halt_charge,
                    'service_charge' => $CarDetails->service_charge,
                    'need_guide' => $request->need_guide,
                    'days_for_guide' => (int)$day_for_guide,
                    'totalPrice' => floatval($request->totalPrice),
                    'user_type' => !empty($user) ? 'registered' : 'guest',
                    'create_user' => !empty($user) ? $user->id : null,
                ]);
                if ($CarBooking->save()) {
                    $responce['status'] = 1;
                    $responce['booking_id'] = $booking_id;
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Unable to book.';
                }
            }
        }
        return response()->json($responce);
    }

    public function sitePages(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'get_page_contents') {
            $responce['message'] = '';
            $PageContents = PageContent::select('title', 'image', 'content')->where(['type' => 'pages', 'slug' => $request->slug])->first();
            if (!empty($PageContents)) {
                $PageContents->image = !empty($PageContents->image) ? $this->site . $PageContents->image : $PageContents->image;
                $responce['status'] = 1;
                $responce['data'] = $PageContents;
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Data not found';
            }
        }
        return response()->json($responce);
    }

    public function orderDetails(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];

        if ($request->request_type == 'get_user_orders') {
            $responce['message'] = '';
            $user = $request->user();
            $order_column = 'id';
            $order_dir = 'DESC';

            $take = $request->pageSize;
            $skip = ($request->pageIndex == 0) ? $request->pageIndex : $request->pageIndex * $take;
            $previousPageIndex = ($request->pageIndex == 0) ? 0 : $request->pageIndex - 1;
            $OrderMasterQuery = OrderMaster::select('service_type', 'vendor_name', 'service_name', 'created_at', 'start_date', 'order_id', 'invoice_id', 'order_type', 'status', 'total_order_price', 'payment_gateway', 'payment_status', 'transaction_id', 'id', 'end_date', 'service_name_id', 'room_request', 'payment_method')
                    ->where(['customer_id' => $user->id]);
            if($request->status == 'all') {
                $OrderMasterQuery->where('status', '!=', 'partially-cancelled');
            } else {
                if ($request->status == 'cancelled') {
                    $OrderMasterQuery->where('status', $request->status); //->orWhere('status', 'partially-cancelled');
                }
                elseif ($request->status == 'upcoming') {
                    $OrderMasterQuery->where('start_date', '>', date("Y-m-d"))->where('status', 'completed');
                    $order_column = 'start_date';
                    $order_dir = 'ASC';
                }
                 else {
                    $OrderMasterQuery->where('status', $request->status);
                }
            }
            if ($request->active != '' && $request->direction != '') {
                $order_column = $request->active;
                $order_dir = $request->direction;
            }
            if ($user->access_type == 'agent') {
                $OrderMasterQuery->where('created_at', '>=', $this->ecoStartDate);
            }
            $orderTotal = clone $OrderMasterQuery->where('service_type', '<>', 'flight')->orderBy($order_column, $order_dir);
            $totalData = $orderTotal->get()->count();
            $OrderMaster = $OrderMasterQuery->skip($skip)
                    ->take($take)
                    ->get();
            if (!empty($OrderMaster)) {
                foreach ($OrderMaster as $key => $value) {
                    $OrderMaster[$key]->paynow = 0;
                    $OrderMaster[$key]->cancel = 0;
                    if ($value->service_type == 'hotel') {
                        $MasterHotel = MasterHotel::find($value->service_name_id);
                        $OrderMaster[$key]->slug = (!empty($MasterHotel)) ? $MasterHotel->slug .'-'. $MasterHotel->id : '';
                        $OrderMaster[$key]->icon_name = $this->site . $MasterHotel->feature_image;
                    } elseif ($value->service_type == 'car') {
                        $MasterCar = MasterCar::find($value->service_name_id);
                        $OrderMaster[$key]->slug = (!empty($MasterCar)) ? $MasterCar->slug .'-'. $MasterCar->id : '';
                        $OrderMaster[$key]->icon_name = $this->site . $MasterCar->feature_image;
                    } elseif ($value->service_type == 'caravan') {
                        $MasterCar = MasterCaravan::find($value->service_name_id);
                        $OrderMaster[$key]->slug = (!empty($MasterCar)) ? $MasterCar->slug .'-'. $MasterCar->id : '';
                        $OrderMaster[$key]->icon_name = $this->site . $MasterCar->feature_image;
                    } elseif ($value->service_type == 'tour') {
                        $Tour = Tour::find($value->service_name_id);
                        $OrderMaster[$key]->slug = (!empty($Tour)) ? $Tour->slug .'-'. $Tour->id : '';
                        $OrderMaster[$key]->icon_name = $this->site . $Tour->feature_image;
                    } elseif ($value->service_type == 'ticketing') {
                        $Ticket = Ticket::find($value->service_name_id);
                        $OrderMaster[$key]->slug = (!empty($Ticket)) ? $Ticket->slug .'-'. $Ticket->id : '';
                        $OrderMaster[$key]->icon_name = $this->site . $Ticket->feature_image;
                    } elseif ($value->service_type == 'merchant') {
                        $Vendor_list = User::where('role', 2)->pluck('company', 'id')->toArray();
                        $Items = json_decode($value->room_request, 1);
                        $temp = array();
                        foreach ($Items as $val) {
                            array_push($temp, $Vendor_list[$val['vendor_id']]);
                        }
                        $OrderMaster[$key]->vendor_name = implode(', ', array_unique($temp));
                    }
                    $value->transaction_id = !empty($value->transaction_id) ? $value->transaction_id : 'N/A';
                    $value->start_date = date("M d Y", strtotime($value->start_date));
                    $value->end_date = !empty($value->end_date) ? date("M d Y", strtotime($value->end_date)) : '';
                    $value->service_type = strtoupper($value->service_type);
                    $value->payment_method = !empty($value->payment_method) ? $value->payment_method : 'N/A';

                    $datetime1 = new DateTime();
                    $datetime2 = new DateTime(date("Y-m-d H:i:s", strtotime($value->created_at)));
                    $interval = $datetime2->diff($datetime1)->format('%h');
                    $intervaldays = $datetime2->diff($datetime1)->format('%days');
                    if ($value->status == 'pending' && $value->payment_status != 'success' && $intervaldays == 0 && $interval <= 2) {
                        $OrderMaster[$key]->paynow = 0;
                    }
                    $PCOrders = OrderMaster::where('id', '!=', $value->id)->where('invoice_id', $value->invoice_id)->count();
                    if ($value->status != 'cancelled' && $value->status != 'partially-cancelled' && $value->status != 'pending' && date("Y-m-d", strtotime($value->start_date)) >= date("Y-m-d") && $PCOrders == 0) {
                        if ($value->service_type != 'RESTAURANT' && $value->service_type != 'MERCHANT') {
                            $OrderMaster[$key]->cancel = 1;
                        }
                    }
                    $value->status = strtoupper($value->status);
                }
                $length = $totalData;
                $responce['pageIndex'] = $skip;
                $responce['pageSize'] = $take;
                $responce['length'] = $length;
                $responce['totalPage'] = ceil($totalData/$take);
                $responce['previousPageIndex'] = $previousPageIndex;
                $responce['status'] = 1;
                $responce['data'] = $OrderMaster;
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'No orders found';
            }
        }
        elseif ($request->request_type == 'get_user_orders_by_id') {
            $responce['message'] = '';
            $user = $request->user();
            $OrderMaster = OrderMaster::where('ID', $request->ID)->where('service_type', '<>', 'flight')->first();
            if (!empty($OrderMaster)) {
                $OrderData = array();
                $UserData = array();
                $OrderData['service_name'] = $OrderMaster->service_name;
                $OrderData['service_name_id'] = $OrderMaster->service_name_id;
                if ($OrderMaster->service_type == 'hotel') {
                    $Coupon_percent = $sgst = $cgst = 0;
                    if ($OrderMaster->tax_amount > 0) {
                        $GstData = GstDetail::pluck('value', 'name');
                        $cgst = $GstData['CGST'];
                        $sgst = $GstData['SGST'];
                    }
                    if ($OrderMaster->coupon_amount > 0) {
                        $Coupon = Coupon::where('coupon_code', $OrderMaster->coupon_code)->first();
                        if (!empty($Coupon)) {
                            $Coupon_percent = $Coupon->coupon_amount;
                        }
                    }
                    $OrderDeatil = OrderDetail::select('service_item_name', DB::raw('sum(unit_total_price) as grossPrice'), DB::raw('sum(total_room_price) as totalRoomPrice'), DB::raw('sum(tax_amount) as totTax'))
                            ->where('order_master_id', $OrderMaster->id)
                            ->groupBy('service_item_id')
                            ->get();
                    $room_details = array();
                    foreach ($OrderDeatil as $value) {
                        $discount = $value->grossPrice * ($Coupon_percent / 100);
                        $afterDiscount = $value->grossPrice - $discount;
                        $cgstPrice = $sgstPrice = 0;
                        if ($cgst > 0 || $sgst > 0) {
                            $cgstPrice = ($value->totTax / ($cgst + $sgst)) * $cgst;
                            $sgstPrice = ($value->totTax / ($cgst + $sgst)) * $sgst;
                        }
                        $totalRoomPrice = $afterDiscount + $cgstPrice + $sgstPrice;

                        $room_details[] = array(
                            'room_name' => $value->service_item_name,
                            'gross_price' => number_format($value->grossPrice, 2),
                            'discount' => number_format($discount, 2),
                            'after_discount' => number_format($afterDiscount, 2),
                            'cgst' => number_format($cgstPrice, 2),
                            'sgst' => number_format($sgstPrice, 2),
                            'total_room_price' => number_format($totalRoomPrice, 2)
                        );
                    }
                    $OrderData['room_details'] = $room_details;
                    $room_html = '';
                    $room_details = json_decode($OrderMaster->room_details, 1);
                    foreach ($room_details as $value) {
                        $room_html .= $value['quantity'] .' '. $value['room_name'] .', ';
                    }
                    $room_html = trim($room_html, ', ');
                    $OrderData['room_types'] = '['. $room_html .']';
                    $OrderData['check_date'] = '['. date("d M Y", strtotime($OrderMaster->start_date)) .' - '. date("d M Y", strtotime($OrderMaster->end_date)) .']';
                    $OrderData['service_charge'] = $OrderMaster->service_charge;
                    $OrderData['total_adult'] = $OrderMaster->total_adults;
                    $OrderData['total_child'] = $OrderMaster->total_child;
                    $OrderData['need_pickup'] = $OrderMaster->need_pickup;
                    $OrderData['expected_arrival_time'] = $OrderMaster->expected_arrival_time;
                }
                elseif ($OrderMaster->service_type == 'car') {
                    $OrderData['quantity'] = $OrderMaster->service_quantity;
                    $OrderData['check_date'] = '['. date("d M Y", strtotime($OrderMaster->start_date)) .' - '. date("d M Y", strtotime($OrderMaster->end_date)) .']';
                    $OrderData['drop_location'] = $OrderMaster->drop_location;
                    $OrderData['pickup_address'] = $OrderMaster->pickup_address;
                    $OrderData['route_map'] = json_decode($OrderMaster->route, 1);


                    $OrderDetail = OrderDetail::where('order_master_id', $OrderMaster->id)->get();
                    $room_details = array();
                    foreach ($OrderDetail as $value) {
                        $room_details[] = array(
                            'pickup' => $value->pickup_address .', '. $value->pickup_city,
                            'drop' => $value->drop_address .', '. $value->drop_city,
                            'check_date' => date("d M Y h:i a", strtotime($value->start_date .' '. $value->start_time)) .' - <br>'. date("d M Y h:i a", strtotime($value->end_date .' '. $value->end_time)),
                            'distance' => $value->distance,
                            'sub_total' => number_format($value->unit_total_price - $value->coupon_amount, 2),
                            'cgst' => number_format($value->tax_amount / 2, 2),
                            'sgst' => number_format($value->tax_amount / 2, 2),
                            'total_price' => number_format($value->total_room_price, 2)
                        );
                    }
                    $OrderData['room_details'] = $room_details;
                    $OrderData['guide_charge'] = $OrderMaster->guide_charge;
                    $OrderData['days_for_guide'] = $OrderMaster->days_for_guide;
                }elseif ($OrderMaster->service_type == 'caravan') {
                    $OrderData['quantity'] = $OrderMaster->service_quantity;
                    $OrderData['check_date'] = '['. date("d M Y", strtotime($OrderMaster->start_date)) .' - '. date("d M Y", strtotime($OrderMaster->end_date)) .']';
                    $OrderData['drop_location'] = $OrderMaster->drop_location;
                    $OrderData['pickup_address'] = $OrderMaster->pickup_address;
                    $OrderData['route_map'] = json_decode($OrderMaster->route, 1);


                    $OrderDetail = OrderDetail::where('order_master_id', $OrderMaster->id)->get();
                    $room_details = array();
                    foreach ($OrderDetail as $value) {
                        $room_details[] = array(
                            'pickup' => $value->pickup_address .', '. $value->pickup_city,
                            'drop' => $value->drop_address .', '. $value->drop_city,
                            'check_date' => date("d M Y h:i a", strtotime($value->start_date .' '. $value->start_time)) .' - <br>'. date("d M Y h:i a", strtotime($value->end_date .' '. $value->end_time)),
                            'distance' => $value->distance,
                            'sub_total' => number_format($value->unit_total_price - $value->coupon_amount, 2),
                            'cgst' => number_format($value->tax_amount / 2, 2),
                            'sgst' => number_format($value->tax_amount / 2, 2),
                            'total_price' => number_format($value->total_room_price, 2)
                        );
                    }
                    $OrderData['room_details'] = $room_details;
                    $OrderData['guide_charge'] = $OrderMaster->guide_charge;
                    $OrderData['days_for_guide'] = $OrderMaster->days_for_guide;
                }
                elseif ($OrderMaster->service_type == 'tour') {

                    $OrderData['category'] = $OrderMaster->service_category;
                    if ($OrderMaster->service_category == 'sight seeing') {
                        $OrderData['total_tickets'] = $OrderMaster->total_guests;
                        $OrderData['check_date'] = '['. date("M d Y", strtotime($OrderMaster->start_date)) .']';
                    } else {
                        $OrderData['adult'] = $OrderMaster->total_adults;
                        $OrderData['child'] = $OrderMaster->total_child;
                        $OrderData['check_date'] = '['. date("M d Y", strtotime($OrderMaster->start_date)) .' - '. date("M d Y", strtotime($OrderMaster->end_date)) .']';
                        $OrderDetail = OrderDetail::select('service_name', 'start_date', 'end_date', 'service_item_name', DB::raw('SUM(service_item_quantity)as totQty'))
                                ->where('order_master_id', $OrderMaster->id)
                                ->groupBy('start_date')
                                ->get();
                        $room_details = array();
                        foreach ($OrderDetail as $value) {
                            $room_details[] = array(
                                'hotel_name' => $value->service_name,
                                'check_date' => date("M d Y", strtotime($value->start_date)) .' - '. date("M d Y", strtotime($value->end_date)),
                                'room_name' => $value->service_item_name,
                                'quantity' => $value->totQty
                            );
                        }
                        $OrderData['room_details'] = $room_details;
                    }
                }
                elseif ($OrderMaster->service_type == 'ticketing') {
                    if ($OrderMaster->vendor_id == 6048 || $OrderMaster->vendor_id == 268) {
                        $OrderData['service_name'] = $OrderMaster->service_name .' ('. $OrderMaster->gate_number .')';
                    }
                    $OrderData['category'] = $OrderMaster->service_category;
                    $OrderData['check_date'] = date("M d Y", strtotime($OrderMaster->start_date));
                    $OrderData['adult'] = $OrderMaster->total_adults;
                    $OrderData['child'] = $OrderMaster->total_child;
                    if ($OrderMaster->start_time) {
                        $OrderData['duration'] = '['. $OrderMaster->start_time .' - '. $OrderMaster->end_time .']';
                    } else {
                        $OrderData['duration'] = 'All day';
                    }
                    $extra_services = json_decode($OrderMaster->room_details, 2);
                    $occupied_service = array();
                    foreach ($extra_services as $val) {
                        $occupied_service[] = array(
                            'name' => $val['name'],
                            'quantity' => $val['quantity'],
                            'price' => number_format($val['price'] * $val['quantity'], 2)
                        );
                    }
                    $OrderData['room_details'] = $occupied_service;
                }
                elseif ($OrderMaster->service_type == 'restaurant') {
                    $OrderDeatil = OrderDetail::where('order_master_id', $OrderMaster->id)->get();
                    $food_details = array();
                    foreach ($OrderDeatil as $value) {
                        $food_details[] = array(
                            'food_name' => $value->service_item_name,
                            'food_qty' => $value->service_item_quantity,
                            'unit_price' => number_format($value->service_item_price, 2),
                            'total_price' => number_format($value->total_room_price, 2)
                        );
                    }
                    $OrderData['food_details'] = $food_details;
                }
                elseif ($OrderMaster->service_type == 'merchant') {
                    $OrderDeatil = OrderDetail::where('order_master_id', $OrderMaster->id)->get();
                    $item_details = array();
                    foreach ($OrderDeatil as $value) {
                        $Vendor = User::find($value->vendor_id);
                        $item_details[] = array(
                            'vendor_id' => $Vendor->company,
                            'item_name' => $value->service_item_name,
                            'item_qty' => $value->service_item_quantity,
                            'unit_price' => number_format($value->service_item_price, 2),
                            'total_price' => number_format($value->total_room_price, 2)
                        );
                    }
                    $OrderData['item_details'] = $item_details;
                }
                $OrderData['status'] = $OrderMaster->status;
                $OrderData['payment_gateway'] = $OrderMaster->payment_gateway;
                $OrderData['payment_method'] = !empty($OrderMaster->payment_method) ? $OrderMaster->payment_method : 'N/A';
                $OrderData['qr_code'] = !empty($OrderMaster->qr_code) ? $this->site . $OrderMaster->qr_code : '';
                $OrderData['invoice_id'] = $OrderMaster->invoice_id;
                $OrderData['order_id'] = $OrderMaster->order_id;
                $OrderData['booking_date'] = date("d M Y h:i a", strtotime($OrderMaster->created_at));
                $OrderData['orderId'] = $OrderMaster->id;

                $OrderData['total_amount'] = $OrderMaster->total_order_price;
                $OrderData['total_service_price'] = $OrderMaster->total_service_price;
                $OrderData['sub_total_price'] = $OrderMaster->sub_total_price;
                $OrderData['gst'] = $OrderMaster->tax_amount;
                $OrderData['discount_amount'] = $OrderMaster->coupon_amount;
                $OrderData['coupon_name'] = !empty($OrderMaster->coupon_name) ? $OrderMaster->coupon_name : '';
                $OrderData['payment_status'] = $OrderMaster->payment_status;
                $OrderData['txn_id'] = !empty($OrderMaster->transaction_id) ? $OrderMaster->transaction_id : 'N/A';
                $OrderData['confirm_voucher'] = $OrderMaster->confimation_voucher;

                $UserData['name'] = $OrderMaster->customer_name;
                $UserData['customer_email'] = $OrderMaster->customer_email;
                $UserData['customer_phone'] = $OrderMaster->customer_phone;
                $UserData['customer_address1'] = $OrderMaster->customer_address1;
                $UserData['customer_address2'] = $OrderMaster->customer_address2;
                $UserData['customer_city'] = $OrderMaster->customer_city;
                $UserData['customer_state'] = $OrderMaster->customer_state;
                $UserData['customer_country'] = $OrderMaster->customer_country;
                $UserData['customer_zipcode'] = $OrderMaster->customer_zipcode;
                $UserData['customer_notes'] = $OrderMaster->customer_notes;

                $responce['status'] = 1;
                $responce['service_type'] = $OrderMaster->service_type;
                $responce['user_data'] = $UserData;
                $responce['order_data'] = $OrderData;
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Invalid Order id.';
            }
        }
        return response()->json($responce);
    }

    public function tourDetails(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'get_tour_list') {
            $responce['message'] = '';
            $sort_column = 'updated_at';
            $sort_direction = 'desc';

            $TourQuery = DB::table('tours')
                    ->select('id', 'name', 'slug', 'feature_image', 'city', 'single_share_price', 'double_share_price', 'triple_share_price', 'review_score', 'review_count', 'duration_start', 'duration_start_text', 'duration_end', 'duration_end_text', 'category', 'show_price')
                    ->where('status', 'publish')->where('vendor_id', '!=', '58672');
            if(! isset($request->hide_from_mobile)) {
                $TourQuery->whereNotIn('id', [32, 33, 68]);
            }
            if(!empty($request->property)) {
                $property = json_decode($request->property, 1);
                foreach ($property as $terms) {
                    $TourQuery->where('property_slug', 'like', '%'. $terms .'%');
                }
            }
            if(!empty($request->review_score)) {
                $reviews = json_decode($request->review_score, 1);
                $TourQuery->whereIn('review_score', $reviews);
            }
            if(!empty($request->tour_type) && $request->tour_type != 'special tour') {
                $TourQuery->where('category', $request->tour_type);
            }
            if(!empty($request->tour_type) && $request->tour_type == 'special tour') {
                $TourQuery->where('is_special_tour', 1);
            }
            if(!empty($request->vendorId)) {
                $vendors = json_decode($request->vendorId, 1);
                $TourQuery->whereIn('vendor_id', $vendors);
            }
            if($request->startPrice != '' && $request->endPrice != '') {
                $TourQuery->whereBetween('single_share_price', [$request->startPrice, $request->endPrice]);
            }
            if ($request->city != '') {
                $TourQuery->where('city', 'like', '%'. $request->city .'%');
            }
            if (!empty($request->prop_name)) {
                $TourQuery->where('name', 'like', '%'. $request->prop_name .'%');
            }
            if ($request->sortColumn != '' && $request->direction != '') {
                $sort_column = $request->sortColumn;
                $sort_direction = $request->direction;
            }
            $TourQuery->orderBy($sort_column, $sort_direction);
            $take = 9;
            $skip = ($request->pageno == 0) ? $request->pageno : $request->pageno * $take;
            $totalData = $TourQuery->count();

            $TourData = $TourQuery->skip($skip)->take($take)->get()->toArray();

            if (!empty($TourData)) {
                $Package = array();
                foreach ($TourData as $key => $value) {
                    $TourData[$key]->feature_image = $this->site . $value->feature_image;
                    $duration = '';
                    if ($TourData[$key]->category == 'package') {
                        $tmp = ((int)$TourData[$key]->duration_start > 1) ? $TourData[$key]->duration_start .' '. $TourData[$key]->duration_start_text : $TourData[$key]->duration_start .' Night';
                        $duration = $tmp .' '. $TourData[$key]->duration_end .' '. $TourData[$key]->duration_end_text;
                    } else {
                        $duration = date("h:i", strtotime($TourData[$key]->duration_start)) .' '. strtoupper($TourData[$key]->duration_start_text) .'-'. date("h:i", strtotime($TourData[$key]->duration_end)) .' '. strtoupper($TourData[$key]->duration_end_text);
                    }
                    $TourData[$key]->duration = $duration;
                    if($request->tour_type == 'package') {
                        $dataArray = !empty($Package[$value->city]) ? $Package[$value->city] : [];
                        array_push($dataArray, $value);
                        $Package[$value->city] = $dataArray;
                    }
                    $value->review_score = !empty($value->review_score) ? round($value->review_score, 2) : 0;
                    $value->review_count = !empty($value->review_count) ? $value->review_count : 0;
                    $value->single_share_price = number_format($value->single_share_price, 0);
                    $value->double_share_price = (!empty($value->double_share_price)) ? number_format($value->double_share_price, 0) : 0;
                    $value->triple_share_price = (!empty($value->triple_share_price)) ? number_format($value->triple_share_price, 0) : 0;
                }

                $RelatedTour = array();
                if (!empty(isset($request->relatedKey) && !empty($request->relatedKey))) {
                    $RelatedTour = DB::table('tours')
                        ->select('id', 'name', 'slug', 'feature_image', 'city', 'single_share_price', 'double_share_price', 'triple_share_price', 'review_score', 'review_count', 'duration_start', 'duration_start_text', 'duration_end', 'duration_end_text', 'category', 'show_price')
                        ->where('status', 'publish')
                        ->where('name', '<>', $request->prop_name)
                        ->where('name', 'like', '%'. $request->relatedKey .'%')
                        ->get()->toArray();
                    if (!empty($RelatedTour)) {
                        foreach ($RelatedTour as $key => $value) {
                            $RelatedTour[$key]->feature_image = $this->site . $value->feature_image;
                            $duration = '';
                            if ($RelatedTour[$key]->category == 'package') {
                                $tmp = ((int)$RelatedTour[$key]->duration_start > 1) ? $RelatedTour[$key]->duration_start .' '. $RelatedTour[$key]->duration_start_text : $RelatedTour[$key]->duration_start .' Night';
                                $duration = $tmp .' '. $RelatedTour[$key]->duration_end .' '. $RelatedTour[$key]->duration_end_text;
                            } else {
                                $duration = $RelatedTour[$key]->duration_start .' '. strtoupper($RelatedTour[$key]->duration_start_text) .'-'. $RelatedTour[$key]->duration_end .' '. strtoupper($RelatedTour[$key]->duration_end_text);
                            }
                            $RelatedTour[$key]->duration = $duration;
                            $value->review_score = !empty($value->review_score) ? round($value->review_score, 2) : 0;
                            $value->review_count = !empty($value->review_count) ? $value->review_count : 0;
                            $value->single_share_price = number_format($value->single_share_price, 0);
                            $value->double_share_price = (!empty($value->double_share_price)) ? number_format($value->double_share_price, 0) : 0;
                            $value->triple_share_price = (!empty($value->triple_share_price)) ? number_format($value->triple_share_price, 0) : 0;
                        }
                    }
                }

                $responce['status'] = 1;
                $responce['totalPage'] = ceil($totalData/$take);
                $responce['length'] = $totalData;
                $responce['data'] = ($request->tour_type == 'package') ? $Package : $TourData;
                $responce['data_length'] = count($TourData);
                $responce['related_data'] = $RelatedTour;
            } else {
                $responce['status'] = 0;
                $responce['data'] = [];
                $responce['data_length'] = 0;
            }
            // $responce['banner_image'] = $this->site . 'images/tours/banner-search.jpg';
        }
        elseif ($request->request_type == 'get_tour_details') {
            $responce['message'] = '';
            if (isset($request->slug)) {
                $TourData = Tour::where(['slug' => $request->slug, 'status' => 'publish'])->first();
            } else {
                $TourData = Tour::where(['id' => $request->tourId, 'status' => 'publish'])->first();
            }
            if (!empty($TourData)) {
                $UserData = User::find($TourData->vendor_id);
                $TourData->vendor_name = $UserData->company;
                $TourData->vendor_email = $UserData->email;
                $TourData->vendor_image = $this->site . $UserData->photo;
                $TourData->member_since = date("M Y", strtotime($UserData->created_at));

                $vendor_profile = VendorProfile::where('vendor_id', $TourData->vendor_id)->first();
                if (!empty($vendor_profile)) {
                    $TourData->vendor_profile = $vendor_profile->profile_type;
                    if ($vendor_profile->profile_type == 'own') {
                        $TourData->vendor_slug = !empty($vendor_profile->profile_url) ? $vendor_profile->profile_url : 'javascript:void(0)';
                    } else {
                        $TourData->vendor_slug = $vendor_profile->slug;
                    }
                } else {
                    $TourData->vendor_slug = '';
                }
                //$TourData->startdays = 1;
                $TourData->startdays = $TourData->days_from_start_date;
                if (!empty($TourData->start_date)) {
                    if ($TourData->start_date > date("Y-m-d")) {
                        $differ = strtotime($TourData->start_date) - strtotime(date("Y-m-d"));
                        $day = round($differ / (60 * 60 * 24));
                        //$TourData->startdays = ($day > 0) ? $day : 1;
                        $TourData->startdays = ($day > 0) ? $day : $TourData->days_from_start_date;
                    }
                }



                $TourData->feature_image = !empty($TourData->feature_image) ? $this->site . $TourData->feature_image : $TourData->feature_image;
                $TourData->banner_image = !empty($TourData->banner_image) ? $this->site . $TourData->banner_image : $TourData->banner_image;
                if (!empty($TourData->gallery)) {
                    $hotel_gallery = json_decode($TourData->gallery);
                    $TourData->gallery = array_map(function($val) { return $this->site . $val; } , $hotel_gallery);
                }
                $Property = !empty($TourData->property) ? json_decode($TourData->property, 1) : [];
                $PropertyApp = array();
                if (!empty($Property)) {
                    foreach ($Property as $key => $parent) {
                        foreach ($parent as $ckey => $val) {
                            $Property[$key][$ckey]['icon'] = !empty($val['icon']) ? $this->site . $val['icon'] : '';
                        }
                        $PropertyApp[] = array(
                            'name' => $key,
                            'data' => $Property[$key]
                        );
                    }
                }
                $TourData->property = $Property;
                $TourData->property_app = $PropertyApp;

                $TourData->faqs = !empty($TourData->faqs) ? json_decode($TourData->faqs, 1) : $TourData->faqs;
                // $TourData->property = !empty($TourData->property) ? json_decode($TourData->property, 1) : $TourData->property;
                $TourData->include = !empty($TourData->include) ? json_decode($TourData->include, 1) : $TourData->include;
                $TourData->exclude = !empty($TourData->exclude) ? json_decode($TourData->exclude, 1) : $TourData->exclude;
                $Itinerary = !empty($TourData->itinerary) ? json_decode($TourData->itinerary, 1) : [];
                $TourData->itinerary = $Itinerary;
                $TourData->route_map = json_decode($TourData->route_map, 1);
                $duration = '';
                if ($TourData->category == 'package') {
                    $tmp = ((int)$TourData->duration_start > 1) ? $TourData->duration_start .' '. $TourData->duration_start_text : $TourData->duration_start .' Night';
                    $duration = $tmp .' '. $TourData->duration_end .' '. $TourData->duration_end_text;
                } else {
                    $duration = date("h:i", strtotime($TourData->duration_start)) .' '. strtoupper($TourData->duration_start_text) .'-'. date("h:i", strtotime($TourData->duration_end)) .' '. strtoupper($TourData->duration_end_text);
                }
                $TourData->duration = $duration;

                if ($request->checkinDate != '') {
                    $BlockData = TourAvailability::where(['tour_id' => $TourData->id, 'block_date' => date('Y-m-d', strtotime($request->checkinDate))])->first();
                    if (!empty($BlockData)) {
                        $responce['message'] = 'Booking not available for this date. Please choose different date!';
                        $TourData->max_people = 0;
                    } else {
                        if ($TourData->category == 'package') {
                            $checkoutDate = date('Y-m-d', strtotime($request->checkinDate. ' + '. ($TourData->duration_end - 1) .' days'));
                            $difference = strtotime($checkoutDate) - strtotime($request->checkinDate);
                            $days = round($difference / (60 * 60 * 24));
                            $i = 0;
                            foreach ($Itinerary as $itnrs) {
                                if($itnrs['hotel'] != 'other' && $itnrs['hotel'] != 'No Accommodation') {
                                    $MaterHotel = MasterHotel::where(['id' => $itnrs['hotel'], 'status' => 'publish'])->first();
                                    if (!empty($MaterHotel)) {
                                        // for ($i = 0; $i < $days; $i++) {
                                            $checkDate = date("Y-m-d", strtotime($request->checkinDate . ' + ' . $i . ' days'));
                                            $HotelRoom = HotelRoom::where(['id' => $itnrs['hotelRoom'], 'status' => 'publish'])->first();
                                            if (!empty($HotelRoom)) {
                                                $BlockedHotel = BlockedHotel::where('hotel_id', $MaterHotel->id)
                                                                ->where('block_date', $checkDate)
                                                                ->whereRaw("find_in_set('". $HotelRoom->id ."',rooms)")
                                                                ->first();
                                                if (!empty($BlockedHotel)) {
                                                    $responce['message'] = 'Booking not available for this date. Please choose different date!';
                                                    $TourData->max_people = 0;
                                                } else {
                                                    $MasterInventory = MasterInventory::where(["date" => $checkDate, 'room_id' => $itnrs['hotelRoom']])->first();
                                                    $room_qty = (!empty($MasterInventory->total_available)) ? $MasterInventory->total_available : 0;
                                                    if ($room_qty < 1) {
                                                        $responce['message'] = 'Booking not available for this date. Please choose different date!';
                                                        $TourData->max_people = 0;
                                                    }
                                                }
                                            } else {
                                                $responce['message'] = 'Booking not available for this date. Please choose different date!';
                                                $TourData->max_people = 0;
                                            }
                                        // }
                                    } else {
                                        $responce['message'] = 'Booking not available for this date. Please choose different date!';
                                        $TourData->max_people = 0;
                                    }
                                }
                                $i++;
                            }
                        }
                        $OrderDetails = DB::table('order_masters')
                                ->select(DB::raw('SUM(total_guests) as totQty'))
                                ->where('service_name_id', $TourData->id)
                                ->where('service_type', 'tour')
                                ->where('start_date', date("Y-m-d", strtotime($request->checkinDate)))
                                ->where('status', '!=', 'cancelled')
                                ->first();

                        if ($OrderDetails->totQty > 0 && ($TourData->vendor_id != 1 || $TourData->category != 'package')) {
                            $TourData->max_people = $TourData->max_people - $OrderDetails->totQty;
                            if ($TourData->max_people < 1) {
                                $responce['message'] = 'Booking not available for this date. Please choose different date!';
                                $TourData->max_people = 0;
                            }
                        }
                        if ($TourData->category == 'sight seeing') {
                            $weekDay = date("l", strtotime($request->checkinDate));
                            $TourData->not_available = !empty($TourData->not_available) ? json_decode($TourData->not_available, 1) : [];
                            if (in_array($weekDay, $TourData->not_available)) {
                                $responce['message'] = 'Tour is not available on '. $weekDay .'. Please choose different date!';
                                $TourData->max_people = 0;
                            }
                            $SightSeenPricing = SightSeenPricing::where(['tour_id' => $TourData->id, 'start_date' => date("Y-m-d", strtotime($request->checkinDate))])->first();
                            if (!empty($SightSeenPricing)) {
                                $discount_amount = $SightSeenPricing->offer_percentage; //$TourData->single_share_price * ($SightSeenPricing->offer_percentage / 100);
                                if ($SightSeenPricing->offer_type == 'plus') {
                                    $TourData->single_share_price = round($TourData->single_share_price + $discount_amount);
                                } else {
                                    $TourData->single_share_price = round($TourData->single_share_price - $discount_amount);
                                }
                            }
                        }
                    }
                    $TourData->max_people_per_booking = $TourData->max_people;
                    if ($TourData->id == '34' || $TourData->id == '35' || $TourData->id == '36') {
                        $TourData->end_date = "2025-06-27";
                        $TourData->max_people_per_booking = 2;
                    }
                    elseif ($TourData->id == '32' || $TourData->id == '33' || $TourData->id == '68') {
                        $TourData->end_date = "2025-12-05";
                        // $TourData->max_people_per_booking = 2;
                    }elseif ($TourData->id == '57' || $TourData->id == '58' || $TourData->id == '59') {
                        $TourData->end_date = "2025-01-13";
                        // $TourData->max_people_per_booking = 2;
                    }
                    // if (isset($responce['message'])) {
                    //     $TourData->max_people = 0;
                    // }
                }
                $responce['status'] = 1;
                $responce['data'] = $TourData;
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Tour not available';
            }
        }
        elseif ($request->request_type == 'check_tour_availability') {
            $responce['message'] = '';
            $TourData = Tour::find($request->tourId);
            if (!empty($TourData)) {
                if ($request->checkinDate != '') {
                    $BlockData = TourAvailability::where(['tour_id' => $TourData->id, 'block_date' => date('Y-m-d', strtotime($request->checkinDate))])->first();
                    if (!empty($BlockData)) {
                        $responce['message'] = 'Booking not available for this date. Please choose different date!';
                        $TourData->max_people = 0;
                    } else {
                        if ($TourData->category == 'package') {
                            $Itinerary = !empty($TourData->itinerary) ? json_decode($TourData->itinerary, 1) : [];
                            $checkoutDate = date('Y-m-d', strtotime($request->checkinDate. ' + '. ($TourData->duration_end - 1) .' days'));
                            $difference = strtotime($checkoutDate) - strtotime($request->checkinDate);
                            $days = round($difference / (60 * 60 * 24));
                            $check_room = ($request->adult > 3) ? 2 : 1;
                            $i = 0;
                            foreach ($Itinerary as $itnrs) {
                                if($itnrs['hotel'] != 'other' && $itnrs['hotel'] != 'No Accommodation') {
                                    $MaterHotel = MasterHotel::where(['id' => $itnrs['hotel'], 'status' => 'publish'])->first();
                                    if (!empty($MaterHotel)) {
                                        // for ($i = 0; $i < $days; $i++) {
                                            $checkDate = date("Y-m-d", strtotime($request->checkinDate . ' + ' . $i . ' days'));
                                            $HotelRoom = HotelRoom::where(['id' => $itnrs['hotelRoom'], 'status' => 'publish'])->first();
                                            if (!empty($HotelRoom)) {
                                                $BlockedHotel = BlockedHotel::where('hotel_id', $MaterHotel->id)
                                                                ->where('block_date', $checkDate)
                                                                ->whereRaw("find_in_set('". $HotelRoom->id ."',rooms)")
                                                                ->first();
                                                if (!empty($BlockedHotel)) {
                                                    $responce['message'] = 'Booking not available for this date. Please choose different date!';
                                                    $TourData->max_people = 0;
                                                } else {
                                                    $MasterInventory = MasterInventory::where(["date" => $checkDate, 'room_id' => $itnrs['hotelRoom']])->first();
                                                    $room_qty = (!empty($MasterInventory->total_available)) ? $MasterInventory->total_available : 0;
                                                    if ($room_qty < $check_room) {
                                                        $responce['message'] = 'Booking not available for this date. Please choose different date!';
                                                        $TourData->max_people = 0;
                                                    }
                                                }
                                            } else {
                                                $responce['message'] = 'Booking not available for this date. Please choose different date!';
                                                $TourData->max_people = 0;
                                            }
                                        // }
                                    } else {
                                        $responce['message'] = 'Booking not available for this date. Please choose different date!';
                                        $TourData->max_people = 0;
                                    }
                                }
                                $i++;
                            }

                        }
                        $booked_data = array();
                        $OrderDetails = DB::table('order_masters')
                                ->select(DB::raw('SUM(total_guests) as totQty'))
                                ->where('service_name_id', $TourData->id)
                                ->where('service_type', 'tour')
                                ->where('start_date', date("Y-m-d", strtotime($request->checkinDate)))
                                ->where('status', '!=', 'cancelled')
                                ->first();
                        if ($OrderDetails->totQty > 0 && ($TourData->vendor_id != 1 || $TourData->category != 'package')) {
                            $TourData->max_people = $TourData->max_people - $OrderDetails->totQty;
                        }
                        if ($TourData->max_people < 1) {
                            $responce['message'] = 'Booking not available for this date. Please choose different date!';
                            $TourData->max_people = 0;
                        }
                    }
                    if ($TourData->category == 'sight seeing') {
                        $weekDay = date("l", strtotime($request->checkinDate));
                        $TourData->not_available = !empty($TourData->not_available) ? json_decode($TourData->not_available, 1) : [];
                        if (in_array($weekDay, $TourData->not_available)) {
                            $responce['message'] = 'Tour is not available on '. $weekDay .'. Please choose different date!';
                            $TourData->max_people = 0;
                        }
                        $SightSeenPricing = SightSeenPricing::where(['tour_id' => $TourData->id, 'start_date' => date("Y-m-d", strtotime($request->checkinDate))])->first();
                        if (!empty($SightSeenPricing)) {
                            $discount_amount = $SightSeenPricing->offer_percentage; // $TourData->single_share_price * ($SightSeenPricing->offer_percentage / 100);
                            if ($SightSeenPricing->offer_type == 'plus') {
                                $TourData->single_share_price = round($TourData->single_share_price + $discount_amount);
                            } else {
                                $TourData->single_share_price = round($TourData->single_share_price - $discount_amount);
                            }
                        }
                        $responce['price'] = $TourData->single_share_price;
                    }
                    $TourData->max_people_per_booking = $TourData->max_people;
                    if ($TourData->id == '34' || $TourData->id == '35' || $TourData->id == '36') {
                        $TourData->end_date = "2025-06-27";
                        $TourData->max_people_per_booking = 2;
                    }elseif ($TourData->id == '57' || $TourData->id == '58' || $TourData->id == '59') {
                        $TourData->end_date = "2025-01-13";
                        //$TourData->max_people_per_booking = 6;
                    }
                    // if (isset($responce['message'])) {
                    //     $TourData->max_people = 0;
                    // }
                    $responce['status'] = 1;
                    $responce['available_ticket'] = $TourData->max_people;
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Enter valid date';
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Tour not available';
            }
        }
        return response()->json($responce);
    }

    public function tourBooking(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'book_tour') {
            $responce['message'] = '';
            $validate = Validator::make($request->all(), [
                'vendorId' => 'required|numeric',
                'tour_id' => 'required|numeric',
                'checkinDate' => 'required|string',
                'totalChild' => 'required|numeric',
                'totalAdult' => 'required|numeric',
                'totalPrice' => 'required|numeric',
                'service_charge' => 'required',
                'childPrice' => 'required|numeric',
                'adultPrice' => 'required|numeric'
            ]);

            if ($validate->fails()) {
                $responce['status'] = 0;
                $errors = $validate->errors();
                if ($errors->has('vendorId')) {
                    $responce['message'] = $errors->first('vendorId');
                } elseif ($errors->has('tour_id')) {
                    $responce['message'] = $errors->first('tour_id');
                } elseif ($errors->has('checkinDate')) {
                    $responce['message'] = $errors->first('checkinDate');
                } elseif ($errors->has('totalChild')) {
                    $responce['message'] = $errors->first('totalChild');
                } elseif ($errors->has('totalAdult')) {
                    $responce['message'] = $errors->first('totalAdult');
                } elseif ($errors->has('totalPrice')) {
                    $responce['message'] = $errors->first('totalPrice');
                } elseif ($errors->has('service_charge')) {
                    $responce['message'] = $errors->first('service_charge');
                } elseif ($errors->has('childPrice')) {
                    $responce['message'] = $errors->first('childPrice');
                } elseif ($errors->has('adultPrice')) {
                    $responce['message'] = $errors->first('adultPrice');
                }
            } else {
                if (date('Y-m-d', strtotime($request->checkinDate)) < date("Y-m-d")) {
                    $responce['status'] = 0;
                    $responce['message'] = 'Invalid check in date.';
                    return response()->json($responce);
                } elseif ((date('Y-m-d', strtotime($request->checkinDate)) == date("Y-m-d", strtotime('tomorrow'))) && (date('H:i:s') > date('H:i:s', strtotime('20:00:00')))) {
                    $responce['status'] = 0;
                    $responce['message'] = 'Booking not available for this date. Please choose different date!';
                    return response()->json($responce);
                }

                $user = $request->user();
                $lastIdData = OrderMaster::orderBy('id', 'desc')->first();
                $lastId = !empty($lastIdData) ? $lastIdData->id + 1 : 1;
                $booking_id = 'OT-'. time() .'-'. $request->vendorId .'-'. $lastId;

                $TourDetails = Tour::where(['id'=> $request->tour_id, 'status' => 'publish'])->first(); //find($request->tour_id);
                $total_price = 0;
                $price_break = array();
                if (!empty($TourDetails)) {
                    if ($TourDetails->id == '34' || $TourDetails->id == '35' || $TourDetails->id == '36') {
                        if ($request->totalAdult > 2) {
                            $responce['status'] = 0;
                            $responce['message'] = 'Sorry! You can book maximum 2 tickets at a time.';
                            return response()->json($responce);
                        }
                    }
                    $total_guests = ($TourDetails->category == 'sight seeing') ? $request->totalAdult : $request->totalAdult + $request->totalChild;
                    $OrderDetails = DB::table('order_masters')
                            ->select(DB::raw('SUM(total_guests) as totQty'))
                            ->where('service_name_id', $TourDetails->id)
                            ->where('service_type', 'tour')
                            ->where('start_date', date("Y-m-d", strtotime($request->checkinDate)))
                            ->where('status', '!=', 'cancelled')
                            ->first();
                    $orderQty = (!empty($OrderDetails->totQty) && $OrderDetails->totQty > 0) ? $OrderDetails->totQty : 0;
                    if ($TourDetails->vendor_id != 1 || $TourDetails->category != 'package') {
                        $TourDetails->max_people = $TourDetails->max_people - $orderQty;
                        if ($TourDetails->max_people < $total_guests) {
                            $responce['message'] = 'Booking not available for this date. Please choose different date!';
                            $responce['status'] = 0;
                            return response()->json($responce);
                        }
                    }

                    $BlockData = TourAvailability::where(['tour_id' => $TourDetails->id, 'block_date' => date('Y-m-d', strtotime($request->checkinDate))])->first();
                    if (!empty($BlockData)) {
                        $responce['status'] = 0;
                        $responce['message'] = 'Booking not available for this date. Please choose different date!';
                        return response()->json($responce);
                    }
                    if ($TourDetails->category == 'package') {
                        $Itinerary = !empty($TourDetails->itinerary) ? json_decode($TourDetails->itinerary, 1) : [];
                        $checkoutDate = date('Y-m-d', strtotime($request->checkinDate . ' + ' . ($TourDetails->duration_end - 1) . ' days'));
                        $difference = strtotime($checkoutDate) - strtotime($request->checkinDate);
                        $days = round($difference / (60 * 60 * 24));
                        $check_room = ($request->adult > 3) ? 2 : 1;
                        $i = 0;
                        foreach ($Itinerary as $itnrs) {
                            if ($itnrs['hotel'] != 'other' && $itnrs['hotel'] != 'No Accommodation') {
                                $MaterHotel = MasterHotel::where(['id' => $itnrs['hotel'], 'status' => 'publish'])->first();
                                if (!empty($MaterHotel)) {
                                    // for ($i = 0; $i < $days; $i++) {
                                        $checkDate = date("Y-m-d", strtotime($request->checkinDate . ' + ' . $i . ' days'));
                                        $HotelRoom = HotelRoom::where(['id' => $itnrs['hotelRoom'], 'status' => 'publish'])->first();
                                        if (!empty($HotelRoom)) {
                                            $BlockedHotel = BlockedHotel::where('hotel_id', $MaterHotel->id)
                                                                ->where('block_date', $checkDate)
                                                                ->whereRaw("find_in_set('". $HotelRoom->id ."',rooms)")
                                                                ->first();
                                            if (!empty($BlockedHotel)) {
                                                $responce['status'] = 0;
                                                $responce['message'] = 'Booking not available for this date. Please choose different date!';
                                                return response()->json($responce);
                                            } else {
                                                $MasterInventory = MasterInventory::where(["date" => $checkDate, 'room_id' => $itnrs['hotelRoom']])->first();
                                                $room_qty = (!empty($MasterInventory->total_available)) ? $MasterInventory->total_available : 0;
                                                if ($room_qty < $check_room) {
                                                    $responce['status'] = 0;
                                                    $responce['message'] = 'Booking not available for this date. Please choose different date!';
                                                    return response()->json($responce);
                                                }
                                            }
                                        } else {
                                            $responce['status'] = 0;
                                            $responce['message'] = 'Booking not available for this date. Please choose different date!';
                                            return response()->json($responce);
                                        }
                                    // }
                                } else {
                                    $responce['status'] = 0;
                                    $responce['message'] = 'Booking not available for this date. Please choose different date!';
                                    return response()->json($responce);
                                }
                            }
                            $i++;
                        }
                        $adult_price = 0;
                        if ($request->totalAdult == 1) {
                            $adult_price = $TourDetails->single_share_price;
                        } elseif ($request->totalAdult % 2 == 0) {
                            $adult_price = $TourDetails->double_share_price * $request->totalAdult;
                        } elseif ($request->totalAdult % 3 == 0) {
                            $adult_price = $TourDetails->triple_share_price * $request->totalAdult;
                        }
                        $child_price = $request->totalChild * $TourDetails->child_price;
                        $total_price = round($adult_price + $child_price, 2);
                    } else {
                        $weekDay = date("l", strtotime($request->checkinDate));
                        $TourDetails->not_available = !empty($TourDetails->not_available) ? json_decode($TourDetails->not_available, 1) : [];
                        if (in_array($weekDay, $TourDetails->not_available)) {
                            $responce['message'] = 'Tour is not available on '. $weekDay .'. Please choose different date!';
                            $responce['status'] = 0;
                            return response()->json($responce);
                        }
                        $price_break['actual_price'] = $TourDetails->single_share_price * $request->totalAdult;
                        $price_break['seasonal_type'] = 'none';
                        $SightSeenPricing = SightSeenPricing::where(['tour_id' => $TourDetails->id, 'start_date' => date("Y-m-d", strtotime($request->checkinDate))])->first();
                        if (!empty($SightSeenPricing)) {
                            $discount_amount = $SightSeenPricing->offer_percentage; // $TourDetails->single_share_price * ($SightSeenPricing->offer_percentage / 100);
                            if ($SightSeenPricing->offer_type == 'plus') {
                                $TourDetails->single_share_price = round($TourDetails->single_share_price + $discount_amount);
                                $price_break['seasonal_type'] = 'plus';
                            } else {
                                $TourDetails->single_share_price = round($TourDetails->single_share_price - $discount_amount);
                                $price_break['seasonal_type'] = 'minus';
                            }
                        }
                        $price_break['seasonal_price'] = $total_price = round($TourDetails->single_share_price * $request->totalAdult, 2);
                    }
                }
                if ($total_price != floatval($request->totalPrice)) {
                    $responce['status'] = 0;
                    $responce['message'] = 'Sorry! Price is tampered, please try again.';
                    return response()->json($responce);
                }

                $TourBooking = new TourBooking([
                    'vendor_id' => $request->vendorId,
                    'booking_id' => $booking_id,
                    'tour_id' => $request->tour_id,
                    'category' => strtolower($request->category),
                    'total_seats' => $request->totalChild + $request->totalAdult,
                    'total_child' => $request->totalChild,
                    'total_adults' => $request->totalAdult,
                    'start_date' => date("Y-m-d", strtotime($request->checkinDate)),
                    'duration' => $request->duration,
                    'priceType' => $request->priceType,
                    'child_price' => floatval($request->childPrice),
                    'adult_price' => floatval($request->adultPrice),
                    'service_charge' => floatval($request->service_charge),
                    'totalPrice' => floatval($request->totalPrice),
                    'price_breakup' => json_encode($price_break),
                    'user_type' => !empty($user) ? 'registered' : 'guest',
                    'create_user' => !empty($user) ? $user->id : null
                ]);
                if ($TourBooking->save()) {
                    $responce['status'] = 1;
                    $responce['booking_id'] = $booking_id;
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Unable to book tour';
                }
            }
        }
        return response()->json($responce);
    }

    public function ticketingDetails(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'get_ticketing_list') {
            $responce['message'] = '';
            $sort_column = 'name';
            $sort_direction = 'asc';

            if(isset($request->request_from) && $request->request_from == 'web') {
                $TicketingQuery = DB::table('tickets')
                    ->select('id', 'name', 'slug', 'feature_image', 'city', 'adult_price', 'review_score', 'review_count', 'category', 'start_date', 'end_date', 'start_time', 'end_time', 'slots', 'max_ticket_per_txn', 'max_ticket_per_user_per_day', 'show_price')
                    ->where('status', 'publish');
            }else{
                $TicketingQuery = DB::table('tickets')
                    ->select('id', 'name', 'slug', 'feature_image', 'city', 'adult_price', 'review_score', 'review_count', 'category', 'start_date', 'end_date', 'start_time', 'end_time', 'slots', 'max_ticket_per_txn', 'max_ticket_per_user_per_day', 'show_price')
                    ->where('status', 'publish')->whereNotIn('id', [24]);
            }

            if(!empty($request->property)) {
                $property = json_decode($request->property, 1);
                foreach ($property as $terms) {
                    $TicketingQuery->where('property_slug', 'like', '%'. $terms .'%');
                }
            }
            if(!empty($request->review_score)) {
                $reviews = json_decode($request->review_score, 1);
                $TicketingQuery->whereIn('review_score', $reviews);
            }
            if(!empty($request->ticketing_type)) {
                $ticketing_type = json_decode($request->ticketing_type, 1);
                $TicketingQuery->whereIn('category', $ticketing_type);
            }
            if(!empty($request->vendorId)) {
                $vendors = json_decode($request->vendorId, 1);
                $TicketingQuery->whereIn('vendor_id', $vendors);
            }
            if($request->startPrice != '' && $request->endPrice != '') {
                $TicketingQuery->whereBetween('adult_price', [$request->startPrice, $request->endPrice]);
            }
            if ($request->city != '') {
                $TicketingQuery->where('place', 'like', '%'. $request->city .'%');
            }
            if (!empty($request->prop_name)) {
                $TicketingQuery->where('name', 'like', '%'. $request->prop_name .'%');
            }
            if (!isset($request->request_from)) {
                $TicketingQuery->where('id', '!=', '29');
            }
            if ($request->sortColumn != '' && $request->direction != '') {
                $sort_column = $request->sortColumn;
                $sort_direction = $request->direction;
            }
            $TicketingQuery->orderBy($sort_column, $sort_direction);

            $take = 9;
            $skip = ($request->pageno == 0) ? $request->pageno : $request->pageno * $take;
            $totalData = $TicketingQuery->count();

            $TicketingData = $TicketingQuery->skip($skip)->take($take)->get()->toArray();

            if (!empty($TicketingData)) {
                foreach ($TicketingData as $key => $value) {

                    $TicketingData[$key]->feature_image = $this->site . $value->feature_image;
                    $duration = '';
                    if (empty($TicketingData[$key]->start_time)) {
                        $slots = json_decode($value->slots, 1);
                        $TicketingData[$key]->start_time = $slots[0]['from_time'];
                    }
                    $TicketingData[$key]->duration = $duration;
                    $value->review_score = !empty($value->review_score) ? round($value->review_score, 2) : 0;
                    $value->review_count = !empty($value->review_count) ? $value->review_count : 0;
                    $value->adult_price = number_format($value->adult_price, 0);
                }
                $RelatedTicket = array();
                if (!empty(isset($request->relatedKey) && !empty($request->relatedKey))) {
                    $RelatedTicket = DB::table('tickets')
                            ->select('id', 'name', 'slug', 'feature_image', 'city', 'adult_price', 'review_score', 'review_count', 'category', 'start_date', 'end_date', 'start_time', 'end_time', 'slots', 'max_ticket_per_txn', 'max_ticket_per_user_per_day', 'show_price')
                            ->where('status', 'publish')
                            ->where('name', '<>', $request->prop_name)
                            ->where('name', 'like', '%'. $request->relatedKey .'%')
                            ->get()->toArray();
                    if (!empty($RelatedTicket)) {
                        foreach ($RelatedTicket as $key => $value) {
                            $RelatedTicket[$key]->feature_image = $this->site . $value->feature_image;
                            $duration = '';
                            if (empty($RelatedTicket[$key]->start_time)) {
                                $slots = json_decode($value->slots, 1);
                                $RelatedTicket[$key]->start_time = $slots[0]['from_time'];
                            }
                            $RelatedTicket[$key]->duration = $duration;
                            $value->review_score = !empty($value->review_score) ? reound($value->review_score, 2) : 0;
                            $value->review_count = !empty($value->review_count) ? $value->review_count : 0;
                            $value->adult_price = number_format($value->adult_price, 0);
                        }
                    }
                }

                $responce['totalPage'] = ceil($totalData/$take);
                $responce['length'] = $totalData;
                $responce['status'] = 1;
                $responce['data'] = $TicketingData;
                $responce['related_data'] = $RelatedTicket;
