                if (!empty($vendor_profile)) {
                    $TicketingData->vendor_profile = $vendor_profile->profile_type;
                    if ($vendor_profile->profile_type == 'own') {
                        $TicketingData->vendor_slug = !empty($vendor_profile->profile_url) ? $vendor_profile->profile_url : 'javascript:void(0)';
                    } else {
                        $TicketingData->vendor_slug = $vendor_profile->slug;
                    }
                } else {
                    $TicketingData->vendor_slug = '';
                }

                //$TicketingData->startdays = 0;
                $TicketingData->startdays = $TicketingData->days_from_start_date;
                if (!empty($TicketingData->book_start_date)) {
                    if ($TicketingData->book_start_date > date("Y-m-d")) {
                        $differ = strtotime($TicketingData->book_start_date) - strtotime(date("Y-m-d"));
                        $day = round($differ / (60 * 60 * 24));
                        $TicketingData->startdays = ($day > 0) ? $day : 1;
                    }
                }

                $TicketingData->feature_image = !empty($TicketingData->feature_image) ? $this->site . $TicketingData->feature_image : $TicketingData->feature_image;
                $TicketingData->banner_image = !empty($TicketingData->banner_image) ? $this->site . $TicketingData->banner_image : $TicketingData->banner_image;
                if (!empty($TicketingData->gallery)) {
                    $hotel_gallery = json_decode($TicketingData->gallery);
                    $TicketingData->gallery = array_map(function($val) { return $this->site . $val; } , $hotel_gallery);
                }
                $Property = !empty($TicketingData->property) ? json_decode($TicketingData->property, 1) : [];
                $PropertyApp = array();
                if (!empty($Property)) {
                    foreach ($Property as $key => $parent) {
                        foreach ($parent as $ckey => $val) {
                            $Property[$key][$ckey]['icon'] = !empty($val['icon']) ? $this->site . $val['icon'] : '';
                        }
                        $PropertyApp[] = array(
                            'name' => $key,
                            'data' => $Property[$key]
                        );
                    }
                }
                $TicketingData->property = $Property;
                $TicketingData->property_app = $PropertyApp;

                $TicketingData->faqs = !empty($TicketingData->faqs) ? json_decode($TicketingData->faqs, 1) : $TicketingData->faqs;
                // $TicketingData->property = !empty($TicketingData->property) ? json_decode($TicketingData->property, 1) : $TicketingData->property;
                $TicketingData->slots = !empty($TicketingData->slots) ? json_decode($TicketingData->slots, 1) : [];
                if (empty($TicketingData->start_time)) {
