                                    }
                                    $TicketingData->slots = $timeSlots;
                                }
                            }
                        }
                    }
                }
                $responce['status'] = 1;
                $responce['data'] = $TicketingData;
                // $responce['ip'] = $_SERVER;
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Ticketing data not available';
            }
        }
        elseif ($request->request_type == 'check_ticket_availability') {
            $responce['message'] = '';
            $TicketingData = Ticket::find($request->ticketId);
            $Ip = $_SERVER['REMOTE_ADDR'];
            if (!empty($TicketingData)) {
