                        $TicketInventory = DB::table('ticket_inventory')->where(['vendor_id' => $TicketingData->vendor_id, 'date' => date("Y-m-d", strtotime($request->checkinDate)), 'ticket_id' => $TicketingData->id])->first();
                        if (!empty($TicketInventory)) {
