    public function ticketBooking(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'book_ticket') {
            $responce['message'] = '';
            $validate = Validator::make($request->all(), [
                'vendorId' => 'required|numeric',
                'ticketing_id' => 'required|numeric',
                'checkinDate' => 'required|string',
                'totalChild' => 'required|numeric',
                'totalAdult' => 'required|numeric',
                'totalPrice' => 'required|numeric',
                'service_charge' => 'required',
                'childPrice' => 'required|numeric',
                'adultPrice' => 'required|numeric'
            ]);

            if ($validate->fails()) {
                $responce['status'] = 0;
                $errors = $validate->errors();
                if ($errors->has('vendorId')) {
                    $responce['message'] = $errors->first('vendorId');
                } elseif ($errors->has('ticketing_id')) {
                    $responce['message'] = $errors->first('ticketing_id');
                } elseif ($errors->has('checkinDate')) {
                    $responce['message'] = $errors->first('checkinDate');
                } elseif ($errors->has('totalChild')) {
                    $responce['message'] = $errors->first('totalChild');
                } elseif ($errors->has('totalAdult')) {
                    $responce['message'] = $errors->first('totalAdult');
                } elseif ($errors->has('totalPrice')) {
                    $responce['message'] = $errors->first('totalPrice');
                } elseif ($errors->has('service_charge')) {
                    $responce['message'] = $errors->first('service_charge');
                } elseif ($errors->has('childPrice')) {
                    $responce['message'] = $errors->first('childPrice');
                } elseif ($errors->has('adultPrice')) {
                    $responce['message'] = $errors->first('adultPrice');
                }
            } else {
                $Ip = $_SERVER['REMOTE_ADDR'];
                if (date('Y-m-d', strtotime($request->checkinDate)) < date("Y-m-d")) {
                    $responce['status'] = 0;
                    $responce['message'] = 'Invalid check in date.';
                    return response()->json($responce);
                }
                $user = $request->user();
                $lastIdData = OrderMaster::orderBy('id', 'desc')->first();
                $lastId = !empty($lastIdData) ? $lastIdData->id + 1 : 1;
                $booking_id = 'OT-'. time() .'-'. $request->vendorId .'-'. $lastId;

                $TicketDetails = Ticket::where(['id'=> $request->ticketing_id, 'status' => 'publish'])->first(); //find($request->ticketing_id);
                $total_price = 0; $start_time = $end_time = '';
                if (!empty($TicketDetails)) {
                    if ($TicketDetails->vendor_id == 268 || $TicketDetails->vendor_id == 6048) { // 268  ,  6048
                        $TicketInventory = DB::table('ticket_inventory')->where(['vendor_id' => $TicketDetails->vendor_id, 'date' => date("Y-m-d", strtotime($request->checkinDate)), 'ticket_id' => $TicketDetails->id])->first();
                        if (!empty($TicketInventory)) {
                            $TicketDetails->max_people = $TicketInventory->online_quantity;
                        }
                        // $OrderData = DB::table('order_masters')
                        //             ->select(DB::raw('COUNT(id) as totQty'))
                        //             ->where('created_at', 'like', date("Y-m-d") .'%')
                        //             ->where(['vendor_id' => $TicketDetails->vendor_id, 'service_type' => 'ticketing', 'order_type' => 'online', 'book_ip' => $Ip])
                        //             ->where('status', '!=', 'cancelled')
                        //             ->first();
                        // if (!empty($OrderData) && $OrderData->totQty > 0) {
                        //     $responce['status'] = 0;
                        //     $responce['message'] = "Sorry!, You have already booked maximum no. of tickets for the day.";
                        //     return response()->json($responce);
                        // }
                    }
                    $current_time = date("H:i:s");
                    if ((date("Y-m-d", strtotime($request->checkinDate)) == date("Y-m-d")) && strtotime($TicketDetails->book_end_time) <= strtotime($current_time)) {
                        $responce['status'] = 0;
                        $responce['message'] = 'No tickets available for this date. Please choose different date!';
                        return response()->json($responce);
                    }
                    $total_guest = $request->totalChild + $request->totalAdult;
                    $BlockData = TicketAvailability::where(['ticket_id' => $TicketDetails->id, 'block_date' => date('Y-m-d', strtotime($request->checkinDate))])->first();
                    if (!empty($BlockData)) {
                        $responce['status'] = 0;
                        $responce['message'] = 'No tickets available for this date. Please choose different date!';
                        return response()->json($responce);
                    }
                    $weekDay = date("l", strtotime($request->checkinDate));
                    $TicketDetails->not_available = !empty($TicketDetails->not_available) ? json_decode($TicketDetails->not_available, 1) : [];
                    if (in_array($weekDay, $TicketDetails->not_available)) {
                        $responce['status'] = 0;
                        $responce['message'] = 'Ticket is not available on ' . $weekDay . '. Please choose different date!';
                        return response()->json($responce);
                    }

                    $OrderDataQuery = OrderMaster::select(DB::raw('SUM(total_guests) AS tot_booked'))
                            ->where('service_name_id', $TicketDetails->id)
                            ->where('start_date', date("Y-m-d", strtotime($request->checkinDate)))
                            ->where('order_type', 'online')
                            ->where('service_type', 'ticketing')
                            ->where('status', '!=', 'cancelled');
                    $OrderData = array();

                    if ($TicketDetails->ticket_type == 'Full Day Booking') {
                        $OrderData = $OrderDataQuery->first();
                        $start_time = $TicketDetails->start_time;
                        $end_time = $TicketDetails->end_time;
                    } else {
                        $OrderData = $OrderDataQuery->where('start_time', $request->start_time)->first();
                        $start_time = $request->start_time;
                        $end_time = $request->end_time;
                    }
                    if (!empty($OrderData)) {
                        if ($TicketDetails->ticket_type == 'Full Day Booking') {
                            if (($TicketDetails->max_people - $OrderData->tot_booked) < $total_guest) {
                                $responce['status'] = 0;
                                $responce['message'] = 'No tickets available for this date. Please choose different date!';
                                return response()->json($responce);
                            }
                        } else {
                            $slots = json_decode($TicketDetails->slots, 1);
                            foreach ($slots as $value) {
                                if($value['from_time'] == $request->start_time) {
                                    if (($value['max_ticket'] - $OrderData->tot_booked) < $total_guest) {
                                        $responce['status'] = 0;
                                        $responce['message'] = "Sorry!, No tickets available. Please change date or time slot and try again.";
                                        return response()->json($responce);
                                        break;
                                    }
                                }
                            }
                        }
                    }
                    $ExtraService = !empty($TicketDetails->extra_services) ? json_decode($TicketDetails->extra_services, 1) : [];
                    $RequestService = json_decode($request->extraticketitems, 1);
                    $extraprice = 0;
                    $ExtraAddedService = array();
                    if (count($ExtraService) > 0) {
                        foreach ($RequestService as $key => $value) {
                            if ($value['quantity'] > 0) {
                                $ExtraAddedService[] = $value;
                            }
                            $extraprice += $ExtraService[$key]['price'] * $value['quantity'];
                        }
                    }
                    $adult_price = $TicketDetails->adult_price * $request->totalAdult;
                    $child_price = $request->totalChild * $TicketDetails->child_price;
                    $total_price = round($adult_price + $child_price + $extraprice, 2);
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Invalid data.';
                    return response()->json($responce);
                }
                if ($total_price != floatval($request->totalPrice)) {
                    $responce['status'] = 0;
                    $responce['message'] = 'Sorry! Price is tampered, please try again.';
                    return response()->json($responce);
                }

                $TicketBooking = new TicketBooking([
                    'vendor_id' => $request->vendorId,
                    'booking_id' => $booking_id,
                    'ticketing_id' => $request->ticketing_id,
                    'category' => $request->category,
                    'total_seats' => $request->totalChild + $request->totalAdult,
                    'total_child' => $request->totalChild,
                    'total_adults' => $request->totalAdult,
                    'start_date' => date("Y-m-d", strtotime($request->checkinDate)),
                    'start_time' => $start_time,
                    'end_time' => $end_time,
                    'child_price' => floatval($request->childPrice),
                    'adult_price' => floatval($request->adultPrice),
                    'extra_services' => json_encode($ExtraAddedService),
                    'service_charge' => floatval($request->service_charge),
                    'totalPrice' => floatval($request->totalPrice),
                    'user_type' => !empty($user) ? 'registered' : 'guest',
                    'create_user' => !empty($user) ? $user->id : null
                ]);
                if ($TicketBooking->save()) {
                    $responce['status'] = 1;
                    $responce['booking_id'] = $booking_id;
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Unable to book ticket';
                }
            }
        }
        return response()->json($responce);
    }

    public function foodDetails(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'get_food_list') {
