    public function foodBooking(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'book_food') {
            $responce['message'] = '';
            $user = $request->user();
            $booking_id = '';
            $food_details = array();
            $total_price = 0;
            $food_request = json_decode($request->food_cart, 1);
            if (!empty($food_request)) {
                foreach ($food_request as $value) {
                    $ItemDetails = FoodItem::where(['id'=> $value['id'], 'status' => 'publish'])->first(); //find($value['id']);
                    $temp = array();
                    if (!empty($ItemDetails)) {
                        $OrderDetails = OrderDetail::select(DB::raw('SUM(service_item_quantity) as totQty'))
                                ->where(['service_item_id' => $value['id'], 'start_date' => date("Y-m-d"), 'service_type' => 'food'])
                                ->where('status', '!=', 'cancelled')
                                ->first();
                        $orderQty = ($OrderDetails->totQty) ? (int)$OrderDetails->totQty : 0;
                        $remainQty = $ItemDetails->max_qty - $orderQty;
                        $max_cart_qty = ($remainQty < $ItemDetails->max_cart_qty) ? $remainQty : $ItemDetails->max_cart_qty;
                        if ($max_cart_qty == 0) {
                            $responce['status'] = 0;
                            $responce['message'] = "Sorry!, $ItemDetails->item_name is not available. Please remove this from cart & try again.";
                            return response()->json($responce);
                        } elseif ($max_cart_qty < $value['quantity']) {
                            $responce['status'] = 0;
                            $responce['message'] = "Sorry!, You can order maximum $max_cart_qty $ItemDetails->item_name at a time.";
                            return response()->json($responce);
                        }
                        $temp['actualPrice'] = (float)$ItemDetails->price;
                        $temp['foodName'] = $ItemDetails->item_name;
                        $temp['id'] = $ItemDetails->id;
                        $temp['foodQuantity'] = $value['quantity'];
                        $temp['vegStatus'] = $ItemDetails->is_veg;
                        $temp['categoryId'] = $ItemDetails->category_id;
                        $temp['foodPrice'] = round(($ItemDetails->price * $value['quantity']), 2);
                        $total_price += $temp['foodPrice'];
                        array_push($food_details, $temp);
                    }
                }
            }
            if ($total_price > 0) {
                if (isset($request->booking_id)) {
                    $FoodBooking = FoodBooking::where(['booking_id' => $request->booking_id, 'status' => 0])->first();
                    if (!empty($FoodBooking)) {
                        $booking_id = $FoodBooking->booking_id;
                        $FoodBooking->food_request = $request->food_cart;
                        $FoodBooking->food_details = json_encode($food_details);
                        $FoodBooking->update_user = !empty($user) ? $user->id : null;
                    } else {
                        $responce['status'] = 0;
                        $responce['message'] = 'Invalid booking details!';
                    }
                } else {
                    $lastIdData = OrderMaster::orderBy('id', 'desc')->first();
                    $lastId = !empty($lastIdData) ? $lastIdData->id + 1 : 1;
                    $booking_id = 'OT-'. time() .'-'. $request->vendorId .'-'. $lastId;

                    $FoodBooking = new FoodBooking([
                        'vendor_id' => $request->vendorId,
                        'booking_id' => $booking_id,
                        'food_request' => $request->food_cart,
                        'food_details' => json_encode($food_details),
                        'service_city' => $request->city,
                        'total_price' => round($total_price, 2),
                        'user_type' => !empty($user) ? 'registered' : 'guest',
                        'create_user' => !empty($user) ? $user->id : null,
                    ]);
                }
                if ($FoodBooking->save()) {
                    $responce['status'] = 1;
                    $responce['booking_id'] = $booking_id;
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Unable to book';
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Unable to book';
            }
        }
        return response()->json($responce);
    }

    private function verifyMsg(Request $request){
        if($request->has('request_access_type') && $request->request_access_type == 'verify_otp'){
            $NOWDATETIME = date("Y-m-d H:i:s");
            $TempOtp = TempOtp::where(['device_detail' => $request->phone, 'otp' => $request->otp])
                    ->whereRaw('updated_at > DATE_SUB("'. $NOWDATETIME .'",INTERVAL 10 MINUTE)')
                    ->first();
            if(!empty($TempOtp)){
                return true;
            }else{
                return false;
            }
        }
        return false;
    }

    public function orderPayment(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        // Only in case of otp verification, we will check the otp and phone number, otherwise we will not check it.
        if($request->has('request_access_type') && $request->request_access_type == 'verify_otp'){
            if($request->has('otp') && $request->has('phone') && !empty($request->otp) && !empty($request->phone)){
                $verifyOtp = $this->verifyMsg($request);
                if(!$verifyOtp){
                    return response()->json(['status' => 0, 'message' => 'Invalid OTP. Please try again.']);
                }
            }else{
                return response()->json(['status' => 0, 'message' => 'Invalid OTP. Please try again.']);
            }
        }

        if ($request->request_type == 'get_check_out_details') {
            $responce['message'] = '';
            $GSTData = GstDetail::pluck('value', 'name')->toArray();
            $responce['gst_data'] = [];
            $user = $request->user();
            $agent_comission = 0;
            $blockStat = 0;
            $agent_block_date = array();

            if (!empty($user)) {
                if ($user->access_type == 'agent') {
                    $agent_comission = $user->agent_comission;
                    $agent_block_date = !empty($user->agent_block_date) ? explode(',', $user->agent_block_date) : [];
                }
            }
            if ($request->service_type == 'hotel') {
                $HotelRoomBooking = HotelRoomBooking::where('booking_id', $request->bookingId)->first();
                if (!empty($HotelRoomBooking)) {

                    // agent comission according to property set
                    if (isset($user->commission_taken) && $user->access_type == 'agent' && $user->commission_taken == 1 && $request->service_type == 'hotel'){
                        $BookingData_commision = HotelRoomBooking::where('booking_id', $request->bookingId)->first();
                        $HotelData_commission = MasterHotel::find($BookingData_commision->hotel_id);
                        if (!empty($HotelData_commission)) {
                            $more_nights = $foreign_visitors = $weekend_days = $week_days = 0;
                            $totalOrderMaster = OrderMaster::select(DB::raw("SUM(DATEDIFF(end_date, start_date) * total_rooms)as totBook"))
                                        ->where(['customer_id' => Auth::user()->id, 'service_type' => 'hotel', 'status' => 'completed', 'payment_status' => 'success']) //'service_name_id' => $BookingData_commision->hotel_id,
                                        ->where('created_at', 'like', '%' . date('Y-m') . '%')
                                        ->first();
                            // echo $totalOrderMaster->totBook; exit;
                            if (!empty($totalOrderMaster->totBook) && $totalOrderMaster->totBook >= 100) {
                                $more_nights = 1;
                            }

                            if(isset($request->isForeignCitizen) && $request->isForeignCitizen == 1) {
                                $foreign_visitors = 1;
                            }

                            $chekin_date = date("Y-m-d", strtotime($BookingData_commision->start_date));
                            $checkout_date = date("Y-m-d", strtotime($BookingData_commision->end_date));

                            $weekend_check = date('N', strtotime($chekin_date));
                            if($weekend_check == 6 || $weekend_check == 7) {
                                $weekend_days = 1;
                            }else{
                                $weekend_present = 0;
                                if ($chekin_date == $checkout_date) {
                                    $days = 1;
                                } else {
                                    $difference = strtotime($checkout_date) - strtotime($chekin_date);
                                    $days = round($difference / (60 * 60 * 24));
                                }

                                for ($i = 0; $i < $days; $i++) {
                                    $checkInDateCommission = date("Y-m-d", strtotime($chekin_date . ' + ' . $i . ' days'));
                                    $weekend_present_check = date('N', strtotime($checkInDateCommission));
                                    if($weekend_present_check == 6 || $weekend_present_check == 7) {
                                        $weekend_present = 1;
                                        break;
                                    }
                                }
                                if ($weekend_present == 1){
                                    if ($HotelData_commission->weekend_days < $HotelData_commission->week_days) {
                                        $weekend_days = 1;
                                    }else{
                                        $week_days = 1;
                                    }
                                }else{
                                    $week_days = 1;
                                }
                            }

                            if($more_nights == 1 && $HotelData_commission->more_nights > 0 && $user->night_limit_commission == 1){
                                $agent_comission = $HotelData_commission->more_nights;
                            }else if ($foreign_visitors == 1 && $HotelData_commission->foreign_visitors > 0 && $user->foreign_visitors_commission == 1){
                                $agent_comission = $HotelData_commission->foreign_visitors;
                            }else if ($weekend_days == 1 && $HotelData_commission->weekend_days > 0){
                                $agent_comission = $HotelData_commission->weekend_days;
                            }else if ($week_days == 1 && $HotelData_commission->week_days > 0){
                                $agent_comission = $HotelData_commission->week_days;
                            }else{
                                $agent_comission = 0;
                            }
                        }
                    }
                    $days = 0;
                    if ($HotelRoomBooking->start_date == $HotelRoomBooking->end_date) {
                        $HotelRoomBooking->night = $days = 1;
                    } else {
                        $difference = strtotime($HotelRoomBooking->end_date) - strtotime($HotelRoomBooking->start_date);
                        $HotelRoomBooking->night = $days = round($difference / (60 * 60 * 24));
                    }
                    $start_date = $HotelRoomBooking->start_date;
                    $end_date = $HotelRoomBooking->end_date;
                    $MasterHotel = MasterHotel::find($HotelRoomBooking->hotel_id);
                    if (!empty($user)) {
                        for ($i = 0; $i < $days; $i++) {
                            $checkInDate = date("Y-m-d", strtotime($start_date . ' + ' . $i . ' days'));
                            if (in_array($checkInDate, $agent_block_date)) {
                                $blockStat = 1;
                                break;
                            }
                        }
                        if (($user->access_type == 'agent' && $user->vendor_id != $MasterHotel->vender_id) || $blockStat == 1) {
                            $agent_comission = 0;
                        }
                    }
                    $VendorDetails = User::find($MasterHotel->vender_id);
                    $HotelRoomBooking->vendor_name = $VendorDetails->company;
                    $HotelRoomBooking->vendor_id = $VendorDetails->id;
                    $HotelRoomBooking->hotel_name = $MasterHotel->name;
                    $HotelRoomBooking->hotel_slug = $MasterHotel->slug .'-'. $MasterHotel->id;
                    $HotelRoomBooking->hotel_image = $this->site . $MasterHotel->feature_image;
                    $HotelRoomBooking->hotel_address = $MasterHotel->address;
                    $HotelRoomBooking->hotel_city = $MasterHotel->city;

                    $HotelRoomBooking->hotel_name = $MasterHotel->name;
                    $HotelRoomBooking->service_fee = $MasterHotel->service_fee;
                    $HotelRoomBooking->gst_applicable = $MasterHotel->gst_applicable;
                    $room_details = json_decode($HotelRoomBooking->room_details, 1);
                    $HotelRoomBooking->pricing_details = $Pricing_data = json_decode($HotelRoomBooking->pricing_details, 1);
                    $HotelRoomBooking->room_request = json_decode($HotelRoomBooking->room_request, 1);
                    $extra_price = 0;

                    if ($MasterHotel->gst_applicable == 1) {
                        $GstTable = GstTable::where(['vendor_id' => $MasterHotel->vender_id, 'service_type' => 'hotel'])
                                ->orderBy('min_amount', 'asc')
                                ->pluck('gst', 'min_amount')->toArray();
                        $GstDetails = array();
                        if (!empty($GstTable)) {
                            foreach ($GstTable as $k => $gst) {
                                $GstDetails[$k] = json_decode($gst, 1);
                            }
                        } else {
                            $GstDetails[0] = $GSTData;
                        }
                        $GstMin = array_keys($GstDetails);
                    }

                    $GstShowData = $tax_array = array();$total_gst = $total_coupon_amt = $SubTotal = 0;
                    foreach ($room_details as $key => $value) {
                        $HotelRoom = HotelRoom::find($value['id']);
                        $room_details[$key]['name'] = $HotelRoom->title;
                        $extra_price += $value['extra_bed'] * $value['extra_bed_price'];
                        $extra_bed_price = $value['extra_bed'] * $value['extra_bed_price'];
                        unset($room_details[$key]['price']);

                        for ($i = 0; $i < $days; $i++) {
                            $checkInDate = date("Y-m-d", strtotime($start_date . ' + ' . $i . ' days'));
                            $checkOutDate = date("Y-m-d", strtotime($start_date . ' + ' . ($i + 1) . ' days'));
                            if ($start_date == $end_date) {
                                $checkOutDate = $checkInDate;
                            }
                            $only_room_price = $Pricing_data[$value['id']][$checkInDate]['price'];
                            $room_price = ($Pricing_data[$value['id']][$checkInDate]['price'] + $extra_bed_price);
                            $coupon_amt = $only_room_price * ($agent_comission / 100);
                            $total_coupon_amt += $coupon_amt;
                            $price = $room_price - $coupon_amt;
                            $SubTotal += $price;
                            if ($MasterHotel->gst_applicable == 1) {
                                $filter_res = array_filter($GstMin, function($n) use($price) { return $n <= $price; });
                                if (!empty($filter_res)) {
                                    $tempr = $GstDetails[end($filter_res)];
                                    if (!empty($tax_array)) {
                                        foreach ($tempr as $g_name => $g_val) {
                                            $tax_amt = $price * ($g_val/100);
                                            $tax_array[$g_name] += $tax_amt;
                                        }
                                    } else {
                                       foreach ($tempr as $g_name => $g_val) {
                                            $tax_amt = $price * ($g_val/100);
                                            $tax_array[$g_name] = $tax_amt;
                                        }
                                    }
                                }
                            }
                        }
                    }
                    foreach ($tax_array as $key => $val) {
                        $GstShowData[] = [
                            'gst_name' => $key,
                            'gst_percentage' => $tempr[$key],
                            'gst_value' => ceil($val)
                        ];
                        $total_gst += ceil($val);
                    }
                    $responce['gst_data'] = $GstShowData;
                    $HotelRoomBooking->subTotalPrice = ceil($SubTotal);
                    $HotelRoomBooking->discountAmount = ceil($total_coupon_amt);
                    $HotelRoomBooking->totalOrderPrice = ceil($SubTotal + $total_gst + $MasterHotel->service_fee);
                    $HotelRoomBooking->extra_price = $extra_price * $HotelRoomBooking->night;
                    $HotelRoomBooking->room_details = $room_details;
                    $responce['status'] = 1;
                    $responce['booking_details'] = $HotelRoomBooking;
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Invalid booking details!';
                }
            }
            elseif ($request->service_type == 'car') {
                $CarBooking = CarBooking::where('booking_id', $request->bookingId)->first();
                if (!empty($CarBooking)) {
                    $MasterCar = $CarDetails = MasterCar::find($CarBooking->car_id);
                    $difference = strtotime($CarBooking->end_date) - strtotime($CarBooking->start_date);
                    $CarBooking->night = $days = round($difference / (60 * 60 * 24));
                    if (!empty($user)) {
                        for ($i = 0; $i < $days; $i++) {
                            $checkInDate = date("Y-m-d", strtotime($CarBooking->start_date . ' + ' . $i . ' days'));
                            if (in_array($checkInDate, $agent_block_date)) {
                                $blockStat = 1;
                                break;
                            }
                        }
                        if (($user->access_type == 'agent' && $user->vendor_id != $MasterCar->vendor_id) || $blockStat == 1) {
                            $agent_comission = 0;
                        }
                    }
                    $VendorDetails = User::find($MasterCar->vendor_id);
                    $CarBooking->vendor_name = $VendorDetails->company;
                    $CarBooking->vendor_id = $VendorDetails->id;
                    $CarBooking->car_name = $MasterCar->title;
                    $CarBooking->car_slug = $MasterCar->slug . '-' . $MasterCar->id;
                    $CarBooking->car_image = $this->site . $MasterCar->feature_image;
                    $CarBooking->car_address = $MasterCar->address;
                    $CarBooking->car_city = $MasterCar->city;

                    $CarBooking->hotel_name = $MasterCar->name;
                    $CarBooking->service_fee = $MasterCar->service_fee;
                    $CarBooking->gst_applicable = $MasterCar->gst_applicable;
                    $CarBooking->price_breakup = json_decode($CarBooking->price_breakup, 1);
                    $guide_fees = 0;
                    if ($CarBooking->need_guide == 'Yes' && $CarBooking->days_for_guide > 0) {
                        $guide_fees = $CarBooking->days_for_guide * $MasterCar->guide_price_per_day;
                    }
                    $CarBooking->guide_fees = $guide_fees;

                    $GstDetails = array();
                    $GstShowData = $tax_array = array();$total_gst = $total_coupon_amt = $SubTotal = 0;
                    if ($MasterCar->gst_applicable == 1) {
                        $GstTable = GstTable::where(['vendor_id' => $MasterCar->vendor_id, 'service_type' => 'rental'])
                                ->orderBy('min_amount', 'asc')
                                ->pluck('gst', 'min_amount')->toArray();
                        $GstDetails = array();
                        if (!empty($GstTable)) {
                            foreach ($GstTable as $k => $gst) {
                                $GstDetails[$k] = json_decode($gst, 1);
                            }
                        } else {
                            $GstDetails[0] = $GSTData;
                        }
                        $GstMin = array_keys($GstDetails);
                    }
                    $day_breakup = json_decode($CarBooking->day_breakup, 1);
                    foreach ($day_breakup as $val) {
                        $totalPrice = 0;
                        $difference = strtotime(date("Y-m-d", strtotime($val['date']['endDate']))) - strtotime(date("Y-m-d", strtotime($val['date']['startDate'])));
                        $days = floor($difference / (60 * 60 * 24));

                        $checkinDate = new DateTime($val['date']['startDate']);
                        $checkoutDate = new DateTime($val['date']['endDate']);

                        $interval = $checkinDate->diff($checkoutDate);
                        $totalHour = $interval->format('%h') + ($interval->format('%d') * 24);

                        $travelHr = ceil($val['day_km'] / $CarDetails->dist_cover_per_hour);
                        $cover_day = $days + 1;
                        $cover_distance_day = $val['day_km'] / $cover_day;
                        if ($cover_distance_day >= $CarDetails->max_distance) {
                            $totalPriceKm = $val['day_km'] * $CarDetails->price_per_km;
                            $halthour = $days * $CarDetails->halt_hour;
                            $totalHaltPrice = $days * $CarDetails->price_for_halt;
                            $detention_hour = $totalHour - $travelHr - $halthour;
                            $detention_charge = 0;
                            if ($detention_hour > 0) {
                                $detention_charge = $detention_hour * $CarDetails->detention_charge_per_hour;
                            }
                            $totalPrice = ($totalPriceKm + $detention_charge + $totalHaltPrice) * $CarBooking->total_cars;
                        } else {
                            $extrakm = 0;
                            $totalPriceKm = $travelHr * $CarDetails->price_per_hour;
                            $halthour = $days * $CarDetails->halt_hour;
                            $calculateHr = $totalHour - $halthour;
                            if($val['day_km'] > ($calculateHr * $CarDetails->free_km_per_hour)) {
                                $extrakm = $val['day_km'] - ($calculateHr * $CarDetails->free_km_per_hour);
                            }
                            $extrakm_price = 0;
                            if($val['day_km'] > $extrakm) {
                                $extrakm_price = $extrakm * $CarDetails->price_per_km;
                            }
                            $totalPriceHr = $calculateHr * $CarDetails->price_per_hour;
                            $totalHaltPrice = $days * $CarDetails->price_for_halt;
                            $totalPrice = ($totalPriceHr + $totalHaltPrice + $extrakm_price) * $CarBooking->total_cars;
                        }

                        $coupon_amt = round($totalPrice * ($agent_comission / 100), 2);
                        $price = $totalPrice - $coupon_amt;
                        $total_coupon_amt += $coupon_amt;
                        $SubTotal += $price;
                        if ($MasterCar->gst_applicable == 1) {
                            $filter_res = array_filter($GstMin, function($n) use($price) { return $n <= $price; });
