                                if (!empty($tax_array)) {
                                    foreach ($tempr as $g_name => $g_val) {
                                        $tax_amt = ceil($price * ($g_val/100));
                                        $tax_array[$g_name] += $tax_amt;
                                    }
                                } else {
                                   foreach ($tempr as $g_name => $g_val) {
                                        $tax_amt = ceil($price * ($g_val/100));
                                        $tax_array[$g_name] = $tax_amt;
                                    }
                                }
                            }
                        }
                    }
                    foreach ($tax_array as $key => $val) {
                        $GstShowData[] = [
                            'gst_name' => $key,
                            'gst_percentage' => $tempr[$key],
                            'gst_value' => round($val, 2)
                        ];
                        $total_gst += $val;
