                        }
                    }



                //    $Message = "Dear $request->first_name ,<br>Your order placed successfully. Please complete payment.";
                //    $Subject = "Order Confirmation - $invoice_id";
                //    Mail::to($request->email)->send(new \App\Mail\RegistrationMailUser($Message, $Subject));

