                                "callbackUrl" => $McallbackUrl,
                                "txnAmount" => array(
                                    "value" => $TXN_AMOUNT,
                                    "currency" => "INR",
                                ),
                                "userInfo" => array(
                                    "custId" => $CUST_ID,
                                ),
                            );

                            if (!empty($OrderMaster->paytm_mid)) {
                                $splitSettlementInfo['splitMethod'] = 'AMOUNT';
                                $splitSettlementInfo['splitInfo'][] = array('mid' => $OrderMaster->paytm_mid, 'amount' => array('value' => $OrderMaster->vendor_amount, 'currency' => 'INR'));
                                $paramList["body"]["splitSettlementInfo"] = $splitSettlementInfo;
                            }

                            /*
                             * Generate checksum by parameters we have in body
                             * Find your Merchant Key in your Paytm Dashboard at https://dashboard.paytm.com/next/apikeys
                             */
                            $checksum = generateSign($paramList["body"], PAYTM_MERCHANT_KEY);

                            $paramList["head"] = array(
                                "signature" => $checksum
                            );
                            $post_data = json_encode($paramList, JSON_UNESCAPED_SLASHES);

                            /* for Staging */
                            $url = "https://securegw-stage.paytm.in/theia/api/v1/initiateTransaction?mid=" . PAYTM_MERCHANT_MID . "&orderId=$ORDER_ID";
                            if (PAYTM_ENVIRONMENT == 'PROD') {
                                $url = "https://securegw.paytm.in/theia/api/v1/initiateTransaction?mid=" . PAYTM_MERCHANT_MID . "&orderId=$ORDER_ID";
                            }

                            $ch = curl_init($url);
                            curl_setopt($ch, CURLOPT_POST, 1);
                            curl_setopt($ch, CURLOPT_POSTFIELDS, $post_data);
                            curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
                            curl_setopt($ch, CURLOPT_HTTPHEADER, array("Content-Type: application/json"));
                            $response = curl_exec($ch);
                            $response = json_decode($response, 1);
                            if (isset($response['body']['txnToken'])) {
                                $paramList["txnToken"] = $response['body']['txnToken'];
                                $paramList["response"] = $response;
                                $paramList["mobile_callbackurl"] = $McallbackUrl;
                            }else {
                                $responce['status'] = 0;
                                $paramList["response"] = $response;
                                $responce['message'] = 'Unable to place order. Please try again after some time.';
                                return response()->json($responce);
                            }
                        } else {
                            $paramList["MID"] = PAYTM_MERCHANT_MID;
                            $paramList["ORDER_ID"] = $ORDER_ID;
                            $paramList["CUST_ID"] = $CUST_ID;
                            $paramList["INDUSTRY_TYPE_ID"] = $INDUSTRY_TYPE_ID;
                            $paramList["CHANNEL_ID"] = $CHANNEL_ID;
                            $paramList["TXN_AMOUNT"] = $TXN_AMOUNT;
                            $paramList["WEBSITE"] = PAYTM_MERCHANT_WEBSITE;
                            $paramList["CALLBACK_URL"] = $this->site . "api/auth/paytm_success";
                            $paramList["MSISDN"] = $request->phone;
                            $paramList["EMAIL"] = $request->email;
                            $paramList["VERIFIED_BY"] = "EMAIL";
                            $paramList["IS_USER_VERIFIED"] = "YES";

                            if (!empty($OrderMaster->paytm_mid)) {
                                $splitSettlementInfo['splitMethod'] = 'AMOUNT';
                                $splitSettlementInfo['splitInfo'][] = array('mid' => $OrderMaster->paytm_mid, 'amount' => $OrderMaster->vendor_amount);
                                $paramList["splitSettlementInfo"] = json_encode($splitSettlementInfo);
                            }

                            $checkSum = getChecksumFromArray($paramList, PAYTM_MERCHANT_KEY);
                            $paramList["CHECKSUMHASH"] = $checkSum;
                            $paramList["PAYTM_TXN_URL"] = $PAYTM_TXN_URL;
                        }
                        if (!empty($OrderMaster->paytm_mid)) {
                            $paramList["is_split"] = 1;
                            $paramList["paytm_mid"] = $OrderMaster->paytm_mid;
                        } else {
                            $paramList["is_split"] = 0;
                            $paramList["paytm_mid"] = '';
                        }
                        $paramList['ENVIRONMENT'] = PAYTM_ENVIRONMENT;

                        $payment_info = $paramList;

                        $PaymentHistory = new PaymentHistory([
                            'order_id' => $request->order_id,
                            'vendor_id' => $vendor_id,
                            'user_id' => $userId,
                            'payment_method' => 'paytm',
                            'transaction_id' => $ORDER_ID,
                            'amount' => $request->total_price,
                            'product_info' => $service_name,
                            'first_name' => $request->first_name,
                            'last_name' => $request->last_name,
                            'email' => $request->email,
                            'phone' => $request->phone,
                            'address1' => $request->address1,
                            'address2' => $request->address2,
                            'city' => $request->city,
                            'state' => $request->state,
                            'country' => $request->country,
                            'zipcode' => $request->zipcode,
                            'udf1' => $invoice_id,
                            'udf2' => $vendor_id,
                            'udf3' => $vendor_name,
                            'udf4' => $request->service_type,
                            'status' => 'pending'
                        ]);
                        $PaymentHistory->save();
                        $payment_id = $PaymentHistory->id;

                        OrderMaster::find($OrderMasterId)->update(['payment_id' => $payment_id]);
                    }
                    $responce['status'] = 1;
                    $responce['data'] = $payment_info;
                    $responce['payment_gateway_redirect'] = $payment_gateway_redirect;
                    if ($payment_gateway_redirect == 0) {
                        $param = base64_encode($payment_info['txn_id']);
                        $param = str_replace("=", "%3D", $param);
                        $responce['param'] = $param;
                        $responce['redirect'] = $this->frontendUrl .'success/'. $param;
                        OrderMaster::find($OrderMasterId)->update(['transaction_id' => 'N/A']);
                    }

                }else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Unable to place order';
                }
            }
        }
        elseif ($request->request_type == 'generate_hash') {
            $responce['message'] = '';
            require_once public_path('paytm_lib/config_paytm.php');
            $hashStringwithoutSalt = $request->hashStringwithoutSalt;
            $Mid = $request->payment_id;
            $PropertyAccount = PropertyAccount::where('hdfc_mid', $Mid)->first();
            if (!empty($PropertyAccount) && PAYTM_ENVIRONMENT == 'PROD') {
                $HDFC_SALT = $PropertyAccount->hdfc_salt;
            }
            $hashSHAStringwithSalt = hash('sha512', $hashStringwithoutSalt . $HDFC_SALT);
            $responce['status'] = 1;
            $responce['hashSHAStringwithSalt'] = $hashSHAStringwithSalt;
        }
        return response()->json($responce);
    }

    public function flightOrderPayment(Request $request){
        $validator = Validator::make($request->all(),[
            'bookingId'=>'required'
        ]);
        if ($validator->fails()) {
            return [
                'status' => 0,
                'message' => $validator->errors()->first()
            ];
        }
        $response = ['status' => 0,'message' => 'Sorry, Something went wrong please try again after sometime.'];

        $flightBooking = FlightBooking::where('booking_id', $request->bookingId)->first();
        $GSTData = GstDetail::pluck('value', 'name')->toArray();

        try{
            if(!empty($flightBooking)){
                $departureSchedule = FlightSchedule::with('flight')->where('id', $flightBooking->onward_schedule_id)->first();

                $departure_date = $flightBooking->onward_flight_date;
                $tripType = $flightBooking->booking_type;

                $checkInventory = SeatInventory::where('date', $departure_date)->where('schedule_id', $flightBooking->onward_schedule_id)->first();
                $availableBookings = $checkInventory->online_capacity - $checkInventory->online_booked;

                if(empty($checkInventory) || ((int)$flightBooking->adult_count > (int)$availableBookings)){
                    return [
                        'status'=>0,
                        'message'=>'Tickets are not available'
                    ];
                }
                $flightDetails = $departureSchedule->flight;
                $airport = $this->getSourceDetails($departureSchedule->source_airport_id);
                $airportArr = $this->getSourceDetails($departureSchedule->destination_airport_id);

                if($tripType == 'oneway'){
                    $flightBooking->departure = [
                        'flight_code'=>$flightDetails->airline_code,
                        'flight_name'=>$flightDetails->operator_name,
                        'departure_time'=> date('h:i A', strtotime($departureSchedule->departure_time)),
                        'arrival_time'=> date('h:i A', strtotime($departureSchedule->arrival_time)),
                        'departure_from'=> $airport ? $airport->city_name : null,
                        'departure_from_code'=> $airport ? $airport->airport_code : null,
                        'arrival_at'=> $airportArr ? $airportArr->city_name : null,
                        'arrival_at_code'=> $airportArr ? $airportArr->airport_code : null,
                        'adult_fare'=> $this->getFarePrice($flightDetails->id, $departureSchedule->id),
                        'child_fare'=>$this->getFarePrice($flightDetails->id, $departureSchedule->id, 'INFANT')
                    ];
                }

                if($tripType == 'roundtrip'){

                }
                return [
                    'status'=>1,
                    'message'=>"",
                    'booking_details'=>$flightBooking
                ];
            }else{
                return [
                    'status'=>0,
                    'message'=>'Invalid booking ID '
                ];
            }
        }catch(\Exception $e){
            return [
                'status'=>0,
                'message'=>'Unable to proceed. Please try after sometime '.$e->getMessage()
            ];
        }

        return $response;
    }

    private function isSlotAvailable(string $date, string $requestedSlot = 'full_day'){
        $date = date("Y-m-d", strtotime($date));
        $isSlotAvailable = HallMasterInventory::where('hall_id', $this->hall_id)->where('inventory_date', $date);
        $query = clone $isSlotAvailable;
        if($isSlotAvailable->exists()){
            if ($requestedSlot === 'full_day') {
                // A full day request is blocked by ANY existing booking on that day
                $query->where('first_half_available', '0')->where('second_half_available', '0');
            }elseif ($requestedSlot === 'first_half') {
                // First half is blocked by an existing full day or another first half
                $query->where('first_half_available', '0');
            } elseif ($requestedSlot === 'second_half') {
                // Second half is blocked by an existing full day or another second half
                $query->where('second_half_available', '0');
            }else {
                throw new \InvalidArgumentException("Invalid slot type provided.");
            }
            // If a record exists, it means the slot is available
            return $query->exists();
        }else{
            return false; // No inventory exists for the given date
        }
    }

    private function hallOrderPayment(Request $request){
        $hallRoomBooking = HallBooking::where('booking_id', $request->bookingId)->first();
        $GSTData = GstDetail::pluck('value', 'name')->toArray();
        DB::beginTransaction();
        try{
            if (!empty($hallRoomBooking)) {

                $days = 0;
                if ($hallRoomBooking->start_date == $hallRoomBooking->end_date) {
                    $days = 1;
                } else {
                    $difference = strtotime($hallRoomBooking->end_date) - strtotime($hallRoomBooking->start_date);
                    $days = round($difference / (60 * 60 * 24));
                    $days += 1; // Include the checkout day in the count
                }
                $start_date = $hallRoomBooking->start_date;
                $end_date = $hallRoomBooking->end_date;
                $this->hall_id = $hallRoomBooking->hall_id;
                $MasterHall = Hall::where('id',$hallRoomBooking->hall_id)->first();

                $MasterProperty = HallProperty::where('id', $MasterHall->property_id)->first();

                $VendorDetails = User::find($MasterProperty->vender_id);
                $hallRoomBooking->vendor_name = $VendorDetails->company;
                $hallRoomBooking->vendor_id = $VendorDetails->id;
                $hallRoomBooking->hall_name = $MasterHall->hall_name;
                $hallRoomBooking->hall_slug = $MasterHall->slug .'-'. $MasterHall->id;
                $hallRoomBooking->hall_image = $this->site . $MasterHall->feature_image;
                $hallRoomBooking->hall_address = $MasterProperty->address;
                $hallRoomBooking->hall_place = $MasterProperty->place;

                $hallRoomBooking->property_name = $MasterProperty->property_name;
                $hallRoomBooking->gst_applicable = $MasterProperty->gst_applicable;
                //$room_details = json_decode($hallRoomBooking->room_details, 1);

                $totalPrice = $sub_total_price = 0;
                $slot = '';
                switch(strtolower($hallRoomBooking->slot_type)){
                    case 'full_day':
                        $slot = 'FULL_DAY';
                        break;

                    case 'first_half':
                        $slot = 'HALF_DAY';
                        break;

                    case 'second_half':
                        $slot = 'HALF_DAY';
                        break;
                    default:
                        $slot = '';
                        break;
                }
                $slots = Slot::where('hall_id', $MasterHall->id)->where('slot', $slot)->where('booking_type', $slot)->where('status','1')->where('is_deleted',0)->first();


                $extra_price = 0;

                $GstDetails = array();
                if ($MasterProperty->gst_applicable == '1') {
                    $GstTable = GstTable::where(['vendor_id' => $MasterProperty->vender_id, 'service_type' => 'hall'])
                            ->orderBy('min_amount', 'asc')
                            ->pluck('gst', 'min_amount')->toArray();
                    if (!empty($GstTable)) {
                        foreach ($GstTable as $k => $gst) {
                            $GstDetails[$k] = json_decode($gst, 1);
                        }
                    } else {
                        $GstDetails[0] = $GSTData;
                    }
                    $GstMin = array_keys($GstDetails);
                }
                $tempr = array();
                $price_breakup = $tax_array = array();

                for($i = 0; $i < $days; $i++){
                    $dateToCheck = date("Y-m-d", strtotime($start_date . ' + ' . $i . ' days'));
                    if (!$this->isSlotAvailable($dateToCheck, strtolower($hallRoomBooking->slot_type))) {
                        return response()->json([
                            'status' => 0,
                            'statusCode' => 'error',
                            'message' => "The requested slot is not available for the date: " . date("Y-m-d", strtotime($dateToCheck)),
                        ], 200);
                    }
                    $totalPrice = $slots->price;
                    $sub_total_price += $totalPrice;
                    $price_breakup[] = array(
                        "price_per_day" => $slots->price,
                        "totaldays" => $i+1,
                        "slot"=> str_replace('_',' ',strtoupper($slot)),
                        "slot_type" => str_replace('_',' ',strtoupper($hallRoomBooking->slot_type)),
                        "booking_date" => array(
                            "startDate" => date("d-m-Y", strtotime($start_date)),
                            "endDate" => date("d-m-Y", strtotime($dateToCheck))
                        ),
                        "totalPrice" => $sub_total_price
                    );
                    $price = $totalPrice;
                    if ($MasterProperty->gst_applicable == 1) {
                        $filter_res = array_filter($GstMin, function($n) use($price) { return $n <= $price; });

                        if (!empty($filter_res)) {
                            $tempr = $GstDetails[end($filter_res)];

                            if (!empty($tax_array)) {
                                foreach ($tempr as $g_name => $g_val) {
                                    $tax_amt = $price * ($g_val/100);
                                    $tax_array[$g_name] += $tax_amt;
                                }
                            } else {
                                foreach ($tempr as $g_name => $g_val) {
                                    $tax_amt = $price * ($g_val/100);
                                    $tax_array[$g_name] = $tax_amt;
                                }
                            }
                        }

                    }
                }
                $hallRoomBooking->pricing_details = $Pricing_data = $price_breakup;

                $GstShowData = array();$total_gst = $total_coupon_amt = $SubTotal = 0;

                foreach ($tax_array as $key => $val) {
                    $GstShowData[] = [
                        'gst_name' => $key,
                        'gst_percentage' => $tempr[$key],
                        'gst_value' => ceil($val)
                    ];
                    $total_gst += ceil($val);
                }
                $responce['gst_data'] = $GstShowData;
                $hallRoomBooking->subTotalPrice = ceil($sub_total_price);
                $hallRoomBooking->discountAmount = ceil($total_coupon_amt);
                $hallRoomBooking->totalOrderPrice = ceil($sub_total_price + $total_gst);
                $hallRoomBooking->extra_price = 0;
                $hallRoomBooking->slot_action = [
                    "slot"=>$slot,
                    "slot_type"=>$hallRoomBooking->slot_type
                ];
                $hallRoomBooking->slot_type = str_replace('_',' ',strtoupper($hallRoomBooking->slot_type));
                $responce['status'] = 1;
                $responce['booking_details'] = $hallRoomBooking;
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Invalid booking details!';
            }
            return $responce;
        }catch(\Exception $e){
            DB::rollback();
            return [
                'status'=>0,
                'message'=>'Unable to proceed. Please try after sometime '.$e->getMessage()
            ];
        }

    }

    private function caravanOrderPayment(Request $request){
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];

        $GSTData = GstDetail::pluck('value', 'name')->toArray();
        $responce['gst_data'] = [];
        $user = $request->user();
        $agent_comission = 0;
        $blockStat = 0;
        $agent_block_date = array();
        if (!empty($user)) {
            if ($user->access_type == 'agent') {
                $agent_comission = $user->agent_comission;
                $agent_block_date = !empty($user->agent_block_date) ? explode(',', $user->agent_block_date) : [];
            }
        }
        $CarBooking = CaravanBooking::where('booking_id', $request->bookingId)->first();
        if (!empty($CarBooking)) {
            $MasterCar = $CarDetails = MasterCaravan::find($CarBooking->caravan_id);
            $difference = strtotime($CarBooking->end_date) - strtotime($CarBooking->start_date);
            $days = $CarBooking->no_of_days;
            if (!empty($user)) {
                for ($i = 0; $i < $days; $i++) {
                    $checkInDate = date("Y-m-d", strtotime($CarBooking->start_date . ' + ' . $i . ' days'));
                    if (in_array($checkInDate, $agent_block_date)) {
                        $blockStat = 1;
                        break;
                    }
                }
                if (($user->access_type == 'agent' && $user->vendor_id != $MasterCar->vendor_id) || $blockStat == 1) {
                    $agent_comission = 0;
                }
            }
            $VendorDetails = User::find($MasterCar->vendor_id);
            $CarBooking->vendor_name = $VendorDetails->company;
            $CarBooking->vendor_id = $VendorDetails->id;
            $CarBooking->caravan_name = $MasterCar->title;
            $CarBooking->caravan_slug = $MasterCar->slug . '-' . $MasterCar->id;
            $CarBooking->caravan_image = $this->site . $MasterCar->feature_image;
            $CarBooking->caravan_address = $MasterCar->address;
            $CarBooking->caravan_city = $MasterCar->city;

            $CarBooking->hotel_name = $MasterCar->title;
            $CarBooking->service_fee = $MasterCar->service_fee;
            $CarBooking->gst_applicable = $MasterCar->gst_applicable;
            $CarBooking->price_breakup = json_decode($CarBooking->price_breakup, 1);
            $guide_fees = 0;
            if ($CarBooking->need_guide == 'Yes' && $CarBooking->days_for_guide > 0) {
                $guide_fees = $CarBooking->days_for_guide * $MasterCar->guide_price_per_day;
            }
            $CarBooking->guide_fees = $guide_fees;
            unset($CarBooking->start_time);
            unset($CarBooking->end_time);
            $GstDetails = array();
            $GstShowData = $tax_array = array();$total_gst = $total_coupon_amt = $SubTotal = 0;
            if ($MasterCar->gst_applicable == 1) {
                $GstTable = GstTable::where(['vendor_id' => $MasterCar->vendor_id, 'service_type' => 'caravan'])
                        ->orderBy('min_amount', 'asc')
                        ->pluck('gst', 'min_amount')->toArray();
                $GstDetails = array();
                if (!empty($GstTable)) {
                    foreach ($GstTable as $k => $gst) {
                        $GstDetails[$k] = json_decode($gst, 1);
                    }
                } else {
                    $GstDetails[0] = $GSTData;
                }
                $GstMin = array_keys($GstDetails);
            }


            $totalPrice = 0;
            $days = $CarBooking->no_of_days;
            $totalPrice = ($days * $CarDetails->price_per_day) * $CarBooking->total_caravans;

            $coupon_amt = round($totalPrice * ($agent_comission / 100), 2);
            $price = $totalPrice - $coupon_amt;
            $total_coupon_amt += $coupon_amt;
            $SubTotal += $price;
            if ($MasterCar->gst_applicable == 1) {
                $filter_res = array_filter($GstMin, function($n) use($price) { return $n <= $price; });
                if (!empty($filter_res)) {
                    $tempr = $GstDetails[end($filter_res)];
                    if (!empty($tax_array)) {
                        foreach ($tempr as $g_name => $g_val) {
                            $tax_amt = ceil($price * ($g_val/100));
                            $tax_array[$g_name] += $tax_amt;
                        }
                    } else {
                        foreach ($tempr as $g_name => $g_val) {
                            $tax_amt = ceil($price * ($g_val/100));
                            $tax_array[$g_name] = $tax_amt;
                        }
                    }
                }
            }

            foreach ($tax_array as $key => $val) {
                $GstShowData[] = [
                    'gst_name' => $key,
                    'gst_percentage' => $tempr[$key],
                    'gst_value' => round($val, 2)
                ];
                $total_gst += $val;
            }

            $CarBooking->discountAmount = round($total_coupon_amt, 2);
            $CarBooking->subTotalPrice = round($SubTotal, 2);
            $responce['gst_data'] = $GstShowData;
            $CarBooking->totalOrderPrice = round($SubTotal + $total_gst + $MasterCar->service_fee + $guide_fees, 2);

            $responce['status'] = 1;
            $responce['message'] = '';
            $responce['booking_details'] = $CarBooking;
        } else {
            $responce['status'] = 0;
            $responce['message'] = 'Invalid booking details!';
        }
        return $responce;
    }

    public function paytmSuccess(Request $request) {

        require_once public_path('paytm_lib/config_paytm.php');
        require_once public_path('paytm_lib/encdec_paytm.php');

        $param = base64_encode($request->ORDERID);
        $param = str_replace("=", "%3D", $param);

        $paytmChecksum = "";
        $paramList = array();
        $isValidChecksum = "FALSE";

        $paramList = $request->except('splitSettlementInfo');

        $paytmChecksum = isset($request->CHECKSUMHASH) ? $request->CHECKSUMHASH : "";

        //Verify all parameters received from Paytm pg to your application. Like MID received from paytm pg is same as your application’s MID, TXN_AMOUNT and ORDER_ID are same as what was sent by you to Paytm PG for initiating transaction etc.
        $isValidChecksum = verifychecksum_e($paramList, PAYTM_MERCHANT_KEY, $paytmChecksum);

        if ($isValidChecksum == "TRUE") {
            $PaymentHistory = PaymentHistory::where('transaction_id', $request->ORDERID)->first();

            if (!empty($PaymentHistory)) {
                if ($request->STATUS == "TXN_SUCCESS") {
                    if ($request->TXNAMOUNT == $PaymentHistory->amount) {
                        $requestParamList = array("MID" => PAYTM_MERCHANT_MID, "ORDERID" => $request->ORDERID);
                        $StatusCheckSum = getChecksumFromArray($requestParamList, PAYTM_MERCHANT_KEY);
                        $requestParamList['CHECKSUMHASH'] = $StatusCheckSum;
                        $responseParamList = getTxnStatusNew($requestParamList);

                        if (isset($responseParamList) && count($responseParamList) > 0 && $responseParamList['TXNAMOUNT'] == $request->TXNAMOUNT && $responseParamList['TXNID'] == $request->TXNID) {
                            $PaymentHistory->mihpayid = $request->TXNID;
                            $PaymentHistory->status = $request->STATUS;
                            $PaymentHistory->added_on = $request->TXNDATE;
                            $PaymentHistory->error = $request->RESPCODE;
                            $PaymentHistory->error_Message = $request->RESPMSG;
                            $PaymentHistory->payment_response = $request->all();
                            $PaymentHistory->save();

                            $OrderMaster = OrderMaster::where(['order_id' => $PaymentHistory->order_id, 'payment_id' => $PaymentHistory->id])->first();
