                    }
                }
                else {
                    $PaymentHistory->mihpayid = $request->TXNID;
                    $PaymentHistory->status = $request->STATUS;
                    $PaymentHistory->error = $request->RESPCODE;
                    $PaymentHistory->error_Message = $request->RESPMSG;
                    $PaymentHistory->payment_response = $request->all();
                    $PaymentHistory->save();

                    $OrderMaster = OrderMaster::where(['order_id' => $PaymentHistory->order_id, 'payment_id' => $PaymentHistory->id])->first();
                    $OrderMaster->payment_status = $request->STATUS;
                    $OrderMaster->save();

                    if ($OrderMaster->request_from == 'mobile') {
                        $responce['status'] = 0;
                        $responce['page'] = 'failure';
                        $responce["param"] = $param;
                        return response()->json($responce);
                    } else {
                        return redirect($this->frontendUrl . 'payment-failure/' . $param);
                    }
                }
            }
        } else {
            return redirect($this->frontendUrl .'transaction-failure/'. $param);
        }

        return redirect($this->frontendUrl .'transaction-failure/'. $param);
    }

    public function paymentSuccess(Request $request) {
        require_once public_path('paytm_lib/config_paytm.php');
        $param = base64_encode($request->txnid);
        $param = str_replace("=", "%3D", $param);
        if (isset($request->mihpayid)) {
            $PaymentHistory = PaymentHistory::where('transaction_id', $request->txnid)->first();
            if (!empty($PaymentHistory)) {
                $OrderMaster = OrderMaster::where(['order_id' => $PaymentHistory->order_id, 'payment_id' => $PaymentHistory->id])->first();
                $RequestFrom = $OrderMaster->request_from;
                if ($OrderMaster->status == 'cancelled') {
                    if ($OrderMaster->request_from == 'mobile') {
                        $responce['status'] = 0;
                        $responce['page'] = 'failure';
                        $responce["param"] = $param;
                        $responce['message'] = 'Transaction is failed.';
                        return response()->json($responce);
                    } else {
                        return redirect($this->frontendUrl .'payment-failure/'. $param);
                    }
                }

                if (!empty($OrderMaster->hdfc_key) && !empty($OrderMaster->hdfc_salt) && PAYTM_ENVIRONMENT == 'PROD') {
                    $HDFC_KEY = $OrderMaster->hdfc_key;
                    $HDFC_SALT = $OrderMaster->hdfc_salt;
                }

                $hash = hash('sha512', $HDFC_SALT .'|'. $request->status .'|||||||'. $PaymentHistory->udf4 .'|'. $PaymentHistory->udf3 .'|'. $PaymentHistory->udf2 .'|'. $PaymentHistory->udf1 .'|'. $PaymentHistory->email .'|'. $PaymentHistory->first_name .'|'. $PaymentHistory->product_info .'|'. $PaymentHistory->amount .'|'. $PaymentHistory->transaction_id .'|'. $HDFC_KEY);

                if ($hash == $request->hash && $request->unmappedstatus == 'captured' && $request->amount == $PaymentHistory->amount && $request->email == $PaymentHistory->email && $request->phone == $PaymentHistory->phone && $request->firstname == $PaymentHistory->first_name && $request->productinfo == $PaymentHistory->product_info && $request->udf1 == $PaymentHistory->udf1 && $request->udf2 == $PaymentHistory->udf2 && $request->udf3 == $PaymentHistory->udf3 && $request->udf4 == $PaymentHistory->udf4 && $request->key == $HDFC_KEY) {
                    // verify payment
                    $command = "verify_payment";
                    $var1 = $request->txnid;
                    $hash_str = $HDFC_KEY . '|' . $command . '|' . $var1 . '|' . $HDFC_SALT;
                    $hash_verify_payment = strtolower(hash('sha512', $hash_str));

                    $r = array('key' => $HDFC_KEY, 'hash' => $hash_verify_payment, 'var1' => $var1, 'command' => $command);
                    $qs = http_build_query($r);
                    $wsUrl = VERIFY_URL;
                    $c = curl_init();
                    curl_setopt($c, CURLOPT_URL, $wsUrl);
                    curl_setopt($c, CURLOPT_POST, 1);
                    curl_setopt($c, CURLOPT_POSTFIELDS, $qs);
                    curl_setopt($c, CURLOPT_CONNECTTIMEOUT, 30);
                    curl_setopt($c, CURLOPT_RETURNTRANSFER, 1);
                    curl_setopt($c, CURLOPT_SSL_VERIFYHOST, 0);
                    curl_setopt($c, CURLOPT_SSL_VERIFYPEER, 0);
                    $o = curl_exec($c);
                    // if (curl_errno($c)) {
                    //     $sad = curl_error($c);
                    //     throw new Exception($sad);
                    // }
                    curl_close($c);
                    $valueSerialized = @unserialize($o);
                    $verify_response = json_decode($o, true);
                    if (isset($verify_response['transaction_details'][$request->txnid])) {
                        $check_response = $verify_response['transaction_details'][$request->txnid];
                        if ($request->mihpayid == $check_response['mihpayid'] && $request->unmappedstatus == $check_response['unmappedstatus'] && $request->amount == $check_response['amt'] && $request->firstname == $check_response['firstname'] && $request->status == $check_response['status'] && $request->productinfo == $check_response['productinfo'] && $request->udf1 == $check_response['udf1'] && $request->udf2 == $check_response['udf2'] && $request->udf3 == $check_response['udf3'] && $request->udf4 == $check_response['udf4']) {
                            $PaymentHistory->mihpayid = $request->mihpayid;
                            $PaymentHistory->mode = $request->mode;
                            $PaymentHistory->status = $request->status;
                            $PaymentHistory->unmapped_status = $request->unmappedstatus;
                            $PaymentHistory->card_category = $request->cardCategory;
                            $PaymentHistory->discount = $request->discount;
                            $PaymentHistory->net_amount_debit = $request->net_amount_debit;
                            $PaymentHistory->added_on = $request->addedon;
                            $PaymentHistory->field1 = $request->field1;
                            $PaymentHistory->field2 = $request->field2;
                            $PaymentHistory->field3 = $request->field3;
                            $PaymentHistory->field4 = $request->field4;
                            $PaymentHistory->field5 = $request->field5;
                            $PaymentHistory->field6 = $request->field6;
                            $PaymentHistory->field7 = $request->field7;
                            $PaymentHistory->field8 = $request->field8;
                            $PaymentHistory->field9 = $request->field9;
                            $PaymentHistory->payment_source = $request->payment_source;
                            $PaymentHistory->PG_TYPE = $request->PG_TYPE;
                            $PaymentHistory->bank_ref_num = $request->bank_ref_num;
                            $PaymentHistory->bank_code = $request->bankcode;
                            $PaymentHistory->error = $request->error;
