    public function getSourceDetails($airportId=null){
        if($airportId){
            return AirportMaster::where('id', $airportId)->first();
        }
        return null;
    }

    public function getFarePrice($flightId, $schedule_id, $type='ADULT'){
        if(in_array($type, ['ADULT', 'INFANT'])){
            return FareMaster::where('flight_id', $flightId)->where('schedule_id', $schedule_id)->where('passenger_type', $type)->where('is_active',1)->first()->base_fare;
        }
    }

    public function paymentFailure(Request $request) {
        require_once public_path('paytm_lib/config_paytm.php');
        $param = base64_encode($request->txnid);
        $param = str_replace("=", "%3D", $param);

        if (isset($request->mihpayid)) {
            $PaymentHistory = PaymentHistory::where('transaction_id', $request->txnid)->first();
            if (!empty($PaymentHistory)) {
                $OrderMaster = OrderMaster::where(['order_id' => $PaymentHistory->order_id, 'payment_id' => $PaymentHistory->id])->first();
                if (!empty($OrderMaster->hdfc_key) && !empty($OrderMaster->hdfc_salt) && PAYTM_ENVIRONMENT == 'PROD') {
                    $HDFC_KEY = $OrderMaster->hdfc_key;
                    $HDFC_SALT = $OrderMaster->hdfc_salt;
                }

                $hash = hash('sha512', $HDFC_SALT .'|'. $request->status .'|||||||'. $PaymentHistory->udf4 .'|'. $PaymentHistory->udf3 .'|'. $PaymentHistory->udf2 .'|'. $PaymentHistory->udf1 .'|'. $PaymentHistory->email .'|'. $PaymentHistory->first_name .'|'. $PaymentHistory->product_info .'|'. $PaymentHistory->amount .'|'. $PaymentHistory->transaction_id .'|'. $HDFC_KEY);
                if ($hash == $request->hash) {
                    $PaymentHistory->mihpayid = $request->mihpayid;
                    $PaymentHistory->mode = $request->mode;
                    $PaymentHistory->status = $request->status;
                    $PaymentHistory->unmapped_status = $request->unmappedstatus;
                    $PaymentHistory->card_category = $request->cardCategory;
                    $PaymentHistory->discount = $request->discount;
                    $PaymentHistory->net_amount_debit = $request->net_amount_debit;
                    $PaymentHistory->added_on = $request->addedon;
                    $PaymentHistory->field1 = $request->field1;
                    $PaymentHistory->field2 = $request->field2;
                    $PaymentHistory->field3 = $request->field3;
                    $PaymentHistory->field4 = $request->field4;
                    $PaymentHistory->field5 = $request->field5;
                    $PaymentHistory->field6 = $request->field6;
                    $PaymentHistory->field7 = $request->field7;
                    $PaymentHistory->field8 = $request->field8;
                    $PaymentHistory->field9 = $request->field9;
                    $PaymentHistory->payment_source = $request->payment_source;
                    $PaymentHistory->PG_TYPE = $request->PG_TYPE;
                    $PaymentHistory->bank_ref_num = $request->bank_ref_num;
                    $PaymentHistory->bank_code = $request->bankcode;
                    $PaymentHistory->error = $request->error;
                    $PaymentHistory->error_Message = isset($request->error_Message) ? $request->error_Message : $request->Error_Message;
                    $PaymentHistory->name_on_card = $request->name_on_card;
                    $PaymentHistory->card_number = $request->cardnum;
                    $PaymentHistory->cardhash = $request->cardhash;
                    $PaymentHistory->payment_response = $request->all();
                    $PaymentHistory->save();

                    $OrderMaster->payment_status = $request->status;
                    $OrderMaster->save();

                    if($OrderMaster->service_type == 'flight'){
                        $flightBookingDetails = FlightBooking::where('booking_id', $OrderMaster->order_id)->first();
                        PassengerDetail::where('booking_id', $flightBookingDetails->booking_id)->update([
                            'order_status'=>2
                        ]);

                        FlightBooking::where('id', $flightBookingDetails->id)->update([
                            'payment_status'=>'CANCEL',
                            'booking_status'=>'CANCEL'
                        ]);

                        $departure = SeatInventory::where('date', $flightBookingDetails->onward_flight_date)->where('schedule_id',$flightBookingDetails->onward_schedule_id)->first();

                        if($departure->online_booked >= $flightBookingDetails->departure_adult_count){
                            $releaseSp = $this->releaseSeatBySp($flightBookingDetails->onward_schedule_id, $flightBookingDetails->onward_flight_date, $flightBookingDetails->departure_adult_count);

                            /* $departure->online_booked -= $flightBookingDetails->departure_adult_count;
                            $departure->save(); */
                        }

                        if(!empty($flightBookingDetails->return_schedule_id)){
                                // $return = SeatInventory::where('date', $flightBookingDetails->return_flight_date)->where('schedule_id', $flightBookingDetails->return_schedule_id)->first();
                                // if($return->online_booked >= $flightBookingDetails->return_adult_count){
                                //     $return->online_booked -= $flightBookingDetails->return_adult_count;
                                //     $return->save();
                                // }
                                $releaseSp = $this->releaseSeatBySp($flightBookingDetails->return_schedule_id, $flightBookingDetails->return_flight_date, $flightBookingDetails->return_adult_count);
                        }

                    }

                    if ($OrderMaster->request_from == 'mobile') {
                        $responce['status'] = 0;
                        $responce['page'] = 'failure';
                        $responce["param"] = $param;
                        $responce['message'] = $PaymentHistory->error_Message;
                        return response()->json($responce);
                    } else {
                        return redirect($this->frontendUrl .'payment-failure/'. $param);
                    }
                } else {
                    if ($OrderMaster->request_from == 'mobile') {
                        $responce['status'] = 0;
                        $responce['page'] = 'failure';
                        $responce["param"] = $param;
                        $responce['message'] = 'Error verifying payment. Transaction is tampered.';
                        return response()->json($responce);
                    } else {
                        return redirect($this->frontendUrl .'transaction-failure/'. $param);
                    }
                }
            }
        }
        return redirect($this->frontendUrl .'payment-failure/'. $param);
    }

