    public function paymentDetails(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'get_success_data') {
            $responce['message'] = '';
            $txn_id = base64_decode($request->txnId);
            $PaymentHistory = PaymentHistory::where('transaction_id', $txn_id)->first();
            if (!empty($PaymentHistory)) {
                $details['txn_id'] = ($PaymentHistory->payment_method == 'hdfc') ? $PaymentHistory->transaction_id : $PaymentHistory->mihpayid;
                $details['amount'] = $PaymentHistory->amount;
                $details['product_info'] = $PaymentHistory->product_info;
                $details['order_id'] = $PaymentHistory->order_id;
                $details['service'] = $PaymentHistory->udf4;
                $OrderMaster = OrderMaster::where(['invoice_id' => $PaymentHistory->udf1, 'payment_id' => $PaymentHistory->id])->first();
                if (!empty($OrderMaster)) {
                    $details['txn_id'] = $OrderMaster->transaction_id;
                    $details['invoice_id'] = $OrderMaster->invoice_id;
                    $details['orderId'] = $OrderMaster->id;
                    $details['confirm_voucher_ticket'] = $OrderMaster->confimation_voucher;
                    $details['qr_code'] =  !empty($OrderMaster->qr_code) ? $this->site . $OrderMaster->qr_code : '';
                    $search_string = '<td style="font-weight: bold;">Disclaimer: This is an electronically generated invoice, hence does not require a signature.</td>';
                    $replace_string = '';
                    if ($OrderMaster->service_type == 'hotel') {
                        $MasterHotel = MasterHotel::find($OrderMaster->service_name_id);
                        if (!empty($MasterHotel)) {
                            $replace_string = '<td><h3>Terms and Conditions:</h3>'. $MasterHotel->terms_conditions .'</td>';
                        }
                    } elseif ($OrderMaster->service_type == 'car') {
                        $MasterCar = MasterCar::find($OrderMaster->service_name_id);
                        if (!empty($MasterCar)) {
                            $replace_string = '<td><h3>Terms and Conditions:</h3>'. $MasterCar->terms_conditions .'</td>';
                        }
                    }elseif ($OrderMaster->service_type == 'caravan') {
                        $MasterCar = MasterCaravan::find($OrderMaster->service_name_id);
                        if (!empty($MasterCar)) {
                            $replace_string = '<td><h3>Terms and Conditions:</h3>'. $MasterCar->terms_conditions .'</td>';
                        }
                    } elseif ($OrderMaster->service_type == 'tour') {
                        $Tour = Tour::find($OrderMaster->service_name_id);
                        if (!empty($Tour)) {
                            $replace_string = '<td><h3>Terms and Conditions:</h3>'. $Tour->terms_conditions .'</td>';
                        }
                    } elseif ($OrderMaster->service_type == 'ticketing') {
                        $Ticket = Ticket::find($OrderMaster->service_name_id);
                        if (!empty($Ticket)) {
                            $replace_string = '<td><h3>Terms and Conditions:</h3>'. $Ticket->terms_conditions .'</td>';
                        }
                    }
                    $invoice = str_replace(array($search_string, '<title>Odisha Tourism</title>'), array($replace_string, ''), $OrderMaster->invoice);
                    $details['confirm_voucher'] = $invoice;
                }
                $responce['status'] = 1;
                $responce['data'] = $details;
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Invalid Transaction id.';
            }
        }
        elseif ($request->request_type == 'get_failure_data') {
            $responce['message'] = '';
            $txn_id = base64_decode($request->txnId);
            $PaymentHistory = PaymentHistory::where('transaction_id', $txn_id)->first();
            if (!empty($PaymentHistory)) {
                $details['txn_id'] = ($PaymentHistory->payment_method == 'hdfc') ? $PaymentHistory->transaction_id : $PaymentHistory->mihpayid;
                $details['amount'] = $PaymentHistory->amount;
                $details['product_info'] = $PaymentHistory->product_info;
                $details['invoice_id'] = $PaymentHistory->udf1;
                $details['error_message'] = $PaymentHistory->error_Message;

                $responce['status'] = 1;
                $responce['data'] = $details;
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Invalid Transaction id.';
            }
        }
        elseif ($request->request_type == 'download_invoice') {
            $responce['message'] = '';
            $OrderMaster = OrderMaster::find($request->orderId);

            if (!empty($OrderMaster)) {
                $final_html = parent::convert_image_base64($OrderMaster->invoice);
                // $final_html = $OrderMaster->invoice;

                $file_name = 'documents/'. $OrderMaster->invoice_id .'_invoice.pdf';
                $pdfname = public_path($file_name);
                PDF::loadHTML(html_entity_decode($final_html))->save($pdfname);

                if (isset($request->request_from) && $request->request_from == 'mobile') {
                    $responce['status'] = 1;
                    $responce['file_url'] = $this->site . $file_name;
                } else {
                    //return $OrderMaster->invoice;
                    return response()->download($pdfname)->deleteFileAfterSend(true);
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Invalid booking ID.';
            }
        }
        elseif ($request->request_type == 'download_voucher') {
            $responce['message'] = '';
            $OrderMaster = OrderMaster::find($request->orderId);
            if (!empty($OrderMaster)) {
                $final_html = parent::convert_image_base64($OrderMaster->confimation_voucher);
                // $html = $OrderMaster->confimation_voucher;
                $file_name = 'documents/'. $OrderMaster->invoice_id .'_voucher.pdf';
                $pdfname = public_path($file_name);
                PDF::loadHTML(html_entity_decode($final_html))->save($pdfname);

                if (isset($request->request_from) && $request->request_from == 'mobile') {
                    $responce['status'] = 1;
                    $responce['file_url'] = $this->site . $file_name;
                } else {
                    return response()->download($pdfname)->deleteFileAfterSend(true);
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Invalid booking ID.';
            }
        }
        elseif ($request->request_type == 'print_invoice') {
            $responce['message'] = '';
            $OrderMaster = OrderMaster::find($request->orderId);
            if (!empty($OrderMaster)) {
                $html = $OrderMaster->invoice;
                $responce['status'] = 1;
                $responce['data'] = $html;
            }
        }
        return response()->json($responce);
    }

    public function retryPayment(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'payment_retry') {
            $responce['message'] = '';
            $OrderMaster = OrderMaster::where('order_id', $request->orderId)->first();
            if (!empty($OrderMaster) && $OrderMaster->payment_status != 'success') {
                require_once public_path('paytm_lib/config_paytm.php');
                require_once public_path('paytm_lib/encdec_paytm.php');
                if ($OrderMaster->payment_gateway == 'hdfc') {
                    $OldPaymentHistory = PaymentHistory::find($OrderMaster->payment_id);

                    $payment_info = array();
                    $payment_info['txn_id'] = "TXN". time() . rand(10000, 99999999);
                    $payment_info['key'] = HDFC_KEY;
                    $payment_info['amount'] = $OrderMaster->total_order_price;
                    $payment_info['product_info'] = parent::cleanString($OrderMaster->service_name);
                    $payment_info['first_name'] = parent::cleanString($OldPaymentHistory->first_name);
                    $payment_info['last_name'] = parent::cleanString($OldPaymentHistory->last_name);
                    $payment_info['email'] = $OrderMaster->customer_email;
                    $payment_info['phone'] = $OrderMaster->customer_phone;
                    $payment_info['address1'] = parent::cleanString($OrderMaster->customer_address1);
                    $payment_info['address2'] = parent::cleanString($OrderMaster->customer_address2);
                    $payment_info['city'] = $OrderMaster->customer_city;
                    $payment_info['state'] = $OrderMaster->customer_state;
                    $payment_info['zipcode'] = $OrderMaster->customer_zipcode;
                    $payment_info['country'] = $OrderMaster->customer_country;
                    $payment_info['udf1'] = $OrderMaster->invoice_id;
                    $payment_info['udf2'] = $OrderMaster->vendor_id;
                    $payment_info['udf3'] = $OrderMaster->vendor_name;
                    $payment_info['udf4'] = $OrderMaster->service_type;
                    $payment_info['surl'] = 'payment_success';
                    $payment_info['furl'] = 'payment_failure';
                    $payment_info['curl'] = 'payment_cancel';
                    $payment_info['hash'] = hash('sha512', HDFC_KEY .'|'. $payment_info['txn_id'] .'|'. $payment_info['amount'] .'|'. $payment_info['product_info'] .'|'. $payment_info['first_name'] .'|'. $payment_info['email'] .'|'. $payment_info['udf1'] .'|'. $payment_info['udf2'] .'|'. $payment_info['udf3'] .'|'. $payment_info['udf4'] .'|||||||'. HDFC_SALT);

                    $PaymentHistoryNew = new PaymentHistory([
                        'order_id' => $OrderMaster->order_id,
                        'vendor_id' => $OrderMaster->vendor_id,
                        'user_id' => $OrderMaster->customer_id,
                        'payment_method' => 'hdfc',
                        'transaction_id' => $payment_info['txn_id'],
                        'amount' => $OrderMaster->total_order_price,
                        'product_info' => parent::cleanString($OrderMaster->service_name),
                        'first_name' => parent::cleanString($OldPaymentHistory->first_name),
                        'last_name' => parent::cleanString($OldPaymentHistory->last_name),
                        'email' => $OrderMaster->customer_email,
                        'phone' => $OrderMaster->customer_phone,
                        'address1' => parent::cleanString($OrderMaster->customer_address1),
                        'address2' => parent::cleanString($OrderMaster->customer_address2),
                        'city' => $OrderMaster->customer_city,
                        'state' => $OrderMaster->customer_state,
                        'country' => $OrderMaster->customer_country,
                        'zipcode' => $OrderMaster->customer_zipcode,
                        'udf1' => $OrderMaster->invoice_id,
                        'udf2' => $OrderMaster->vendor_id,
                        'udf3' => $OrderMaster->vendor_name,
                        'udf4' => $OrderMaster->service_type,
                        'status' => 'pending'
                    ]);
                    $PaymentHistoryNew->save();
                    $payment_id = $PaymentHistoryNew->id;

                    $OrderMaster->payment_id = $payment_id;
                    $OrderMaster->payment_status = 'pending';
                    $OrderMaster->transaction_id = $payment_info['txn_id'];
                    $OrderMaster->save();

                    $responce['status'] = 1;
                    $responce['data'] = $payment_info;
                    $responce['payment_gateway'] = 'hdfc';
                }
                elseif ($OrderMaster->payment_gateway == 'paytm') {
                    $paramList = array();
                    $ORDER_ID = "TXN" . time() . rand(10000, 99999999);
                    $CUST_ID = $OrderMaster->customer_id;
                    $INDUSTRY_TYPE_ID = INDUSTRY_TYPE_ID;
                    $CHANNEL_ID = CHANNEL_ID;
                    $TXN_AMOUNT = $OrderMaster->total_order_price;
                    // Create an array having all required parameters for creating checksum.
                    $paramList["MID"] = PAYTM_MERCHANT_MID;
                    $paramList["ORDER_ID"] = $ORDER_ID;
                    $paramList["CUST_ID"] = $CUST_ID;
                    $paramList["INDUSTRY_TYPE_ID"] = $INDUSTRY_TYPE_ID;
                    $paramList["CHANNEL_ID"] = $CHANNEL_ID;
                    $paramList["TXN_AMOUNT"] = $TXN_AMOUNT;
                    $paramList["WEBSITE"] = PAYTM_MERCHANT_WEBSITE;
                    $paramList["CALLBACK_URL"] = $this->site . "api/auth/paytm_success";
                    $paramList["MSISDN"] = $OrderMaster->customer_phone;
                    $paramList["EMAIL"] = $OrderMaster->customer_email;
                    $paramList["VERIFIED_BY"] = "EMAIL"; //
                    $paramList["IS_USER_VERIFIED"] = "YES"; //

                    $checkSum = getChecksumFromArray($paramList, PAYTM_MERCHANT_KEY);
                    $paramList["CHECKSUMHASH"] = $checkSum;
                    $paramList["PAYTM_TXN_URL"] = $PAYTM_TXN_URL;
                    $payment_info = $paramList;

                    $OldPaymentHistory = PaymentHistory::find($OrderMaster->payment_id);
                    $PaymentHistory = new PaymentHistory([
                        'order_id' => $OrderMaster->order_id,
                        'vendor_id' => $OrderMaster->vendor_id,
                        'user_id' => $OrderMaster->customer_id,
                        'payment_method' => 'paytm',
                        'transaction_id' => $ORDER_ID,
                        'amount' => $OrderMaster->total_order_price,
                        'product_info' => $OrderMaster->service_name,
                        'first_name' => $OldPaymentHistory->first_name,
                        'last_name' => $OldPaymentHistory->last_name,
                        'email' => $OrderMaster->customer_email,
                        'phone' => $OrderMaster->customer_phone,
                        'address1' => $OrderMaster->customer_address1,
                        'address2' => $OrderMaster->customer_address2,
                        'city' => $OrderMaster->customer_city,
                        'state' => $OrderMaster->customer_state,
                        'country' => $OrderMaster->customer_zipcode,
                        'zipcode' => $OrderMaster->customer_country,
                        'udf1' => $OrderMaster->invoice_id,
                        'udf2' => $OrderMaster->vendor_id,
                        'udf3' => $OrderMaster->vendor_name,
                        'udf4' => $OrderMaster->service_type,
                        'status' => 'pending'
                    ]);
                    $PaymentHistory->save();
                    $payment_id = $PaymentHistory->id;

                    OrderMaster::find($OrderMaster->id)->update(['payment_id' => $payment_id]);

                    $responce['status'] = 1;
                    $responce['data'] = $payment_info;
                    $responce['payment_gateway'] = 'paytm';
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Invalid order id.';
            }
        }
        return response()->json($responce);
    }

    public function cancelBookingRequest(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'view_refund_amount') {
            $responce['message'] = '';
            $OrderMaster = OrderMaster::find($request->ID);
            if (!empty($OrderMaster)) {
                $cancel_message = '';
                $Today = date("Y-m-d");
                $difference = strtotime($OrderMaster->start_date) - strtotime($Today);
                $days = round($difference / (60 * 60 * 24));
                if ($days == 0) {
                    $days = 1;
                }
                $service_type = $OrderMaster->service_type;
                if($OrderMaster->service_type == 'tour') {
                    $service_type = ($OrderMaster->service_category == 'sight seeing') ? 'sight-seeing' : 'package';
                }
                elseif($OrderMaster->service_type == 'car') {
                    $service_type = 'rental';
                }
                elseif($OrderMaster->service_type == 'ticketing') {
                    $service_type = str_replace(' ', '-', trim(strtolower($OrderMaster->service_category)));
                }
                $CancelPolicy = CancelPolicy::where(['vendor_id' => $OrderMaster->vendor_id, 'service_type' => $service_type])
                        ->whereRaw('start < '.$days)
                        ->whereRaw('end >='. $days)
                        ->first();
                $refund_percent = 100;
                if (!empty($CancelPolicy)) {
                    $refund_percent = $CancelPolicy->percent;
                }
                $refund_amount = $refund_tax = 0;
                if($OrderMaster->service_type == 'hotel') {
                    $policy[0] = 100;
                    $Today = date("Y-m-d H:i:s");
                    $HotelPolicy = CancelPolicy::where(['vendor_id' => $OrderMaster->vendor_id, 'service_type' => $service_type])->orderBy('start', 'asc')->pluck('percent', 'start')->toArray();
                    if (!empty($HotelPolicy)) {
                        $policy = $HotelPolicy;
                    }
                    $PolicyMin = array_keys($policy);
                    $OrderDetails = OrderDetail::where('order_master_id', $OrderMaster->id)->orderBy('start_date', 'asc')->get();
                    foreach ($OrderDetails as $key => $value) {
                        $diff = strtotime($value->start_date .' '. $OrderMaster->start_time) - strtotime($Today);
                        $day = $diff / (60 * 60 * 24);
                        if ($day == 0) {
                            $day = 1;
                        }
                        $filter_res = array_filter($PolicyMin, function($n) use($day) { return $n < $day; });
                        $ref_percent = $policy[end($filter_res)];
                        if ($key == 0 && $ref_percent == 100) {
                            $refund_tax = $OrderMaster->tax_amount;
                            $refund_amount = $OrderMaster->total_order_price;
                            break;
                        }
                        $ref_tax = ceil($value->tax_amount * ($ref_percent/100));
                        $ref_amt = ceil(($value->unit_total_price - $value->coupon_amount) * ($ref_percent/100)) + $ref_tax;
                        $refund_tax += $ref_tax;
                        $refund_amount += $ref_amt;
                    }
                    $refund_tax = round($refund_tax, 2);
                    $refund_amount = round($refund_amount, 2);
                }
                elseif ($service_type == 'package') {
                    $Tour = Tour::find($OrderMaster->service_name_id);
                    $child_policy = json_decode($Tour->child_price_policy, 1);
                    $refund_policy = array();
                    if ($OrderMaster->price_type == 'singleoccupancy') {
                        $refund_policy = json_decode($Tour->single_share_policy, 1);
                    } elseif ($OrderMaster->price_type == 'doubleoccupancy') {
                        $refund_policy = json_decode($Tour->double_share_policy, 1);
                    } else {
                        $refund_policy = json_decode($Tour->triple_share_policy, 1);
                    }
                    $policy_type = '';
                    if ($days > 7) {
                        $policy_type = 'refund_before_7d';
                    } elseif ($days <= 7 && $days > 1) {
                        $policy_type = 'refund_within_7d';
                    } else {
                        $policy_type = 'refund_within_24hr';
                    }
                    foreach ($refund_policy as $value) {
                        $refund_value = ceil(($value['price'] * $OrderMaster->total_adults) * ($value[$policy_type] / 100));
                        $refund_amount += $refund_value;
                    }

                    if ($OrderMaster->total_child > 0) {
                        foreach ($child_policy as $value) {
                            $refund_value = ceil(($value['price'] * $OrderMaster->total_child) * ($value[$policy_type] / 100));
                            $refund_amount += $refund_value;
                        }
                    }

                    if ($OrderMaster->tax_amount > 0) {
                        $GstTable = GstTable::where(['vendor_id' => $Tour->vendor_id, 'service_type' => $service_type])
                                ->where('min_amount', '<=', $OrderMaster->sub_total_price)
                                ->orderBy('min_amount', 'DESC')
                                ->first();
                        if (!empty($GstTable)) {
                            $GstData = json_decode($GstTable->gst, 1);
                            foreach ($GstData as $key => $val) {
                                $gst_val = ceil($refund_amount * ((float) $val / 100));
                                $refund_tax += $gst_val;
                            }
                        } else {
                            $GSTData = GstDetail::pluck('value', 'name')->toArray();
                            foreach ($GSTData as $key => $val) {
                                $gst_val = ceil($refund_amount * ((float) $val / 100));
                                $refund_tax += $gst_val;
                            }
                        }
                    }
                    $refund_tax = round($refund_tax, 2);
                    $refund_amount = round($refund_amount + $refund_tax, 2);
                }
                elseif ($service_type == 'rental') {
                    $refund_guide_charge = ($OrderMaster->guide_charge > 0) ? ceil($OrderMaster->guide_charge * ($refund_percent/100)) : 0;
                    $refund_tax = ceil($OrderMaster->tax_amount * ($refund_percent/100));
                    $refund_amount = ceil($OrderMaster->sub_total_price * ($refund_percent/100)) + $refund_tax + $refund_guide_charge;
                }elseif($OrderMaster->service_type == 'hall') {
                    $policy[0] = 100;
                    $Today = date("Y-m-d H:i:s");
                    $HotelPolicy = CancelPolicy::where(['vendor_id' => $OrderMaster->vendor_id, 'service_type' => $service_type])->orderBy('start', 'asc')->pluck('percent', 'start')->toArray();
                    if (!empty($HotelPolicy)) {
                        $policy = $HotelPolicy;
                    }
                    $PolicyMin = array_keys($policy);
                    $OrderDetails = OrderDetail::where('order_master_id', $OrderMaster->id)->orderBy('start_date', 'asc')->get();
                    foreach ($OrderDetails as $key => $value) {
                        $diff = strtotime($value->start_date .' '. $OrderMaster->start_time) - strtotime($Today);
                        $day = $diff / (60 * 60 * 24);
                        if ($day == 0) {
                            $day = 1;
                        }
                        $filter_res = array_filter($PolicyMin, function($n) use($day) { return $n < $day; });
                        $ref_percent = $policy[end($filter_res)];
                        if ($key == 0 && $ref_percent == 100) {
                            $refund_tax = $OrderMaster->tax_amount;
                            $refund_amount = $OrderMaster->total_order_price;
                            break;
                        }
                        $ref_tax = ceil($value->tax_amount * ($ref_percent/100));
                        $ref_amt = ceil(($value->unit_total_price - $value->coupon_amount) * ($ref_percent/100)) + $ref_tax;
                        $refund_tax += $ref_tax;
                        $refund_amount += $ref_amt;
                    }
                    $refund_tax = round($refund_tax, 2);
                    $refund_amount = round($refund_amount, 2);
                }
                else {
                    $refund_tax = ceil($OrderMaster->tax_amount * ($refund_percent/100));
                    $refund_amount = ceil($OrderMaster->sub_total_price * ($refund_percent/100)) + $refund_tax;
                }
                $responce['status'] = 1;
                $responce['sub_total'] = round($refund_amount - $refund_tax, 2);
                $responce['gst'] = $refund_tax;
                $responce['total_refund'] = $refund_amount;
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Invalid Order id';
            }
        }
        elseif ($request->request_type == 'request_for_cancel') {
            $responce['message'] = '';
            $OrderMaster = OrderMaster::find($request->ID);
            if (!empty($OrderMaster)) {
                $cancel_message = '';
                if ($request->cancel_type == 'partial') {
                    $RequestTemplate = EmailTemplate::where('ref_code', 'BookingRescheduleRequest')->first();
                    $Subject = $RequestTemplate->subject . ' - '. $OrderMaster->service_name .' - Booking ID - '. $OrderMaster->invoice_id;
                    $Message = str_replace(array("~website_url~", "~site_url~", "~invoiceid~", "~customername~", "~email~", "~phone~", "~servicename~", "~checkin~", "~checkout~", "~totalamount~", "~cancelreason~", "~canceldetails~"), array($this->frontendUrl, $this->site, $OrderMaster->invoice_id, $OrderMaster->customer_name, $OrderMaster->customer_email, $OrderMaster->customer_phone, $OrderMaster->service_name, $OrderMaster->start_date, $OrderMaster->end_date, number_format($OrderMaster->total_order_price, 2), $request->cancel_reason, $request->cancel_message), $RequestTemplate->source);
                    // $cancel_message = "Cancellation Details: ". $request->cancel_message ."<br>";
                    // $Subject = "Booking Cancel Request";
                    // $Message = "Order Id: ". $OrderMaster->order_id ."<br>"
                    //         . "Customer Name: ".  $OrderMaster->customer_name ."<br>"
                    //         . "Email: ". $OrderMaster->customer_email ."<br>"
                    //         . "Phone: ". $OrderMaster->customer_phone ."<br>"
                    //         . "Service Name: ". $OrderMaster->service_name ."<br>"
                    //         . "Cancel Type: ". $request->cancel_type ."<br>"
                    //         . "Cancel Reason: ". $request->cancel_reason ."<br>"
                    //         . $cancel_message
                    //         . "Total Amount Paid: ". (float)$OrderMaster->total_order_price;

                    $admin = User::where('role', 1)->first();
                    $Vendor = User::find($OrderMaster->vendor_id);
                    Mail::to($Vendor->email)
                            ->bcc($admin->email)
                            ->send(new \App\Mail\RegistrationMailUser($Message, $Subject));

                    $responce['status'] = 1;
                    $responce['message'] = 'Booking reschedule request sent successfully.';
                }
                else {
                    $Today = date("Y-m-d");
                    $difference = strtotime($OrderMaster->start_date) - strtotime($Today);
                    $days = round($difference / (60 * 60 * 24));
                    if ($days == 0) {
                        $days = 1;
                    }
                    $OrderMaster->status = 'cancelled';
                    $OrderMaster->cancel_reason = $request->cancel_reason;
                    $OrderMaster->cancel_date = date("Y-m-d H:i:s");

