                            $ref_tax = ceil($value->tax_amount * ($ref_percent/100));
                            $ref_amt = ceil(($value->unit_total_price - $value->coupon_amount) * ($ref_percent/100)) + $ref_tax;
                            $refund_tax += $ref_tax;
