                            parent::sendSms($OrderMaster->customer_phone, $sms_txt, $SmsTemplate->templete_id);
                            $mobileNumber = $User->phone;
                        }
                    }
                    $SmsTemplate = SmsTemplate::where('ref_code', 'BookingCancel')->first();
                    if (!empty($SmsTemplate)) {
                        $sms_txt = str_replace(array("~var1~", "~var2~", "~var3~", "~var4~", "~var5~", "~var6~", "~var7~"), array($OrderMaster->customer_name .',', $OrderMaster->service_name, $OrderMaster->invoice_id, number_format($refund_amount, 2), "\n", $OrderMaster->vendor_name, "\n\n"), $SmsTemplate->source);
                        parent::sendSms($mobileNumber, $sms_txt, $SmsTemplate->templete_id);
                    }
                    $Message .= '<div style="margin-top:30px;text-align:center;"><p style="font-family: Segoe UI;color:#333;">Feel free to <a href="https://www.bookodisha.com/tourism/contact">contact us</a> for any further questions or clarifications</p><p style="font-family: Segoe UI;color:#333;"><b>bookodisha.com support team</b></p><p style="font-family: Segoe UI;font-size:11px;color:#999;margin: 0px !important; ">Please do not reply to this message. This email address is automated for delivering outbound messages.<br> Please check the web site for more information&nbsp;<a href="https://www.bookodisha.com/" target="_blank">www.bookodisha.com</a> <br>Copyright &copy; 2022 Odisha Tourism. All rights reserved. <br /> <span style="font-size:16px;"> Powered by&nbsp;&nbsp;&copy;2022-2023&nbsp;<b>Privacy Policy</b><b>&nbsp;</b><b>|&nbsp;</b><b>Odisha Tourism Support</b></span></p><p>&nbsp;</p></div>';

                    $admin = User::where('role', 1)->first();
                    $bcc = [$Vendor->email, $admin->email];
                    if (!empty($service_email)) {
                        $bcc = array_merge($bcc, explode(',', $service_email));
                    }
                    try {
                        Mail::to($To)
                            ->bcc($bcc)
                            ->send(new \App\Mail\RegistrationMailUser($Message, $Subject));
                    }
                    catch(\Exception $e) {}
                    if (isset($request->request_from) && $request->request_from == 'mobile') {
                        $UserAppData = User::find($OrderMaster->customer_id);
                        if (!empty($UserAppData) && !empty($UserAppData->device_token)) {
                            $sms_txt = !empty($sms_txt) ? $sms_txt : 'Your booking is cancelled successfully.';
                            $sms_txt = str_replace(array("\n", 'bookodisha.com'), array("", ""), $sms_txt);
                            $sms_txt = substr_replace($sms_txt,", ", strrpos($sms_txt, ","), 1);
                            $msg_payload = array(
                                'mtitle'=> 'Booking Cancellation',
                                'mdesc' => $sms_txt,
                                'mdata' => array()
                            );
                            DB::table('notification_table')->insert([
                                'user_id' => $UserAppData->id,
                                'device_id' => $UserAppData->device_id,
                                'device_token' => $UserAppData->device_token,
                                'message' => $sms_txt,
                                'status' => 0,
                                'date_time' => date('Y-m-d H:i:s'),
                                'created_at' => date('Y-m-d H:i:s')
                            ]);
                            android($msg_payload, $UserAppData->device_token);
                        }
                    }
                    $responce['status'] = 1;
                    $responce['message'] = 'Booking cancelled successfully.';
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Invalid Order id.';
            }
        }
        return response()->json($responce);
    }

    public function couponDetails(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'get_available_coupons') {
            $responce['message'] = '';
            $start_date = '';
            if ($request->service_type == 'hotel') {
                $HotelBooking = HotelRoomBooking::where('booking_id', $request->bookingId)->first();
                if (!empty($HotelBooking)) {
                    $start_date = $HotelBooking->start_date;
                }
            }
            $coupons = Coupon::select('id', 'coupon_name', 'coupon_code', 'coupon_amount',  'description')
                    ->where(['service_type' => $request->service_type, 'vendor_id' => $request->vendor_id])
                    ->where('start_date', '<=', date("Y-m-d", strtotime($start_date)))
                    ->where('end_date', '>=', date("Y-m-d", strtotime($start_date)))
                    ->where('access_type', 'public')
                    ->where('status', 'publish')
                    ->get()->toArray();
            if (!empty($coupons)) {
                $responce['status'] = 1;
                $responce['data'] = $coupons;
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'No coupons available';
            }
        }
        elseif ($request->request_type == 'verify_coupon') {
            $responce['message'] = '';
            $book_date = date("Y-m-d");
            if ($request->service_type == 'hotel') {
                $HotelRoomBooking = HotelRoomBooking::where(['booking_id' => $request->bookingId, 'status' => 0])->first();
                $book_date = date("Y-m-d", strtotime($HotelRoomBooking->start_date));
            }

            $coupons = Coupon::where(['service_type' => $request->service_type, 'coupon_code' => $request->coupon_code])
                    ->where('start_date', '<=', $book_date)
                    ->where('end_date', '>=', $book_date)
                    ->where('status', 'publish')
                    ->first();
            $user = $request->user();
            if (!empty($coupons)) {
                $UserOrder = OrderMaster::select(DB::raw('count(coupon_code) AS totUsed'))
                        ->where(['customer_id' => $user->id, 'coupon_code' => $request->coupon_code])
                        ->where(function ($query) {
                            $query->where('status', 'completed');
                            $query->orWhere('status', 'pending');
                        })
                        ->first();
                $coupon_data = array();
                if ($coupons->coupon_use_type == 'single') {
                    if ($coupons->frequency > $coupons->already_used && $UserOrder->totUsed == 0) {
                        $coupon_data = array(
                            'coupon_name' => $coupons->coupon_name,
                            'coupon_code' => $coupons->coupon_code,
                            'coupon_value' => $coupons->coupon_amount,
                            'min_order_amount' => $coupons->min_order_amount
                        );
                        $responce['status'] = 1;
                    } else {
                        $responce['status'] = 0;
                        $responce['message'] = 'Coupon is not applicable.';
                    }
                } else {
                    if ($coupons->frequency > $coupons->already_used && $UserOrder->totUsed < $coupons->frequency_per_user) {
                        $coupon_data = array(
                            'coupon_name' => $coupons->coupon_name,
                            'coupon_code' => $coupons->coupon_code,
                            'coupon_value' => $coupons->coupon_amount,
                            'min_order_amount' => $coupons->min_order_amount
                        );
                        $responce['status'] = 1;
                    } else {
                        $responce['status'] = 0;
                        $responce['message'] = 'Coupon is not applicable.';
                    }
                }
                if ($responce['status'] == 1) {
                    $GSTData = GstDetail::pluck('value', 'name')->toArray();
                    if ($request->service_type == 'rental') {
                        $carBooking = CarBooking::where(['booking_id' => $request->bookingId, 'status' => 0])->first();
                        if (!empty($carBooking) && $coupons->vendor_id == $carBooking->vendor_id) {
                            if ($carBooking->totalPrice < $coupon_data['min_order_amount']) {
                                $responce['status'] = 0;
                                $responce['message'] = 'Sorry, coupon is applicable on minimum order value of ₹'. $coupon_data['min_order_amount'];
                            } else {
                                $MasterCar = MasterCar::find($carBooking->car_id);
                                $discount_amount = round(($carBooking->totalPrice * ($coupon_data['coupon_value'] / 100)), 2);
                                $SubTotal = round($carBooking->totalPrice - $discount_amount, 2);

                                $GstDetails = array();$total_gst = 0;
                                if ($MasterCar->gst_applicable == 1) {
                                    $GstTable = GstTable::where(['vendor_id' => $MasterCar->vendor_id, 'service_type' => 'rental'])
                                            ->where('min_amount', '<=', $carBooking->totalPrice)
                                            ->orderBy('min_amount', 'DESC')
                                            ->first();
                                    if (!empty($GstTable)) {
                                        $GstData = json_decode($GstTable->gst, 1);
                                        foreach ($GstData as $key => $val) {
                                            $gst_val = round($SubTotal * ((float) $val / 100), 2);
                                            $GstDetails[] = [
                                                'gst_name' => $key,
                                                'gst_percentage' => $val,
                                                'gst_value' => $gst_val
                                            ];
                                            $total_gst += $gst_val;
                                        }
                                    } else {
                                        foreach ($GSTData as $key => $val) {
                                            $gst_val = round($carBooking->totalPrice * ((float) $val / 100), 2);
                                            $GstDetails[] = [
                                                'gst_name' => $key,
                                                'gst_percentage' => $val,
                                                'gst_value' => $gst_val
                                            ];
                                            $total_gst += $gst_val;
                                        }
                                    }
                                }
                                $responce['sub_total_price'] = round($SubTotal, 2);
                                $responce['discount_amount'] = round($discount_amount, 2);
                                $responce['gst_data'] = $GstDetails;
                                $responce['totalOrderPrice'] = round($SubTotal + $total_gst + $MasterCar->service_fee, 2);
                                $responce['coupon_data'] = $coupon_data;
                            }
                        } else {
                            $responce['status'] = 0;
                            $responce['message'] = 'Sorry, coupon is not applicable.';
                        }
                    }
                    elseif ($request->service_type == 'hotel') {
                        $HotelRoomBooking = HotelRoomBooking::where(['booking_id' => $request->bookingId, 'status' => 0])->first();
                        if (!empty($HotelRoomBooking) && $coupons->vendor_id == $HotelRoomBooking->vendor_id) {
                            if ($HotelRoomBooking->totalPrice < $coupon_data['min_order_amount']) {
                                $responce['status'] = 0;
                                $responce['message'] = 'Sorry, coupon is applicable on minimum order value of ₹'. $coupon_data['min_order_amount'];
                            } else {
                                $room_details = json_decode($HotelRoomBooking->room_details, 1);
                                $Pricing_data = json_decode($HotelRoomBooking->pricing_details, 1);
                                if (count($room_details) > 1 && $coupons->multi_usage == 0) {
                                    $responce['status'] = 0;
                                    $responce['message'] = 'Sorry, maximum 1 room can be booked by using this coupon.';
                                } else {
                                    $days = 0;
                                    $MasterHotel = MasterHotel::find($HotelRoomBooking->hotel_id);

                                    if ($HotelRoomBooking->start_date == $HotelRoomBooking->end_date) {
                                        $HotelRoomBooking->night = $days = 1;
                                    } else {
                                        $difference = strtotime($HotelRoomBooking->end_date) - strtotime($HotelRoomBooking->start_date);
                                        $HotelRoomBooking->night = $days = round($difference / (60 * 60 * 24));
                                    }
                                    $extra_price = 0;
                                    $start_date = $HotelRoomBooking->start_date;
                                    $end_date = $HotelRoomBooking->end_date;
                                    if ($MasterHotel->gst_applicable == 1) {
                                        $GstTable = GstTable::where(['vendor_id' => $MasterHotel->vender_id, 'service_type' => 'hotel'])
                                                ->orderBy('min_amount', 'asc')
                                                ->pluck('gst', 'min_amount')->toArray();
                                        $GstDetails = array();
                                        if (!empty($GstTable)) {
                                            foreach ($GstTable as $k => $gst) {
                                                $GstDetails[$k] = json_decode($gst, 1);
                                            }
                                        } else {
                                            $GstDetails[0] = $GSTData;
                                        }
                                        $GstMin = array_keys($GstDetails);
                                    }
                                    $GstShowData = $tax_array = array();$total_gst = $total_coupon_amt = $SubTotal = 0;
                                    foreach ($room_details as $key => $value) {
                                        $extra_price = $value['extra_bed'] * $value['extra_bed_price'];
                                        for ($i = 0; $i < $days; $i++) {
                                            $checkInDate = date("Y-m-d", strtotime($start_date . ' + ' . $i . ' days'));
                                            $checkOutDate = date("Y-m-d", strtotime($start_date . ' + ' . ($i + 1) . ' days'));
                                            if ($start_date == $end_date) {
                                                $checkOutDate = $checkInDate;
                                            }
                                            $only_room_price = $Pricing_data[$value['id']][$checkInDate]['price'];
                                            $room_price = ($Pricing_data[$value['id']][$checkInDate]['price'] + $extra_price);
                                            $coupon_amt = $only_room_price * ($coupon_data['coupon_value']/100);
                                            $total_coupon_amt += $coupon_amt;
                                            $price = $room_price - $coupon_amt;
                                            $SubTotal += $price;
                                            if ($MasterHotel->gst_applicable == 1) {
                                                $filter_res = array_filter($GstMin, function($n) use($price) { return $n <= $price; });
                                                if (!empty($filter_res)) {
                                                    $tempr = $GstDetails[end($filter_res)];
                                                    if (!empty($tax_array)) {
                                                        foreach ($tempr as $g_name => $g_val) {
                                                            $tax_amt = $price * ($g_val/100);
                                                            $tax_array[$g_name] += $tax_amt;
                                                        }
                                                    } else {
                                                    foreach ($tempr as $g_name => $g_val) {
                                                            $tax_amt = $price * ($g_val/100);
                                                            $tax_array[$g_name] = $tax_amt;
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                    foreach ($tax_array as $key => $val) {
                                        $GstShowData[] = [
                                            'gst_name' => $key,
                                            'gst_percentage' => $tempr[$key],
                                            'gst_value' => ceil($val)
                                        ];
                                        $total_gst += ceil($val);
                                    }
                                    $responce['gst_data'] = $GstShowData;
                                    $responce['sub_total_price'] = ceil($SubTotal);
                                    $responce['discount_amount'] = ceil($total_coupon_amt);
                                    $responce['totalOrderPrice'] = ceil($SubTotal + $total_gst + $MasterHotel->service_fee);
                                    $responce['coupon_data'] = $coupon_data;
                                }
                            }
                        } else {
                            $responce['status'] = 0;
                            $responce['message'] = 'Sorry, coupon is not applicable.';
                        }
                    }
                }
            }
            else {
                $responce['status'] = 0;
                $responce['message'] = 'Invalid coupon code.';
            }
        }
        return response()->json($responce);
    }

    public function merchantDetails(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'get_merchant_list') {
            $responce['message'] = '';
            $sort_column = 'vendor_id';
            $sort_direction = 'asc';
            $MasterMerchantQuery = DB::table('merchant_products')
                    ->select('id', 'vendor_id', 'name', 'slug', 'sku', 'category', 'feature_image', 'price', 'max_quantity', 'status')
                    ->where('status', 'publish');
            if ($request->startPrice != '' && $request->endPrice != '') {
                $MasterMerchantQuery->whereBetween('price', [$request->startPrice, $request->endPrice]);
            }
            if (!empty($request->vendorId)) {
                $vendors = json_decode($request->vendorId, 1);
                $MasterMerchantQuery->whereIn('vendor_id', $vendors);
            }
            if ($request->sortColumn != '' && $request->direction != '') {
                $sort_column = $request->sortColumn;
                $sort_direction = $request->direction;
            }
            if ($request->category1 != '' && $request->category2 == '' && $request->category3 == '' && $request->category4 == '' && $request->category5 == '') {
                $allId = $this->getChildId($request->category1);
                $MasterMerchantQuery->whereIn('category',$allId);
            } elseif ($request->category1 != '' && $request->category2 != '' && $request->category3 == '' && $request->category4 == '' && $request->category5 == '') {
                $allId = $this->getChildId($request->category2);
                $MasterMerchantQuery->whereIn('category',$allId);
            } elseif ($request->category1 != '' && $request->category2 != '' && $request->category3 != '' && $request->category4 == '' && $request->category5 == '') {
                $allId = $this->getChildId($request->category3);
                $MasterMerchantQuery->whereIn('category',$allId);
            } elseif ($request->category1 != '' && $request->category2 != '' && $request->category3 != '' && $request->category4 != '' && $request->category5 == '') {
                $allId = $this->getChildId($request->category4);
                $MasterMerchantQuery->whereIn('category',$allId);
            } elseif ($request->category1 != '' && $request->category2 != '' && $request->category3 != '' && $request->category4 != '' && $request->category5 != '') {
                $allId = $this->getChildId($request->category5);
                $MasterMerchantQuery->whereIn('category',$allId);
            }
            $MasterMerchantQuery->orderBy($sort_column, $sort_direction);
            $take = 9;
            $skip = ($request->pageno == 0) ? $request->pageno : $request->pageno * $take;
            $totalData = $MasterMerchantQuery->count();

            $MasterMerchant = $MasterMerchantQuery->skip($skip)->take($take)->get()->toArray();
            if (!empty($MasterMerchant)) {
                foreach ($MasterMerchant as $key => $value) {
                    $MasterMerchant[$key]->feature_image = $this->site . $value->feature_image;
                    $MasterMerchant[$key]->availQnt = $value->max_quantity;
                    unset($MasterMerchant[$key]->max_quantity, $MasterMerchant[$key]->status);
                }
                $responce['totalPage'] = ceil($totalData / $take);
                $responce['length'] = $totalData;
                $responce['status'] = 1;
                $responce['data'] = $MasterMerchant;
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'No Merchant Product available';
                $responce['data'] = [];
            }
        }
        if ($request->request_type == 'get_merchant_list_app') {
            $responce['message'] = '';
            $sort_column = 'vendor_id';
            $sort_direction = 'asc';
            $MasterMerchantQuery = DB::table('merchant_products')
                    ->select('id', 'vendor_id', 'name', 'slug', 'sku', 'category', 'feature_image', 'price', 'max_quantity', 'status')
                    ->where('status', 'publish');
            if ($request->startPrice != '' && $request->endPrice != '') {
                $MasterMerchantQuery->whereBetween('price', [$request->startPrice, $request->endPrice]);
            }
            if (!empty($request->vendorId)) {
                $vendors = json_decode($request->vendorId, 1);
                $MasterMerchantQuery->whereIn('vendor_id', $vendors);
            }
            if ($request->sortColumn != '' && $request->direction != '') {
                $sort_column = $request->sortColumn;
                $sort_direction = $request->direction;
            }
            if (!empty($request->category1)) {
                $allId = $this->getChildId($request->category1);
                $MasterMerchantQuery->whereIn('category',$allId);
            }
            $MasterMerchantQuery->orderBy($sort_column, $sort_direction);
            $take = 9;
            $skip = ($request->pageno == 0) ? $request->pageno : $request->pageno * $take;
            $totalData = $MasterMerchantQuery->count();

            $MasterMerchant = $MasterMerchantQuery->skip($skip)->take($take)->get()->toArray();
            if (!empty($MasterMerchant)) {
                foreach ($MasterMerchant as $key => $value) {
                    $MasterMerchant[$key]->feature_image = $this->site . $value->feature_image;
                    $MasterMerchant[$key]->availQnt = $value->max_quantity;
                    unset($MasterMerchant[$key]->max_quantity, $MasterMerchant[$key]->status);
                }
                if (!empty($request->category1)) {
                    // $this->getParentData($request->category1);
                    // $this->AllCategories = array_reverse($this->AllCategories);
                    // $categoryId = $this->AllCategories[0]['id'];
                    if ($request->isChildCategory == 1) {
                        $responce['category_structure'] = [];
                    } else {
                        $ParentCategory = $this->getChildStructure($request->category1);
                        $responce['category_structure'][] = $ParentCategory;
                    }
                }

                $responce['totalPage'] = ceil($totalData / $take);
                $responce['length'] = $totalData;
                $responce['status'] = 1;
                $responce['data'] = $MasterMerchant;
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'No Merchant Product available';
                $responce['data'] = [];
            }
        }
        elseif ($request->request_type == 'get_merchant_details') {
            $responce['message'] = '';
            if (isset($request->slug)) {
                $MasterMerchant = MerchantProduct::where(['slug' => $request->slug, 'status' => 'publish'])->first();
            } else {
                $MasterMerchant = MerchantProduct::where(['id' => $request->merchantId, 'status' => 'publish'])->first();
            }
            if (!empty($MasterMerchant)) {
                $UserData = User::find($MasterMerchant->vendor_id);
                // $MasterMerchant->slug .= '-'. $MasterMerchant->id;
                $MasterMerchant->vendor_name = $UserData->company;
                $MasterMerchant->vendor_email = $UserData->email;
                $MasterMerchant->vendor_image = $this->site . $UserData->photo;
                $MasterMerchant->member_since = date("M Y", strtotime($UserData->created_at));
                $MasterMerchant->descriptions_app = strip_tags($MasterMerchant->descriptions);

                $vendor_profile = VendorProfile::where('vendor_id', $MasterMerchant->vendor_id)->first();
                if (!empty($vendor_profile)) {
                    $MasterMerchant->vendor_profile = $vendor_profile->profile_type;
                    if ($vendor_profile->profile_type == 'own') {
                        $MasterMerchant->vendor_slug = !empty($vendor_profile->profile_url) ? $vendor_profile->profile_url : 'javascript:void(0)';
                    } else {
                        $MasterMerchant->vendor_slug = $vendor_profile->slug;
                    }
                } else {
                    $MasterMerchant->vendor_slug = '';
                }

                $MasterMerchant->feature_image = !empty($MasterMerchant->feature_image) ? $this->site . $MasterMerchant->feature_image : $MasterMerchant->feature_image;
                //    $cat_arr = explode(',', $MasterMerchant->category);

                $related_products = MerchantProduct::select('id', 'name', 'slug', 'feature_image', 'price', 'max_quantity as availQnt')
                        ->whereRaw("find_in_set('". $MasterMerchant->category ."',category)")
                        ->where(['status' => 'publish'])
                        ->where('id', '!=', $MasterMerchant->id)
                        ->limit(4)
                        ->get()->toArray();
                if (!empty($related_products)) {
                    foreach ($related_products as $key => $value) {
                        $related_products[$key]['feature_image'] = $this->site . $value['feature_image'];
                    }
                }
                $MasterMerchant->related_products = $related_products;

                $this->getParentData($MasterMerchant->category);
                $this->AllCategories = array_reverse($this->AllCategories);
                $MasterMerchant->category = $this->AllCategories;
                $MasterMerchant->properties = json_decode($MasterMerchant->properties, 1);
                if (!empty($MasterMerchant->gallery_image)) {
                    $merchant_gallery = json_decode($MasterMerchant->gallery_image);
                    $MasterMerchant->gallery_image = array_map(function($val) {
                        return $this->site . $val;
                    }, $merchant_gallery);
                }

                $responce['status'] = 1;
                $responce['data'] = $MasterMerchant;
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Merchant product not available';
            }
        }
        elseif ($request->request_type == 'get_sort_params') {
            $responce['message'] = '';
            $sortData = array(
                ['key' => 'price', 'value' => 'asc', 'html' => 'Price (Low to high)'],
                ['key' => 'price', 'value' => 'desc', 'html' => 'Price (High to low)'],
                ['key' => 'review_count', 'value' => 'desc', 'html' => 'Average Rating'],
                ['key' => 'created_at', 'value' => 'desc', 'html' => 'Latest']
            );
            $responce['status'] = 1;
            $responce['data'] = $sortData;
        }
        elseif ($request->request_type == 'get_parent_categories') {
            $responce['message'] = '';
            $ParentCategory = CategoryTable::select('id', 'category_name', 'image')->where('parent_id', 0)->get();
            foreach ($ParentCategory as $value) {
                $value->image = !empty($value->image) ? $this->site . $value->image : '';
            }
            $responce['status'] = 1;
            $responce['data'] = $ParentCategory;
        }
        elseif($request->request_type == 'get_child_categories') {
            $responce['message'] = '';
            $ParentCategory = $this->getChildStructure($request->categoryId);
            $responce['status'] = 1;
            $responce['data'] = $ParentCategory->subcategory;
        }
        elseif($request->request_type == 'search_products') {
            $responce['message'] = '';
            $result = array();
            if (!empty($request->search_key)) {
                $searchKey = $request->search_key;
                $categoryTable = CategoryTable::where('category_name', 'like', '%'. $searchKey .'%')->get();
                if (!empty($categoryTable)) {
                    foreach ($categoryTable as $value) {
                        $parent_name = $value->category_name;
                        if ($value->parent_id != 0) {
                            $ParentCategory = categoryTable::find($value->parent_id);
                            $parent_name = $ParentCategory->category_name;
                        }
                        $result[] = array(
                            'id' => $value->id,
                            'title' => $value->category_name,
                            'parent_name' => $parent_name
                        );
                    }
                }
                $Products = MerchantProduct::where('name', 'like', '%'. $searchKey .'%')->get();
                if (!empty($Products)) {
                    foreach ($Products as $value) {
                        $parent_name = '';
                        $ParentCategory = categoryTable::find($value->category);
                        if (!empty($ParentCategory)) {
                            $parent_name = $ParentCategory->category_name;
                        }
                        $result[] = array(
                            'id' => $value->category,
                            'title' => $value->name,
                            'parent_name' => $parent_name
                        );
                    }
                }
            }
            $responce['status'] = 1;
            $responce['data'] = $result;
        }
        return response()->json($responce);
    }

    public function getChildStructure($id = null) {
        $ParentCategory = CategoryTable::find($id);
        $ParentCategory->subcategoryname = $ParentCategory->category_name;
        $ParentCategory->url_name = $ParentCategory->slug.'-'.$ParentCategory->id;
        $ParentCategory->subcategoryname = $ParentCategory->category_name;
        $ParentCategory->totalProduct = $this->getProductTotal($ParentCategory->id);
        unset($ParentCategory->slug,$ParentCategory->category_name,$ParentCategory->created_by,$ParentCategory->created_at,$ParentCategory->updated_at);
        if(count($ParentCategory->subcategory)){
            foreach ($ParentCategory->subcategory as $category1) {
                $category1['url_name'] = $category1['slug'].'-'.$category1['id'];
                $category1['subcategoryname'] = $category1['category_name'];
                $category1['totalProduct'] = $this->getProductTotal($category1['id']);
                unset($category1['slug'],$category1['category_name'],$category1['created_by'],$category1['created_at'],$category1['updated_at']);
                if(count($category1->subcategory)){
                    foreach ($category1->subcategory as  $category2) {
                        $category2['url_name'] = $category2['slug'].'-'.$category2['id'];
                        $category2['subcategoryname'] = $category2['category_name'];
                        $category2['totalProduct'] = $this->getProductTotal($category2['id']);
                        unset($category2['slug'],$category2['category_name'],$category2['created_by'],$category2['created_at'],$category2['updated_at']);
                        if(count($category2->subcategory)){
                            foreach ($category2->subcategory as  $category3) {
                                $category3['url_name'] = $category3['slug'].'-'.$category3['id'];
                                $category3['subcategoryname'] = $category3['category_name'];
                                $category3['totalProduct'] = $this->getProductTotal($category3['id']);
                                unset($category3['slug'],$category3['category_name'],$category3['created_by'],$category3['created_at'],$category3['updated_at']);
                                if(count($category3->subcategory)){
                                    foreach ($category3->subcategory as  $category4) {
                                        $category4['url_name'] = $category4['slug'].'-'.$category4['id'];
                                        $category4['subcategoryname'] = $category4['category_name'];
                                        $category4['totalProduct'] = $this->getProductTotal($category4['id']);
                                        unset($category4['slug'],$category4['category_name'],$category4['created_by'],$category4['created_at'],$category4['updated_at']);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        return $ParentCategory;
    }

    public function getParentData($id = null) {

        $Categoriesdata = CategoryTable::where('id', $id)->get()->toArray();
        $subcategoryItem = array();
        $subcategoryItem['id'] = $Categoriesdata[0]['id'];
        $subcategoryItem['category_name'] = $Categoriesdata[0]['category_name'];
        $subcategoryItem['slug'] = $Categoriesdata[0]['slug'] . '-' . $Categoriesdata[0]['id'];


        array_push($this->AllCategories, $subcategoryItem);
        if ($Categoriesdata[0]['parent_id'] != 0) {
            //return $this->AllCategories;
            //return $Categoriesdata[0]['parent_id'];

            self::getParentData($Categoriesdata[0]['parent_id']);
        }
    }

    public function getChildId($id = null) {
        $ParentCategory = CategoryTable::where('parent_id', $id)->get();
        $allChild = array();
        foreach ($ParentCategory as $category) {
            array_push($allChild, $category['id']);
            if (count($category->subcategory)) {
                foreach ($category->subcategory as $category1) {
                    array_push($allChild, $category1['id']);
                    if (count($category->subcategory)) {
                        foreach ($category1->subcategory as $category2) {
                            array_push($allChild, $category2['id']);
                            if (count($category2->subcategory)) {
                                foreach ($category2->subcategory as $category3) {
                                    array_push($allChild, $category3['id']);
                                }
                            }
                        }
                    }
                }
            }
        }
        array_push($allChild, $id);
        return $allChild;
    }

    public function merchantBooking(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'book_merchant') {
            $responce['message'] = '';
            $responce['status'] = 1;
            $user = $request->user();
            $booking_id = '';
            $item_details = array();
            $total_price = 0;
            $request_items = json_decode($request->cart_items, 1);
            if (!empty($request_items)) {
                foreach ($request_items as $value) {
                    $ItemDetails = MerchantProduct::where(['id'=> $value['id'], 'status' => 'publish'])->first(); //find($value['id']);
                    $temp = array();
                    if (!empty($ItemDetails)) {
                        if ($ItemDetails->max_quantity >= $value['quantity']) {
                            $temp['unitPrice'] = (float)$ItemDetails->price;
                            $temp['itemName'] = $ItemDetails->name;
                            $temp['id'] = $ItemDetails->id;
                            $temp['vendor_id'] = $ItemDetails->vendor_id;
                            $temp['itemQuantity'] = $value['quantity'];
                            $temp['itemPrice'] = round(($ItemDetails->price * $value['quantity']), 2);
                            $total_price += $temp['itemPrice'];
                            array_push($item_details, $temp);
                        } else {
                            $responce['status'] = 0;
                            $responce['message'] = 'Sorry! The maximum quantity for '. $ItemDetails->name. ' is '. $ItemDetails->max_quantity .'.';
                            return response()->json($responce);
                            // break;
                        }
                    }
                }
            }
            if ($total_price > 0) {
                $lastIdData = OrderMaster::orderBy('id', 'desc')->first();
                $lastId = !empty($lastIdData) ? $lastIdData->id + 1 : 1;
                $booking_id = 'OT-'. time() .'-M-'. $lastId;

                $MerchantBooking = new MerchantBooking([
                    // 'vendor_id' => $request->vendorId,
                    'booking_id' => $booking_id,
                    'item_request' => $request->cart_items,
                    'item_details' => json_encode($item_details),
                    'total_price' => round($total_price, 2),
                    'user_type' => !empty($user) ? 'registered' : 'guest',
                    'create_user' => !empty($user) ? $user->id : null,
                ]);
                if ($MerchantBooking->save()) {
                    $responce['status'] = 1;
                    $responce['booking_id'] = $booking_id;
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Unable to book, please try again.';
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Unable to book, please try again.';
            }
        }
        return response()->json($responce);
    }

    // Mobile App
    public function userLoginSignUp(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'generate_otp') {
            $error = 0;
            if ($request->input_type == 'mobile') {
                $validate = Validator::make($request->all(), [
                    'input_data' => 'required|digits:10',
                ]);
                if ($validate->fails()) {
                    $errors = $validate->errors();
                    if ($errors->has('input_data')) {
                        $responce['message'] = 'Please enter a valid mobile number.';
                    }
                    $responce['status'] = 0;
                    $error = 1;
                }
            } elseif ($request->input_type == 'email') {
                $validate = Validator::make($request->all(), [
                    'input_data' => 'required|email',
                ]);
                if ($validate->fails()) {
                    $errors = $validate->errors();
                    if ($errors->has('input_data')) {
                        $responce['message'] = 'Please enter a valid email.';
                    }
                    $responce['status'] = 0;
                    $error = 1;
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Invalid input data';
            }
            if ($error == 0) {
                if ($request->request_from && $request->request_from == 'web') {
                    $responce['is_reset_password'] = 0;
                    $field = ($request->input_type == 'email') ? 'email' : 'phone';
                    $GuestUser = User::where($field, $request->input_data)->first();
                    if (empty($GuestUser)) {
                        $responce['status'] = 0;
                        $responce['message'] = 'You are not registered with us. Please sign up.';
                        return response()->json($responce);
                    }
                    elseif (!empty($GuestUser) && $GuestUser->create_account_approval == 0) {
                        $responce['is_reset_password'] = 1;
                    }
                }
                $otp = mt_rand(1000, 9999);
                if ($request->input_type == 'mobile' && $request->input_data == '9652581973') {
                    $otp = '1111';
                }
                DB::table('temp_otp')->updateOrInsert(
                    ['device_detail' => $request->input_data],
                    ['otp' => $otp, 'updated_at' => date('Y-m-d H:i:s')]
                );
                if ($request->input_type == 'mobile') {
                    $SmsTemplate = SmsTemplate::where('ref_code', 'MobileOtpLogin')->first();
                    $msg = str_replace(array("~var1~", "~var2~", "~var3~", "~var4~", "~var5~"), array("user,\n", $otp .".\n", "\n", "\nOTDC", "\n\n"), $SmsTemplate->source);
                    parent::sendSms($request->input_data, $msg, $SmsTemplate->templete_id);
                } else {
                    $OTPTemplete = EmailTemplate::where('ref_code', 'OTPToUser')->first();
                    if (!empty($OTPTemplete)) {
                        $Message = str_replace(array("~var1~", "~website_url~"), array($otp, $this->site), $OTPTemplete->source);
                        $Subject = $OTPTemplete->subject;
                        Mail::to($request->input_data)->send(new \App\Mail\ForgotPasswordMail($Message, $Subject));
                    }
                }
                $responce['status'] = 1;
                $responce['message'] = 'OTP sent successfully';
            }
        }
        elseif ($request->request_type == 'verify_otp') {
            $validate = Validator::make($request->all(), [
                'input_data' => 'required',
                'otp' => 'required|digits:4',
                'input_type' => 'required|string',
                'device_id' => 'required',
                'device_token' => 'required',
                'device_type' => 'required|string'
            ]);
            if ($validate->fails()) {
                $errors = $validate->errors();
                if ($errors->has('input_data')) {
                    $responce['message'] = 'Please enter a valid mobile number or email.';
                } elseif ($errors->has('otp')) {
                    $responce['message'] = $errors->first('otp');
                } elseif ($errors->has('input_type')) {
                    $responce['message'] = $errors->first('input_type');
                } elseif ($errors->has('device_id')) {
                    $responce['message'] = $errors->first('device_id');
                } elseif ($errors->has('device_token')) {
                    $responce['message'] = $errors->first('device_token');
                } elseif ($errors->has('device_type')) {
                    $responce['message'] = $errors->first('device_type');
                }
                $responce['status'] = 0;
            } else {
                $NOWDATETIME = date("Y-m-d H:i:s");
                $TempOtp = TempOtp::where(['device_detail' => $request->input_data, 'otp' => $request->otp])
                        ->whereRaw('updated_at > DATE_SUB("'. $NOWDATETIME .'",INTERVAL 10 MINUTE)')
                        ->first();
                if (!empty($TempOtp)) {
                    $field = ($request->input_type == 'email') ? 'email' : 'phone';
                    $UserDetails = User::where($field, $request->input_data)->first();

                    if (!empty($UserDetails)) {
                        if ($UserDetails->create_account_approval == 0 && ($request->device_type == 'android' || $request->device_type == 'ios')) {
                            $responce['is_existing_user'] = 0;
                            $responce['status'] = 1;
                            $responce['message'] = 'OTP verification successful.';
                            return response()->json($responce);
                        }
                        if ($request->request_from && $request->request_from == 'web') {
                            if ($UserDetails->create_account_approval == 0  && !empty($request->password) && !empty($request->password_confirmation)) {
                                $UserDetails->password = bcrypt($request->password);
                                $UserDetails->create_account_approval = 1;
                                $UserDetails->status == 1;
                                $UserDetails->save();
                            }
                            else {
                                if (empty($UserDetails->email_verified_at)) {
                                    $responce['status'] = 0;
                                    $responce['message'] = "Please verfify your email address before login.";
                                    return response()->json($responce);
                                }
                                if ($UserDetails->status == 0) {
                                    $responce['status'] = 0;
                                    $responce['message'] = 'Your account is deactivated. Please contact admin to activate your account.';
                                    return response()->json($responce);
                                }
                            }
                            $tokenResult = $UserDetails->createToken('Personal Access Token');
                            $token = $tokenResult->token;
                            $token->expires_at = Carbon::now()->addMinute(120);
                            $token->save();

                            $responce['status'] = 1;
                            $responce['message'] = "Welcome ". $UserDetails->first_name;
                            $responce['token'] = $tokenResult->accessToken;
                            $responce['token_expire'] = Carbon::parse($tokenResult->token->expires_at)->toDateTimeString();
                            return response()->json($responce);

                        }
                        if ($UserDetails->status == 0) {
                            $responce['status'] = 0;
                            $responce['message'] = 'Your account is deactivated. Please contact admin to activate your account.';
                            return response()->json($responce);
                        }
                        $UserDetails->device_id = $request->device_id;
                        $UserDetails->device_token = $request->device_token;
                        $UserDetails->device_type = $request->device_type;
                        $UserDetails->save();

                        $accessToken = $this->generateAccessToken($UserDetails->id);
                        $City = City::pluck('name', 'id')->toArray();
                        $State = State::pluck('name', 'id')->toArray();
                        $Country = Country::pluck('name', 'id')->toArray();
                        $UserDetails->photo = !empty($UserDetails->photo) ? $this->site . $UserDetails->photo : $this->site .'images/profile/no-image.png';
                        $UserDetails->country_name = !empty($UserDetails->country) ? $Country[$UserDetails->country] : '';
                        $UserDetails->state_name = !empty($UserDetails->state) ? $State[$UserDetails->state] : '';
                        $UserDetails->city_name = !empty($UserDetails->city) ? $City[$UserDetails->city] : '';

                        $responce['profile_data'] = $UserDetails;
                        $responce['is_existing_user'] = 1;
                        $responce['access_token'] = $accessToken->accessToken;
                        $responce['status'] = 1;
                        $responce['message'] = "Welcome ". $UserDetails->first_name;
                    } else {
                        $responce['is_existing_user'] = 0;
                        $responce['status'] = 1;
                        $responce['message'] = 'OTP verification successful.';
                    }
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Invalid OTP';
                }
            }
        }
        elseif ($request->request_type == 'create_user') {
            $Check = $lastId = 0;
            $GuestUser = User::where('create_account_approval', 0)
                        ->where(function ($query) use($request) {
                            $query->where('email', $request->email);
                            $query->orWhere('phone', $request->phone);
                        })
                        ->first();
            if (!empty($GuestUser)) {
                $ExistUser = User::where('create_account_approval', 1)
                            ->where(function ($query) use($request) {
                                $query->where('email', $request->email);
                                $query->orWhere('phone', $request->phone);
                            })
                            ->first();
                if (!empty($ExistUser)) {
                    if ($ExistUser->email == $request->email) {
                        $responce['message'] = 'An account with this email already exist. Please use different email.';
                    }
                    elseif ($ExistUser->phone == $request->phone) {
                        $responce['message'] = 'An account with this phone number already exist. Please use different phone number.';
                    }
                    $responce['status'] = 0;
                    return response()->json($responce);
                }
                $validate = Validator::make($request->all(), [
                    'first_name' => 'required|string|min:3|max:64',
                    'last_name' => 'required|string|min:3|max:64',
                    'email' => 'required|email',
                    'password' => 'required|string|min:6|confirmed',
                    'phone' => 'required|digits:10',
                    'device_id' => 'required',
                    'device_token' => 'required',
                    'device_type' => 'required|string',
                ]);

                if ($validate->fails()) {
                    $responce['status'] = 0;

                    // Error messages
                    $errors = $validate->errors();
                    if ($errors->has('email')) {
                        $responce['message'] = $errors->first('email');
                    } elseif ($errors->has('first_name')) {
                        $responce['message'] = $errors->first('first_name');
                    } elseif ($errors->has('last_name')) {
                        $responce['message'] = $errors->first('last_name');
                    } elseif ($errors->has('password')) {
                        $responce['message'] = $errors->first('password');
                    } elseif ($errors->has('phone')) {
                        $responce['message'] = $errors->first('phone');
                    } elseif ($errors->has('device_id')) {
                        $responce['message'] = $errors->first('device_id');
                    } elseif ($errors->has('device_token')) {
                        $responce['message'] = $errors->first('device_token');
                    } elseif ($errors->has('device_type')) {
                        $responce['message'] = $errors->first('device_type');
                    }
                    return response()->json($responce);
                } else {
                    $GuestUser->first_name = $request->first_name;
                    $GuestUser->last_name = $request->last_name;
                    $GuestUser->email = $request->email;
                    $GuestUser->phone = $request->phone;
                    $GuestUser->password = bcrypt($request->password);
