            } else {
                $userId = $userName = $userEmail = '';
                $socical_data = json_decode($request->socical_data, 1);
                if ($request->login_type == 'google') {
                    $userId = isset($socical_data['user']['id']) ? $socical_data['user']['id'] : '';
                    $userName = isset($socical_data['user']['name']) ? $socical_data['user']['name'] : '';
                    $userEmail = isset($socical_data['user']['email']) ? $socical_data['user']['email'] : '';
                    $idToken = isset($socical_data['idToken']) ? $socical_data['idToken'] : '';
                    if (!empty($idToken) && !empty($userEmail)) {
                        $curl = curl_init();
                        curl_setopt_array($curl, array(
                            CURLOPT_URL => 'https://oauth2.googleapis.com/tokeninfo?id_token='. $idToken,
                            CURLOPT_RETURNTRANSFER => true,
                            CURLOPT_ENCODING => '',
                            CURLOPT_MAXREDIRS => 10,
                            CURLOPT_TIMEOUT => 0,
                            CURLOPT_FOLLOWLOCATION => true,
                            CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
                            CURLOPT_CUSTOMREQUEST => 'GET',
                        ));
                        $curl_response = curl_exec($curl);
                        curl_close($curl);
                        $verify_response = json_decode($curl_response, 1);
                        $response_email = isset($verify_response['email']) ? $verify_response['email'] : '';
                        $response_email_verified = isset($verify_response['email_verified']) ? $verify_response['email_verified'] : '';
                        $reaponse_uid = isset($verify_response['sub']) ? $verify_response['sub'] : '';
                        if ($userEmail != $response_email || $response_email_verified != 'true' || $reaponse_uid != $userId) {
                            $responce['status'] = 0;
                            $responce['message'] = 'Invalid credentials.';
                            return response()->json($responce);
                        }
                    } else {
                        $responce['status'] = 0;
                        $responce['message'] = 'Invalid credentials.';
                        return response()->json($responce);
                    }
                }
                elseif ($request->login_type == 'facebook') {
                    $userId = isset($socical_data['id']) ? $socical_data['id'] : '';
                    $userName = isset($socical_data['name']) ? $socical_data['name'] : '';
                    $userEmail = isset($socical_data['email']) ? $socical_data['email'] : '';
                    $idToken = isset($socical_data['idToken']) ? $socical_data['idToken'] : '';

                    if (!empty($idToken) && !empty($userEmail)) {
                        $curl = curl_init();
                        curl_setopt_array($curl, array(
                            CURLOPT_URL => 'https://graph.facebook.com/oauth/access_token?client_id=432184601772497&client_secret=fefba81bb2f7b0095ce9962186c35252&grant_type=client_credentials',
                            CURLOPT_RETURNTRANSFER => true,
                            CURLOPT_ENCODING => '',
                            CURLOPT_MAXREDIRS => 10,
                            CURLOPT_TIMEOUT => 0,
                            CURLOPT_FOLLOWLOCATION => true,
                            CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
                            CURLOPT_CUSTOMREQUEST => 'GET',
                        ));
                        $curl_response = curl_exec($curl);
                        curl_close($curl);
                        $fb_response = json_decode($curl_response, 1);
                        $access_token = isset($fb_response['access_token']) ? $fb_response['access_token'] : '';
                        if (!empty($idToken)) {
                            $curl2 = curl_init();
                            curl_setopt_array($curl2, array(
                                CURLOPT_URL => 'https://graph.facebook.com/debug_token?input_token='. $idToken .'&access_token='. $access_token,
                                CURLOPT_RETURNTRANSFER => true,
                                CURLOPT_ENCODING => '',
                                CURLOPT_MAXREDIRS => 10,
                                CURLOPT_TIMEOUT => 0,
                                CURLOPT_FOLLOWLOCATION => true,
                                CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
                                CURLOPT_CUSTOMREQUEST => 'GET',
                            ));
                            $curl2_response = curl_exec($curl2);
                            curl_close($curl2);
                            $fb_user_response = json_decode($curl2_response, 1);
                            $fb_user_id = isset($fb_user_response['data']['user_id']) ? $fb_user_response['data']['user_id'] : '';
                            if ($fb_user_id != $userId) {
                                $responce['status'] = 0;
                                $responce['message'] = 'Invalid credentials.';
                                return response()->json($responce);
                            }
                        } else {
                            $responce['status'] = 0;
                            $responce['message'] = 'Invalid credentials.';
                            return response()->json($responce);
                        }
                    } else {
                        $responce['status'] = 0;
                        $responce['message'] = 'Invalid credentials.';
                        return response()->json($responce);
                    }
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'unable to sign in, please try again.';
                }
                $UserDetails = User::where(['email' => $userEmail])->first();
                if (!empty($UserDetails)) {
                    if ($request->request_from == 'mobile') {
                        $UserDetails->device_id = $request->device_id;
                        $UserDetails->device_token = $request->device_token;
                        $UserDetails->device_type = $request->device_type;
                    }
                    $UserDetails->login_type = $request->login_type;
                    $UserDetails->social_login_id = $userId;
                    $UserDetails->updated_at = date("Y-m-d H:i:s");
                    $UserDetails->email_verified_at = date("Y-m-d H:i:s");
                    $UserDetails->save();

                    $accessToken = $this->generateAccessToken($UserDetails->id);
                    $responce['is_existing_user'] = 1;
                    $responce['access_token'] = $responce['token'] = $accessToken->accessToken;
                    $responce['token_expire'] = Carbon::parse($accessToken->token->expires_at)->toDateTimeString();
                    $responce['status'] = 1;
                    $responce['message'] = "Welcome ". $UserDetails->first_name;
                } else {
                    $user = new User([
                        'first_name' => $userName,
                        'last_name' => '',
                        'email' => $userEmail,
                        'password' => bcrypt(rand(10000000,99999999)),
                        'vendor_id' => 0,
                        'status' => 1,
                        'role' => 4,
                        'access_type' => 'customer',
                        'device_id' => $request->device_id,
                        'device_token' => $request->device_token,
                        'device_type' => $request->device_type,
                        'login_type' => $request->login_type,
                        'social_login_id' => $userId,
                        'email_verified_at' => date("Y-m-d H:i:s")
                    ]);
                    if ($user->save()) {
                        $newUser = $user->id;
                        $accessToken = $this->generateAccessToken($newUser);

                        $SmsTemplate = SmsTemplate::where('ref_code', 'RegistrationSuccess')->first();
                        $msg = str_replace(array("~var1~", "~var2~", "~var3~", "~var4~"), array($request->first_name .",\n", "\n", "\nOTDC", "\n\n"), $SmsTemplate->source);
                        parent::sendSms($request->phone, $msg, $SmsTemplate->templete_id);

                        $responce['access_token'] = $responce['token'] = $accessToken->accessToken;
                        $responce['token_expire'] = Carbon::parse($accessToken->token->expires_at)->toDateTimeString();
                        $responce['status'] = 1;
                        $responce['message'] = "Welcome ". $userName;
                    } else {
                        $responce['status'] = 0;
                        $responce['message'] = 'unable to sign up, please try again.';
                    }
                }
            }
        }
        elseif ($request->request_type == 'forgot_password') {
            $validate = Validator::make($request->all(), [
                'email' => 'required|email',
            ]);
            if ($validate->fails()) {
                $errors = $validate->errors();
                if ($errors->has('email')) {
                    $responce['message'] = 'Please enter a valid email.';
                }
                $responce['status'] = 0;
            }
            else {
                $UserDetails = User::where('email', $request->email)->first();
                if(!empty($UserDetails)) {
                    $token = Str::random(155);
                    $verify_link = $this->site .'change-password/' . $token . '/' . $request->email;

                    // Send forgot password mail to user
                    $ForgotPasswordTemplete = EmailTemplate::where('ref_code', 'ForgotPassword')->first();
                    if (!empty($ForgotPasswordTemplete)) {
                        $Message = str_replace(array("~firstname~", "~lastname~", "~website_url~", "~verify_link~", "~site_url~"), array($UserDetails->first_name, $UserDetails->last_name, $this->frontendUrl, $verify_link, $this->site), $ForgotPasswordTemplete->source);
                        $Subject = $ForgotPasswordTemplete->subject;
                        Mail::to($request->email)->send(new \App\Mail\ForgotPasswordMail($Message, $Subject));

                        $current_date = date('Y-m-d H:i:s');
                        $link_expire = date('Y-m-d H:i:s', strtotime('+2 hour', strtotime($current_date)));
                        DB::insert("INSERT INTO `password_resets`(`email`, `token`, `expire_time`, `created_at`) VALUES ('".$request->email."', '".$token."', '".$link_expire."', '".$current_date."')");

                        // Save email logs
                        DB::insert("INSERT INTO `email_logs`(`user_id`, `email`, `subject`, `email_content`, `created_at`) VALUES ('".$UserDetails->id."', '".$request->email."', '".$Subject."', '".$Message."', '".$current_date."')");
                    }
                    $responce['status'] = 1;
                    $responce['message'] = 'A password reset mail is send to your mail id, Please go through this mail for change password';
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'A password reset mail is send to your mail id, Please go through this mail for change password';
                }
            }
        }
        return response()->json($responce);
    }

    public function getNotifications(Request $request) {
        $user = $request->user();
        if (!empty($user)) {
            $Notfications = Notification::select('id', 'message', 'date_time')->where('user_id', $user->id)->orderBy('id', 'DESC')->get();
            if (!empty($Notfications)) {
                foreach ($Notfications as $key => $value) {
                    $Notfications[$key]->date = date("d M Y", strtotime($value->date_time));
                    $Notfications[$key]->time = date("h:i a", strtotime($value->date_time));
                }
                $responce['status'] = 1;
                $responce['data'] = $Notfications;
            } else {
                $responce['status'] = 1;
                $responce['data'] = [];
            }
        } else {
            $responce['status'] = 0;
            $responce['message'] = 'Invalid user data';
        }
        return response()->json($responce);
    }

    public function vendorLogin(Request $request) {
        $validate = Validator::make($request->all(), [
            'email' => 'required|string|email',
            'password' => 'required|string',
        ]);
        if ($validate->fails()) {
            $errors = $validate->errors();
            if ($errors->has('email')) {
                $responce['message'] = $errors->first('email');
            } elseif ($errors->has('password')) {
                $responce['message'] = $errors->first('password');
            }
            $responce['status'] = 0;
        } else {
            $credentials = request(['email', 'password']);
            if (Auth::attempt($credentials)) {
                $user = $request->user();
                if ($user->access_type == 'vendor') {
                    if ($user->status == 1) {
                        $user->wrong_attempts = 0;
                        $user->save();
                        $tokenResult = $user->createToken('Personal Access Token');
                        $token = $tokenResult->token;
                        $token->save();

                        $vendor_services = json_decode($user->services, 1);
                        $services[] = array('name' => 'Verify QR code', 'image' => $this->site . 'images/frontend/Verify-QR-Code.jpg');
                        if (in_array('hotel', $vendor_services)) {
                            $services[] = array('name' => 'Manage Hotel Inventory', 'image' => $this->site . 'images/frontend/Manage-Hotel-Inventory.jpg', 'type' => 'menu', 'service_type' => 'hotel');
                            $services[] = array('name' => 'Block Hotel Inventory', 'image' => $this->site . 'images/frontend/block-Hotel-Inventory.png', 'type' => 'menu', 'service_type' => 'hotel');
                            $services[] = array('name' => 'Hotel Orders', 'image' => $this->site . 'images/frontend/Manage-Orders.jpg', 'type' => 'order', 'service_type' => 'hotel');
                        }
