                            $services[] = array('name' => 'Block Rental Inventory', 'image' => $this->site . 'images/frontend/block-Rental-Inventory.png', 'type' => 'menu', 'service_type' => 'rental');
                            $services[] = array('name' => 'Rental Orders', 'image' => $this->site . 'images/frontend/Manage-Orders.jpg', 'type' => 'order', 'service_type' => 'car');
                        }
                        if (in_array('tour', $vendor_services)) {
                            $services[] = array('name' => 'Tour Orders', 'image' => $this->site . 'images/frontend/Manage-Orders.jpg', 'type' => 'order', 'service_type' => 'tour');
                        }
                        if (in_array('ticketing', $vendor_services)) {
                            $services[] = array('name' => 'Book Instant Ticket', 'image' => $this->site . 'images/frontend/Book-Instant-Ticket.jpg', 'type' => 'menu', 'service_type' => 'ticketing');
                            $services[] = array('name' => 'Ticketing Orders', 'image' => $this->site . 'images/frontend/Manage-Orders.jpg', 'type' => 'order', 'service_type' => 'ticketing');
                        }
                        if ($user->role == 3) {
                            $servs = array_column($services, 'name');
                            $privileges = json_decode($user->privilege, 1);
                            if (!isset($privileges['68']) || $privileges['68'] == 0) {
                                if (in_array('Manage Hotel Inventory', $servs)) {
                                    unset($services[array_search('Manage Hotel Inventory', $servs)]);
                                }
                            }
                            if (!isset($privileges['69']) || $privileges['69'] == 0) {
                                if (in_array('Manage Rental Inventory', $servs)) {
                                    unset($services[array_search('Manage Rental Inventory', $servs)]);
                                }
                            }
                            if (!isset($privileges['12']) || $privileges['12'] == 0) {
                                if (in_array('Block Hotel Inventory', $servs)) {
                                    unset($services[array_search('Block Hotel Inventory', $servs)]);
                                }
                            }
                            if (!isset($privileges['57']) || $privileges['57'] == 0) {
                                if (in_array('Block Rental Inventory', $servs)) {
                                    unset($services[array_search('Block Rental Inventory', $servs)]);
                                }
                            }
                            if (!isset($privileges['76']) || $privileges['76'] == 0) {
                                if (in_array('Verify QR code', $servs)) {
                                    unset($services[array_search('Verify QR code', $servs)]);
                                }
                            }
                            if (!isset($privileges['77']) || $privileges['77'] == 0) {
                                if (in_array('Book Instant Ticket', $servs)) {
                                    unset($services[array_search('Book Instant Ticket', $servs)]);
                                }
                            }
                            // if ((!isset($privileges['28']) || $privileges['28'] == 0) && (!isset($privileges['30']) || $privileges['30'] == 0) && (!isset($privileges['31']) || $privileges['31'] == 0) && (!isset($privileges['32']) || $privileges['32'] == 0)) {
                            //     if (in_array('Manage Orders', $servs)) {
                            //         unset($services[array_search('Manage Orders', $servs)]);
                            //     }
                            // }
                            if ((!isset($privileges['28']) || $privileges['28'] == 0)) {
                                if (in_array('Hotel Orders', $servs)) {
                                    unset($services[array_search('Hotel Orders', $servs)]);
                                }
                            }
                            if ((!isset($privileges['30']) || $privileges['30'] == 0)) {
                                if (in_array('Rental Orders', $servs)) {
                                    unset($services[array_search('Rental Orders', $servs)]);
                                }
                            }
                            if ((!isset($privileges['31']) || $privileges['31'] == 0)) {
                                if (in_array('Tour Orders', $servs)) {
                                    unset($services[array_search('Tour Orders', $servs)]);
                                }
                            }
                            if ((!isset($privileges['32']) || $privileges['32'] == 0)) {
                                if (in_array('Ticketing Orders', $servs)) {
                                    unset($services[array_search('Ticketing Orders', $servs)]);
                                }
                            }
                        }

                        $responce['status'] = 1;
                        $responce['message'] = "Welcome " . $user->first_name;
                        $responce['token'] = $tokenResult->accessToken;
                        $responce['services'] = array_merge($services);
                    } else {
                        $responce['status'] = 0;
                        $responce['message'] = "Your account is deactivated. Please contact admin to activate your account.";
                    }
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = "Un-autherised access.";
                }
            } else {
                $Userdata = User::where('email', $request->email)->first();
                if (!empty($Userdata)) {
                    if ($Userdata->status == 1) {
                        $Userdata->wrong_attempts += 1;
                        if ($Userdata->wrong_attempts >= 3) {
                            $Userdata->status = 0;
                        }
                        $Userdata->save();
                        $responce['status'] = 0;
                        $responce['message'] = "These credentials do not match our records.";
                    }  else {
                        $responce['status'] = 0;
                        $responce['message'] = "Your account is deactivated. Please contact admin to activate your account.";
                    }
                }  else {
                    $TmpUser = TmpUser::where('email', $request->email)->first();
                    if (!empty($TmpUser)) {
                        if ($TmpUser->attempt >= 3) {
                            $responce['status'] = 0;
                            $responce['message'] = "Your account is deactivated. Please contact admin to activate your account.";
                        } else {
                            $TmpUser->attempt += 1;
                            $TmpUser->save();
                            $responce['status'] = 0;
                            $responce['message'] = "These credentials do not match our records.";
                        }
                    } else {
                        DB::table('temp_users')->insert([
                            'email' => $request->email,
                            'attempt' => 1,
                            'created_at' => date("Y-m-d H:i:s")
                        ]);
                        $responce['status'] = 0;
                        $responce['message'] = "These credentials do not match our records.";
                    }
                }
            }
        }
        return response()->json($responce);
    }

