    public function veriyQrcode(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'verify_qrcode') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $vendorId = ($user->role == 2) ? $user->id : $user->vendor_id;
                $qrData = json_decode(base64_decode($request->qrData), 1);
                $invoiceId = isset($qrData['invoiceId']) ? $qrData['invoiceId'] : '';
                $orderId = isset($qrData['orderId']) ? $qrData['orderId'] : '';
                $txnId = isset($qrData['txnId']) ? $qrData['txnId'] : '';
                $serviceType = isset($qrData['serviceType']) ? $qrData['serviceType'] : '';
                $gate_no = isset($request->gate_number) ? $request->gate_number : '';
                $OrderMaster = OrderMaster::where(['invoice_id' => $invoiceId, 'order_id' => $orderId, 'transaction_id' => $txnId, 'service_type' => $serviceType, 'status' => 'completed', 'vendor_id' => $vendorId, 'gate_number' => $gate_no])->first();
                if (!empty($OrderMaster)) {

                    $OrderData = array();
                    $UserData = array();
                    if ($OrderMaster->service_type == 'hotel') {
                        $Coupon_percent = $sgst = $cgst = 0;
                        if ($OrderMaster->tax_amount > 0) {
                            $GstData = GstDetail::pluck('value', 'name');
                            $cgst = $GstData['CGST'];
                            $sgst = $GstData['SGST'];
                        }
                        if ($OrderMaster->coupon_amount > 0) {
                            $Coupon = Coupon::where('coupon_code', $OrderMaster->coupon_code)->first();
                            $Coupon_percent = $Coupon->coupon_amount;
                        }
                        $OrderDeatil = OrderDetail::select('service_item_name', DB::raw('sum(unit_total_price) as grossPrice'), DB::raw('sum(total_room_price) as totalRoomPrice'), DB::raw('sum(tax_amount) as totTax'))
                                ->where('order_master_id', $OrderMaster->id)
                                ->groupBy('service_item_id')
                                ->get();
                        $room_details = array();
                        foreach ($OrderDeatil as $value) {
                            $discount = $value->grossPrice * ($Coupon_percent / 100);
                            $afterDiscount = $value->grossPrice - $discount;
                            $cgstPrice = $sgstPrice = 0;
                            if ($cgst > 0 || $sgst > 0) {
                                $cgstPrice = ($value->totTax / ($cgst + $sgst)) * $cgst;
                                $sgstPrice = ($value->totTax / ($cgst + $sgst)) * $sgst;
                            }
                            $totalRoomPrice = $afterDiscount + $cgstPrice + $sgstPrice;

                            $room_details[] = array(
                                'room_name' => $value->service_item_name,
                                'gross_price' => number_format($value->grossPrice, 2),
                                'discount' => number_format($discount, 2),
                                'after_discount' => number_format($afterDiscount, 2),
                                'cgst' => number_format($cgstPrice, 2),
                                'sgst' => number_format($sgstPrice, 2),
                                'total_room_price' => number_format($totalRoomPrice, 2)
                            );
                        }
                        $OrderData['room_details'] = $room_details;
                        $room_html = '';
                        $room_details = json_decode($OrderMaster->room_details, 1);
                        foreach ($room_details as $value) {
                            $room_html .= $value['quantity'] .' '. $value['room_name'] .', ';
                        }
                        $room_html = trim($room_html, ', ');
                        $OrderData['room_types'] = '['. $room_html .']';
                        $OrderData['check_date'] = '['. date("d M Y", strtotime($OrderMaster->start_date)) .' - '. date("d M Y", strtotime($OrderMaster->end_date)) .']';
                        $OrderData['service_charge'] = $OrderMaster->service_charge;
                        $OrderData['total_adult'] = $OrderMaster->total_adults;
                        $OrderData['total_child'] = $OrderMaster->total_child;
                        $OrderData['need_pickup'] = $OrderMaster->need_pickup;
                        $OrderData['expected_arrival_time'] = $OrderMaster->expected_arrival_time;
                    }
                    elseif ($OrderMaster->service_type == 'car') {
                        $OrderData['quantity'] = $OrderMaster->service_quantity;
                        $OrderData['check_date'] = '['. date("d M Y", strtotime($OrderMaster->start_date)) .' - '. date("d M Y", strtotime($OrderMaster->end_date)) .']';
                        $OrderData['drop_location'] = $OrderMaster->drop_location;
                        $OrderData['pickup_address'] = $OrderMaster->pickup_address;
                        $OrderData['route_map'] = json_decode($OrderMaster->route, 1);


                        $OrderDetail = OrderDetail::where('order_master_id', $OrderMaster->id)->get();
                        $room_details = array();
                        foreach ($OrderDetail as $value) {
                            $room_details[] = array(
                                'pickup' => $value->pickup_address .', '. $value->pickup_city,
                                'drop' => $value->drop_address .', '. $value->drop_city,
                                'check_date' => date("d M Y h:i a", strtotime($value->start_date .' '. $value->start_time)) .' - <br>'. date("d M Y h:i a", strtotime($value->end_date .' '. $value->end_time)),
                                'distance' => $value->distance,
                                'sub_total' => number_format($value->unit_total_price - $value->coupon_amount, 2),
                                'cgst' => number_format($value->tax_amount / 2, 2),
                                'sgst' => number_format($value->tax_amount / 2, 2),
                                'total_price' => number_format($value->total_room_price, 2)
                            );
                        }
                        $OrderData['room_details'] = $room_details;
                        $OrderData['guide_charge'] = $OrderMaster->guide_charge;
                        $OrderData['days_for_guide'] = $OrderMaster->days_for_guide;
                    }
                    elseif ($OrderMaster->service_type == 'tour') {

                        $OrderData['category'] = $OrderMaster->service_category;
                        if ($OrderMaster->service_category == 'sight seeing') {
                            $OrderData['total_tickets'] = $OrderMaster->total_guests;
                            $OrderData['check_date'] = '['. date("M d Y", strtotime($OrderMaster->start_date)) .']';
                        } else {
                            $OrderData['adult'] = $OrderMaster->total_adults;
                            $OrderData['child'] = $OrderMaster->total_child;
                            $OrderData['check_date'] = '['. date("M d Y", strtotime($OrderMaster->start_date)) .' - '. date("M d Y", strtotime($OrderMaster->end_date)) .']';
                            $OrderDetail = OrderDetail::select('service_name', 'start_date', 'end_date', 'service_item_name', DB::raw('SUM(service_item_quantity)as totQty'))
                                    ->where('order_master_id', $OrderMaster->id)
                                    ->groupBy('start_date')
                                    ->get();
                            $room_details = array();
                            foreach ($OrderDetail as $value) {
                                $room_details[] = array(
                                    'hotel_name' => $value->service_name,
                                    'check_date' => date("M d Y", strtotime($value->start_date)) .' - '. date("M d Y", strtotime($value->end_date)),
                                    'room_name' => $value->service_item_name,
                                    'quantity' => $value->totQty
                                );
                            }
                            $OrderData['room_details'] = $room_details;
                        }
                    }
                    elseif ($OrderMaster->service_type == 'ticketing') {

                        $OrderData['category'] = $OrderMaster->service_category;
                        $OrderData['check_date'] = date("M d Y", strtotime($OrderMaster->start_date));
                        $OrderData['adult'] = $OrderMaster->total_adults;
                        $OrderData['child'] = $OrderMaster->total_child;
                        if ($OrderMaster->start_time) {
                            $OrderData['duration'] = '['. $OrderMaster->start_time .' - '. $OrderMaster->end_time .']';
                        } else {
                            $OrderData['duration'] = 'All day';
                        }
                        $extra_services = json_decode($OrderMaster->room_details, 2);
                        $occupied_service = array();
                        foreach ($extra_services as $val) {
                            $occupied_service[] = array(
                                'name' => $val['name'],
                                'quantity' => $val['quantity'],
                                'price' => number_format($val['price'] * $val['quantity'], 2)
                            );
                        }
                        $OrderData['room_details'] = $occupied_service;
                    }
                    $OrderData['status'] = $OrderMaster->status;
                    $OrderData['payment_gateway'] = $OrderMaster->payment_gateway;
                    $OrderData['qr_code'] = !empty($OrderMaster->qr_code) ? $this->site . $OrderMaster->qr_code : '';
                    $OrderData['invoice_id'] = $OrderMaster->invoice_id;
                    $OrderData['order_id'] = $OrderMaster->order_id;
                    $OrderData['booking_date'] = date("d M Y h:i a", strtotime($OrderMaster->created_at));
                    $OrderData['orderId'] = $OrderMaster->id;
                    $OrderData['service_name'] = $OrderMaster->service_name;
                    $OrderData['total_amount'] = $OrderMaster->total_order_price;
                    $OrderData['total_service_price'] = $OrderMaster->total_service_price;
                    $OrderData['sub_total_price'] = $OrderMaster->sub_total_price;
                    $OrderData['gst'] = $OrderMaster->tax_amount;
                    $OrderData['discount_amount'] = $OrderMaster->coupon_amount;
                    $OrderData['coupon_name'] = !empty($OrderMaster->coupon_name) ? $OrderMaster->coupon_name : '';
                    $OrderData['payment_status'] = $OrderMaster->payment_status;
                    $OrderData['txn_id'] = !empty($OrderMaster->transaction_id) ? $OrderMaster->transaction_id : 'N/A';
                    $OrderData['gate_number'] = $OrderMaster->gate_number;
                    $OrderData['total_ticket'] = $OrderMaster->total_guests;

                    $UserData['name'] = $OrderMaster->customer_name;
                    $UserData['customer_email'] = $OrderMaster->customer_email;
                    $UserData['customer_phone'] = $OrderMaster->customer_phone;
                    $UserData['customer_address1'] = $OrderMaster->customer_address1;
                    $UserData['customer_address2'] = $OrderMaster->customer_address2;
                    $UserData['customer_city'] = $OrderMaster->customer_city;
                    $UserData['customer_state'] = $OrderMaster->customer_state;
                    $UserData['customer_country'] = $OrderMaster->customer_country;
                    $UserData['customer_zipcode'] = $OrderMaster->customer_zipcode;
                    $UserData['customer_notes'] = $OrderMaster->customer_notes;

                    $responce['service_type'] = $OrderMaster->service_type;
                    $responce['user_data'] = $UserData;
                    $responce['order_data'] = $OrderData;

                    $curret_date = date("Y-m-d H:i:s");
                    if ($OrderMaster->service_type == 'hotel') {
                        if ($OrderMaster->start_date <= date("Y-m-d", strtotime($curret_date)) && $OrderMaster->end_date > date("Y-m-d", strtotime($curret_date))) {
                            if ($OrderMaster->qr_verified == 0) {
                                $OrderMaster->qr_verified = 1;
                                $OrderMaster->save();

                                $responce['status'] = 1;
                                $responce['success'] = 1;
                                $responce['message'] = 'Verified successfully.';
                            } else {
                                $responce['status'] = 1;
                                $responce['success'] = 1;
                                $responce['message'] = 'Already verified.';
                            }
                        } else {
                            $responce['status'] = 1;
                            $responce['success'] = 0;
                            $responce['message'] = 'Qr code is expired.';
                        }
                    }
                    elseif ($OrderMaster->service_type == 'car') {
                        $checkIn = date("Y-m-d H:i:s", strtotime($OrderMaster->start_date .' '. $OrderMaster->start_time));
                        $checkOut = date("Y-m-d H:i:s", strtotime($OrderMaster->end_date .' '. $OrderMaster->end_time));
                        if ($checkIn <= $curret_date && $checkOut > $curret_date) {
                            if ($OrderMaster->qr_verified == 0) {
                                $OrderMaster->qr_verified = 1;
                                $OrderMaster->save();

                                $responce['status'] = 1;
                                $responce['success'] = 1;
                                $responce['message'] = 'Verified successfully.';
                            } else {
                                $responce['status'] = 1;
                                $responce['success'] = 1;
                                $responce['message'] = 'Already verified.';
                            }
                        } else {
                            $responce['status'] = 1;
                            $responce['success'] = 0;
                            $responce['message'] = 'Qr code is expired.';
                        }
                    }
                    elseif ($OrderMaster->service_type == 'tour' && $OrderMaster->service_category == 'sight seeing') {
                        if ($OrderMaster->start_date == date("Y-m-d", strtotime($curret_date))) {
                            if ($OrderMaster->qr_verified == 0) {
                                $OrderMaster->qr_verified = 1;
                                $OrderMaster->save();

                                $responce['status'] = 1;
                                $responce['success'] = 1;
                                $responce['message'] = 'Verified successfully.';
                            } else {
                                $responce['status'] = 1;
                                $responce['success'] = 1;
                                $responce['message'] = 'Already verified.';
                            }
                        } else {
                            $responce['status'] = 1;
                            $responce['success'] = 0;
                            $responce['message'] = 'Qr code is expired.';
                        }
                    }
                    elseif ($OrderMaster->service_type == 'tour' && $OrderMaster->service_category == 'package') {
                        if ($OrderMaster->start_date <= date("Y-m-d", strtotime($curret_date)) && $OrderMaster->end_date > date("Y-m-d", strtotime($curret_date))) {
                            if ($OrderMaster->qr_verified == 0) {
                                $OrderMaster->qr_verified = 1;
                                $OrderMaster->save();

                                $responce['status'] = 1;
                                $responce['success'] = 1;
                                $responce['message'] = 'Verified successfully.';
                            } else {
                                $responce['status'] = 1;
                                $responce['success'] = 1;
                                $responce['message'] = 'Already verified.';
                            }
                        } else {
                            $responce['status'] = 1;
                            $responce['success'] = 0;
                            $responce['message'] = 'Qr code is expired.';
                        }
                    }
                    elseif ($OrderMaster->service_type == 'ticketing' && empty($OrderMaster->start_time) && empty($OrderMaster->end_time)) {
                        if ($OrderMaster->start_date == date("Y-m-d", strtotime($curret_date))) {
                            if ($OrderMaster->qr_verified == 0) {
                                $OrderMaster->qr_verified = 1;
                                $OrderMaster->save();

                                $responce['status'] = 1;
                                $responce['success'] = 1;
                                $responce['message'] = 'Verified successfully.';
                            } else {
                                $responce['status'] = 1;
                                $responce['success'] = 1;
                                $responce['message'] = 'Already verified.';
                            }
                        } else {
                            $responce['status'] = 1;
                            $responce['success'] = 0;
                            $responce['message'] = 'Qr code is expired.';
                        }
                    }
                    elseif ($OrderMaster->service_type == 'ticketing' && !empty($OrderMaster->start_time) && !empty($OrderMaster->end_time)) {
                        $checkIn = date("Y-m-d H:i:s", strtotime($OrderMaster->start_date .' '. $OrderMaster->start_time));
                        $checkOut = date("Y-m-d H:i:s", strtotime($OrderMaster->start_date .' '. $OrderMaster->end_time));
                        if (date("Y-m-d", strtotime($OrderMaster->start_date)) == date("Y-m-d") && $checkOut > $curret_date) {
                            if ($OrderMaster->qr_verified == 0) {
                                $OrderMaster->qr_verified = 1;
                                $OrderMaster->save();

                                $responce['status'] = 1;
                                $responce['success'] = 1;
                                $responce['message'] = 'Verified successfully.';
                            } else {
                                $responce['status'] = 1;
                                $responce['success'] = 0;
                                $responce['message'] = 'Already verified.';
                            }
                        } else {
                            $responce['status'] = 1;
                            $responce['success'] = 0;
                            $responce['message'] = 'Qr code is expired.';
                        }
                    }
                } else {
                    $responce['status'] = 1;
                    $responce['success'] = 0;
                    $responce['message'] = 'Invalid Qr code';
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = 'Invalid user details.';
            }
        }
        return response()->json($responce);
    }

    public function hotelInventory(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'hotel_list') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $MasterHotelQuery = MasterHotel::where('status', 'publish');
                $vender_id = ($user->role == 2) ? $user->id : $user->vendor_id;
                $MasterHotelQuery->where('vender_id', $vender_id);
                if ($user->role == 3) {
                    $SubuserAccess = SubuserAccess::where(['user_id' => $user->id, 'service' => 'hotel'])->pluck('service_id', 'id')->toArray();
                    if (!empty($SubuserAccess)) {
                        $MasterHotelQuery->whereIn('id', array_values($SubuserAccess));
                    }
                }
                $MasterHotel = $MasterHotelQuery->pluck('name', 'id');
                $HotelList = array();
                if (!empty($MasterHotel)) {
                    foreach ($MasterHotel as $key => $val) {
                        $HotelList[] = array(
                            'id' => $key,
                            'name' => $val
                        );
                    }
                }
                $responce['status'] = 1;
                $responce['data'] = $HotelList;
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        elseif ($request->request_type == 'room_list') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $vender_id = ($user->role == 2) ? $user->id : $user->vendor_id;
                $MasterHotel = MasterHotel::where(['status' => 'publish', 'vender_id' => $vender_id, 'id' => $request->hotelId])->first();
                $RoomList = array();
                if (!empty($MasterHotel)) {
                    $HotelRoom = HotelRoom::where(['status' => 'publish', 'hotel_id' => $MasterHotel->id])->pluck('title', 'id');
                    foreach ($HotelRoom as $key => $val) {
                        $RoomList[] = array(
                            'id' => $key,
                            'name' => $val
                        );
                    }
                    $responce['status'] = 1;
                    $responce['data'] = $RoomList;
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = "Invalid hotel.";
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        elseif ($request->request_type == 'get_inventory') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $vender_id = ($user->role == 2) ? $user->id : $user->vendor_id;

                $MasterInventoryQry = MasterInventory::select('date', 'room_id', 'initial_quantity', 'total_available', 'total_blocked', 'id')
                        ->where(['vendor_id' => $vender_id, 'hotel_id' => $request->hotelId])
                        ->whereBetween('date', [date("Y-m-d", strtotime($request->startDate)), date("Y-m-d", strtotime($request->endDate))]);
                if (!empty($request->roomId)) {
                    $MasterInventoryQry->where('room_id', $request->roomId);
                }
                // $take = 20;
                // $skip = ($request->pageno == 0) ? $request->pageno : $request->pageno * $take;

                $MasterInventory = $MasterInventoryQry->get();  //->skip($skip)->take($take)
                if (!empty($MasterInventory)) {
                    $HotelRooms = HotelRoom::where('hotel_id', $request->hotelId)->pluck('title', 'id')->toArray();
                    foreach ($MasterInventory as $val) {
                        $val->date = date("d M Y", strtotime($val->date));
                        $val->room_name = $HotelRooms[$val->room_id];
                    }
                }
                $responce['status'] = 1;
                $responce['data'] = $MasterInventory;
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        elseif ($request->request_type == 'change_inventory') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $vender_id = ($user->role == 2) ? $user->id : $user->vendor_id;

                $MasterInventory = MasterInventory::where(['vendor_id' => $vender_id, 'id' => $request->inventoryId])->first();
                if (!empty($MasterInventory)) {
                    $changeType = $request->changeType;
                    $changeQty = $request->changeQty;
                    $initial_qty = $total_available = $error = 0;
                    if ($changeType == 'decrease') {
                        if ($changeQty > $MasterInventory->total_available) {
                            $responce['status'] = 0;
                            $responce['message'] = 'You can decrease maximum '. $MasterInventory->total_available .' number of rooms.';
                            $error = 1;
                        } else {
                            $initial_qty = $MasterInventory->initial_quantity - $changeQty;
                            $total_available = $MasterInventory->total_available - $changeQty;
                        }
                    } else {
                        $initial_qty = $MasterInventory->initial_quantity + $changeQty;
                        $total_available = $MasterInventory->total_available + $changeQty;
                    }
                    if ($error == 0) {
                        $MasterInventory->initial_quantity = $initial_qty;
                        $MasterInventory->total_available = $total_available;
                        $MasterInventory->save();

                        $MasterHotel = MasterHotel::find($MasterInventory->hotel_id);
                        $HotelRoom = HotelRoom::find($MasterInventory->room_id);
                        $FullBlockData = BlockedHotel::where(['hotel_id' => $MasterHotel->id, 'block_date' => $MasterInventory->date])
                                        ->whereRaw("find_in_set('". $HotelRoom->id ."',rooms)")
                                        ->first();
                        if (!empty($MasterHotel->mmt_hotel_id) && !empty($HotelRoom->mmt_room_id)) {
                            $BlockedMmt = BlockedMmtInventory::where('hotel_id', $MasterHotel->id)
                                        ->where('block_date', $MasterInventory->date)
                                        ->where('rooms', $MasterInventory->room_id)
                                        ->whereRaw("(platform LIKE 'all' OR platform LIKE 'mmt')")
                                        ->get()->toArray();
                            $closed = 'false';
                            if (!empty($FullBlockData) || !empty($BlockedMmt)) {
                                $closed = "true";
                            }
                            $Xml = '<?xml version="1.0" encoding="UTF-8" ?>
                                        <AvailRateUpdateRQ hotelCode="'. $MasterHotel->mmt_hotel_id .'" timeStamp="'. time() .'">
                                            <AvailRateUpdate locatorID="1">
                                                <DateRange from="'. $MasterInventory->date . '" to="' . $MasterInventory->date .'"/>
                                                <Availability code="'. $HotelRoom->mmt_room_id .'" count="'. $MasterInventory->total_available .'" closed="'. $closed .'" />
                                            </AvailRateUpdate>
                                        </AvailRateUpdateRQ>';
                            DB::insert("INSERT INTO `mmt_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('manage_inventory', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->mmt_hotel_id ."', '". $HotelRoom->id ."', '". $HotelRoom->mmt_room_id . "', '". $Xml ."', '0', '" . date('Y-m-d H:i:s') . "', 'inventory', '". $MasterInventory->total_available ."', '". $MasterInventory->date ."')");
                        }
                        if (!empty($MasterHotel->ctp_hotel_id) && !empty($HotelRoom->ctp_room_id)) {
                            $BlockedMmt = BlockedMmtInventory::where('hotel_id', $MasterHotel->id)
                                            ->where('block_date', $MasterInventory->date)
                                            ->where('rooms', $MasterInventory->room_id)
                                            ->whereRaw("(platform LIKE 'all' OR platform LIKE 'cleartrip')")
                                            ->get()->toArray();
                            $closed = "Open";
                            if (!empty($FullBlockData) || !empty($BlockedMmt)) {
                                $closed = "Close";
                            }
                            $InvRateplanData = CtpRatePlans::where(['room_type_code' => $HotelRoom->ctp_room_id])->first();
                            if (!empty($InvRateplanData)) {
                                // Availability
                                $Xml = '<OTA_HotelAvailNotifRQ xmlns="http://www.opentravel.org/OTA/2003/05" Version="1.0" EchoToken="1234">
                                            <AvailStatusMessages HotelCode="'. $MasterHotel->ctp_hotel_id .'">
                                                <AvailStatusMessage BookingLimit="'. $MasterInventory->total_available .'">
                                                    <StatusApplicationControl Start="'. $MasterInventory->date .'" End="'. $MasterInventory->date .'" InvTypeCode="'. $HotelRoom->ctp_room_id .'" RatePlanCode="'. $InvRateplanData->rate_plan_code .'" />
                                                    <RestrictionStatus Status="'. $closed .'" />
                                                </AvailStatusMessage>
                                            </AvailStatusMessages>
                                        </OTA_HotelAvailNotifRQ>';
                                DB::insert("INSERT INTO `ctp_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('manage_inventory', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->ctp_hotel_id ."', '". $HotelRoom->id ."', '". $HotelRoom->ctp_room_id . "', '". $Xml ."', '0', '" . date('Y-m-d H:i:s') . "', 'inventory', '". $MasterInventory->total_available ."', '". $MasterInventory->date ."')");
                            }
                        }

                        $responce['status'] = 1;
                        $responce['message'] = 'Inventory updated successfully.';
                        // parent::updateMmtInventory($MasterInventory->vendor_id, $MasterInventory->hotel_id);
                    }
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = "Unable to update inventory.";
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        elseif ($request->request_type == 'release_block_inventory') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $vender_id = ($user->role == 2) ? $user->id : $user->vendor_id;
                $MasterInventory = MasterInventory::where(['vendor_id' => $vender_id, 'id' => $request->inventoryId])->first();
                if (!empty($MasterInventory)) {
                    $changeQty = $request->releaseQty;
