                                $BlockedMmt = BlockedMmtInventory::where('hotel_id', $MasterHotel->id)
                                                ->where('block_date', $inventory->date)
                                                ->where('rooms', $inventory->room_id)
                                                ->whereRaw("(platform LIKE 'all' OR platform LIKE 'cleartrip')")
                                                ->get()->toArray();
                                $closed = "Open";
                                if (!empty($FullBlockData) || !empty($BlockedMmt)) {
                                    $closed = "Close";
                                }
                                $InvRateplanData = CtpRatePlans::where(['room_type_code' => $HotelRoom->ctp_room_id])->first();
                                if (!empty($InvRateplanData)) {
                                    // Availability
                                    $Xml = '<OTA_HotelAvailNotifRQ xmlns="http://www.opentravel.org/OTA/2003/05" Version="1.0" EchoToken="1234">
                                                <AvailStatusMessages HotelCode="'. $MasterHotel->ctp_hotel_id .'">
                                                    <AvailStatusMessage BookingLimit="'. $inventory->total_available .'">
                                                        <StatusApplicationControl Start="'. $inventory->date .'" End="'. $inventory->date .'" InvTypeCode="'. $HotelRoom->ctp_room_id .'" RatePlanCode="'. $InvRateplanData->rate_plan_code .'" />
                                                        <RestrictionStatus Status="'. $closed .'" />
                                                    </AvailStatusMessage>
                                                </AvailStatusMessages>
                                            </OTA_HotelAvailNotifRQ>';
                                    DB::insert("INSERT INTO `ctp_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('delete_full_block_app', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->ctp_hotel_id ."', '". $HotelRoom->id ."', '". $HotelRoom->ctp_room_id . "', '". $Xml ."', '0', '" . date('Y-m-d H:i:s') . "', 'inventory', '". $inventory->total_available ."', '". $inventory->date ."')");
                                }
                            }
                        }
                    }

                    $BlockedData->delete();
                    $responce['status'] = 1;
                    $responce['message'] = 'Block data deleted successfully.';
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Invalid block id.';
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        elseif ($request->request_type == 'get_room_initial') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $rooms = json_decode($request->rooms, 1);
                $HotelRoom = HotelRoom::select('id', 'title', 'quantity')->whereIn('id', $rooms)->where('status', 'publish')->get()->toArray();
                if (!empty($HotelRoom)) {
                    $responce['status'] = 1;
                    $responce['data'] = $HotelRoom;
                } else {
                    $responce['status'] = 1;
                    $responce['data'] = [];
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        return response()->json($responce);
    }

    public function rentalInventory(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'vehicle_list') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $vendor_id = ($user->role == 2) ? $user->id : $user->vendor_id;
                $MasterCar = MasterCar::where('status', 'publish')->where('vendor_id', $vendor_id)->pluck('title', 'id');
                $VehicleList = array();
                if (!empty($MasterCar)) {
                    foreach ($MasterCar as $key => $val) {
                        $VehicleList[] = array(
                            'id' => $key,
                            'name' => $val
                        );
                    }
                }
                $responce['status'] = 1;
                $responce['data'] = $VehicleList;
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        elseif ($request->request_type == 'get_inventory') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $vendor_id = ($user->role == 2) ? $user->id : $user->vendor_id;

                $MasterInventoryQry = RentalMasterInventory::select('date', 'car_id', 'initial_quantity', 'total_available', 'total_blocked', 'id')
                        ->where(['vendor_id' => $vendor_id, 'car_id' => $request->vehicleId])
                        ->whereBetween('date', [date("Y-m-d", strtotime($request->startDate)), date("Y-m-d", strtotime($request->endDate))]);

                // $take = 20;
                // $skip = ($request->pageno == 0) ? $request->pageno : $request->pageno * $take;

                $MasterInventory = $MasterInventoryQry->get(); //->skip($skip)->take($take)
                if (!empty($MasterInventory)) {
                    $MasterCar = MasterCar::where('vendor_id', $vendor_id)->pluck('title', 'id')->toArray();
                    foreach ($MasterInventory as $val) {
                        $val->date = date("d M Y", strtotime($val->date));
                        $val->vehicle_name = $MasterCar[$val->car_id];
                    }
                }
                $responce['status'] = 1;
                $responce['data'] = $MasterInventory;
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        elseif ($request->request_type == 'change_inventory') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $vendor_id = ($user->role == 2) ? $user->id : $user->vendor_id;

                $MasterInventory = RentalMasterInventory::where(['vendor_id' => $vendor_id, 'id' => $request->inventoryId])->first();
                if (!empty($MasterInventory)) {
                    $changeType = $request->changeType;
                    $changeQty = $request->changeQty;
                    $initial_qty = $total_available = $error = 0;
                    if ($changeType == 'decrease') {
                        if ($changeQty > $MasterInventory->total_available) {
                            $responce['status'] = 0;
                            $responce['message'] = 'You can decrease maximum '. $MasterInventory->total_available .' number of quantity.';
                            $error = 1;
                        } else {
                            $initial_qty = $MasterInventory->initial_quantity - $changeQty;
                            $total_available = $MasterInventory->total_available - $changeQty;
                        }
                    } else {
                        $initial_qty = $MasterInventory->initial_quantity + $changeQty;
                        $total_available = $MasterInventory->total_available + $changeQty;
                    }
                    if ($error == 0) {
                        $MasterInventory->initial_quantity = $initial_qty;
                        $MasterInventory->total_available = $total_available;
                        $MasterInventory->save();
                        $responce['status'] = 1;
                        $responce['message'] = 'Inventory updated successfully.';
                    }
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = "Unable to update inventory.";
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        elseif ($request->request_type == 'release_block_inventory') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $vendor_id = ($user->role == 2) ? $user->id : $user->vendor_id;

                $MasterInventory = RentalMasterInventory::where(['vendor_id' => $vendor_id, 'id' => $request->inventoryId])->first();
                if (!empty($MasterInventory)) {
                    $changeQty = $request->releaseQty;
                    $initial_qty = $total_available = 0;
                    if ($changeQty > $MasterInventory->total_blocked) {
                        $responce['status'] = 0;
                        $responce['message'] = 'You can release maximum '. $MasterInventory->total_blocked .' number of vehicles.';
                    } elseif ($changeQty < 1) {
                        $responce['status'] = 0;
                        $responce['message'] = 'You can release minimum 1 vehicle.';
                    } else {
                        $MasterInventory->total_available = $MasterInventory->total_available + $changeQty;
                        $MasterInventory->total_blocked = $MasterInventory->total_blocked - $changeQty;
                        $MasterInventory->save();
                        $responce['status'] = 1;
                        $responce['message'] = 'Inventory updated successfully.';
                    }
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = "Unable to update inventory.";
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        elseif ($request->request_type == 'get_blocked_vehicle_quantity') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $vender_id = ($user->role == 2) ? $user->id : $user->vendor_id;
                $take = 10;
                $skip = ($request->pageIndex == 0) ? $request->pageIndex : $request->pageIndex * $take;
                $BlockDataQuery = RentalAvailability::Select('car_name', 'block_reason', 'quantity', 'block_date')
                        ->where('vendor_id', $vender_id)
                        ->orderBy('id', 'DESC');
                $totalData = $BlockDataQuery->count();
                $BlockData = $BlockDataQuery->skip($skip)->take($take)->get();
                if (!empty($BlockDataQuery)) {
                    foreach ($BlockData as $val) {
                        $val->block_date = date("d M Y", strtotime($val->block_date));
                    }
                }
                $responce['status'] = 1;
                $responce['data'] = $BlockData;
                $responce['totalPage'] = ceil($totalData/$take);
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        elseif ($request->request_type == 'get_available_quantity') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $vender_id = ($user->role == 2) ? $user->id : $user->vendor_id;

                $MasterInventory = RentalMasterInventory::where(['vendor_id' => $vender_id, 'car_id' => $request->vehicleId, 'date' => date("Y-m-d", strtotime($request->checkDate))])->first();
                if (!empty($MasterInventory)) {
                    $responce['status'] = 1;
                    $responce['maxQuantity'] = $MasterInventory->total_available;
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Invalid input data.';
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        elseif ($request->request_type == 'block_vehicle_quantity') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $vender_id = ($user->role == 2) ? $user->id : $user->vendor_id;

                if ($request->block_type == 'single') {
                    $MasterInventory = RentalMasterInventory::where(['vendor_id' => $vender_id, 'car_id' => $request->vehicleId, 'date' => date("Y-m-d", strtotime($request->checkDate))])->first();
                    if (!empty($MasterInventory)) {
                        if ($MasterInventory->total_available >= $request->blockQty) {
                            $MasterCar = MasterCar::find($request->vehicleId);
                            $RentalAvailability = new RentalAvailability([
                                'vendor_id' => $vender_id,
                                'car_id' => $request->vehicleId,
                                'car_name' => $MasterCar->title,
                                'block_date' => date("Y-m-d", strtotime($request->checkDate)),
                                'block_reason' => $request->blockReason,
                                'quantity' => $request->blockQty,
                                'created_by' => $user->id,
                                'status' => 1
                            ]);
                            if ($RentalAvailability->save()) {
                                $MasterInventory->total_available -= $request->blockQty;
                                $MasterInventory->total_blocked += $request->blockQty;
                                $MasterInventory->save();
                                $responce['status'] = 1;
                                $responce['message'] = 'Inventory blocked successfully.';
                            } else {
                                $responce['status'] = 0;
                                $responce['message'] = 'Unable to block. Please try again.';
                            }
                        } else {
                            $responce['status'] = 0;
                            $responce['message'] = 'You can block maximum '. $MasterInventory->total_available .' no. of vehicles.';
                        }
                    } else {
                        $responce['status'] = 0;
                        $responce['message'] = 'Invalid input data.';
                    }
                } elseif ($request->block_type == 'multiple') {
                    $vehicles = json_decode($request->vehicles, 1);
                    $block_st_date = date("Y-m-d", strtotime($request->startDate));
                    $block_end_date = date("Y-m-d", strtotime($request->endDate));
                    $BlockedVehicles = BlockedVehicle::whereIn('vehicle_id', $vehicles)
                            ->whereBetween('block_date', [$block_st_date, $block_end_date])
                            ->get()->toArray();
                    if (empty($BlockedVehicles)) {
                        $Blocked_data = array();
                        $key = 0;
                        foreach ($vehicles as $value) {
                            $MasterCar = MasterCar::find($value);
                            $tmp_date = $block_st_date;

                            while ($tmp_date <= $block_end_date) {
                                $Blocked_data[$key] = [
                                    'vendor_id' => $MasterCar->vendor_id,
                                    'vehicle_id' => $value,
                                    'vehicle_name' => $MasterCar->title,
                                    'block_date' => date("Y-m-d", strtotime($tmp_date)),
                                    'block_reason' => $request->blockReason,
                                    'created_by' => $user->id
                                ];
                                $key++;
                                $tmp_date = date("Y-m-d", strtotime($tmp_date .' + 1 day'));
                            }
                        }
                        $save_status = BlockedVehicle::insert($Blocked_data);
                        if ($save_status) {
                            $responce['status'] = 1;
                            $responce['message'] = 'Vehicle blocked successfully';
                        } else {
                            $responce['status'] = 0;
                            $responce['message'] = 'Unable to block Vehicle. Please try again.';
                        }
                    } else {
                        $responce['status'] = 0;
                        $responce['message'] = "Selected vehicles are already blocked for this date. please change date and try again.";
                    }
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        elseif ($request->request_type == 'get_blocked_vehicles') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $vender_id = ($user->role == 2) ? $user->id : $user->vendor_id;
                $take = 10;
                $skip = ($request->pageIndex == 0) ? $request->pageIndex : $request->pageIndex * $take;
                $BlockDataQuery = BlockedVehicle::Select('vehicle_name', 'block_date', 'block_reason', 'id')
                        ->where('vendor_id', $vender_id)
                        ->orderBy('id', 'DESC');
                $totalData = $BlockDataQuery->count();
                $BlockData = $BlockDataQuery->skip($skip)->take($take)->get();
                if (!empty($BlockData)) {
                    foreach ($BlockData as $val) {
                        $val->block_date = date("d M Y", strtotime($val->block_date));
                    }
                }
                $responce['status'] = 1;
                $responce['data'] = $BlockData;
                $responce['totalPage'] = ceil($totalData/$take);
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        elseif ($request->request_type == 'delete_blocked_vehicles') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $vender_id = ($user->role == 2) ? $user->id : $user->vendor_id;

                $BlockData = BlockedVehicle::where('vendor_id', $vender_id)
                        ->where('id', $request->blockId)
                        ->first();
                if (!empty($BlockData)) {
                    $BlockData->delete();
                    $responce['status'] = 1;
                    $responce['message'] = 'Block data deleted successfully.';
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'Invalid block id.';
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        return response()->json($responce);
    }

    public function vendorOrders(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'order_list') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $service_type = $request->service_type;
                $status = $request->status;
                $vendor_id = ($user->role == 2) ? $user->id : $user->vendor_id;
                $take = 10;

                $skip = ($request->pageIndex == 0) ? $request->pageIndex : $request->pageIndex * $take;
                $OrderMasterQry = OrderMaster::select('service_type', 'vendor_name', 'service_name', 'created_at', 'start_date', 'order_id', 'invoice_id', 'order_type', 'status', 'total_order_price', 'payment_gateway', 'payment_method', 'payment_status', 'transaction_id', 'id', 'end_date', 'service_name_id', 'room_request', 'offline_link_expiry')
                        ->where(['vendor_id' => $vendor_id, 'service_type' => $service_type, 'status' => $status]);

                $cancel_permit = 1;
                if ($user->role == 3) {
                    $SubuserAccess = SubuserAccess::where(['user_id' => $user->id, 'service' => $service_type])->pluck('service_id')->toArray();
                    if (!empty($SubuserAccess)) {
                        // $staff_condition = ' AND service_name_id in (' . implode(',', $SubuserAccess) . ')';
                        $OrderMasterQry->whereIn('service_name_id', $SubuserAccess);
                    }
                    if ($user->user_role == 'agent_staff') {
                        // $staff_condition .= ' AND customer_id = "' . $user->id . '" ';
                        $OrderMasterQry->where('customer_id', $user->id);
                    }
                    $privileges = json_decode($user->privilege, 1);
                    if ($service_type == 'hotel' && (!isset($privileges['28']) || $privileges['28'] != 2)) {
                        $cancel_permit = 0;
                    } elseif ($service_type == 'car' && (!isset($privileges['30']) || $privileges['30'] != 2)) {
                        $cancel_permit = 0;
                    } elseif ($service_type == 'tour' && (!isset($privileges['31']) || $privileges['31'] != 2)) {
                        $cancel_permit = 0;
                    } elseif ($service_type == 'ticketing' && (!isset($privileges['32']) || $privileges['32'] != 2)) {
                        $cancel_permit = 0;
                    }
                }
                $OrderMaster = $OrderMasterQry->orderBy('created_at', 'DESC')->skip($skip)->take($take)->get();

                if (!empty($OrderMaster)) {
                    foreach ($OrderMaster as $key => $value) {
                        $OrderMaster[$key]->cancel = 0;
                        if ($value->service_type == 'hotel') {
                            $MasterHotel = MasterHotel::find($value->service_name_id);
                            $OrderMaster[$key]->slug = (!empty($MasterHotel)) ? $MasterHotel->slug .'-'. $MasterHotel->id : '';
                            $OrderMaster[$key]->icon_name = $this->site . $MasterHotel->feature_image;
                        } elseif ($value->service_type == 'car') {
                            $MasterCar = MasterCar::find($value->service_name_id);
                            $OrderMaster[$key]->slug = (!empty($MasterCar)) ? $MasterCar->slug .'-'. $MasterCar->id : '';
                            $OrderMaster[$key]->icon_name = $this->site . $MasterCar->feature_image;
                        } elseif ($value->service_type == 'tour') {
                            $Tour = Tour::find($value->service_name_id);
                            $OrderMaster[$key]->slug = (!empty($Tour)) ? $Tour->slug .'-'. $Tour->id : '';
                            $OrderMaster[$key]->icon_name = $this->site . $Tour->feature_image;
                        } elseif ($value->service_type == 'ticketing') {
                            $Ticket = Ticket::find($value->service_name_id);
                            $OrderMaster[$key]->slug = (!empty($Ticket)) ? $Ticket->slug .'-'. $Ticket->id : '';
                            $OrderMaster[$key]->icon_name = $this->site . $Ticket->feature_image;
                        } elseif ($value->service_type == 'merchant') {
                            $Vendor_list = User::where('role', 2)->pluck('company', 'id')->toArray();
                            $Items = json_decode($value->room_request, 1);
                            $temp = array();
                            foreach ($Items as $val) {
                                array_push($temp, $Vendor_list[$val['vendor_id']]);
                            }
                            $OrderMaster[$key]->vendor_name = implode(', ', array_unique($temp));
                        }
                        $value->transaction_id = !empty($value->transaction_id) ? $value->transaction_id : 'N/A';
                        $value->start_date = date("d M Y", strtotime($value->start_date));
                        $value->end_date = !empty($value->end_date) ? date("d M Y", strtotime($value->end_date)) : '';
                        $value->service_type = strtoupper($value->service_type);

                        $datetime1 = new DateTime();
                        $datetime2 = new DateTime(date("Y-m-d H:i:s", strtotime($value->created_at)));
                        $interval = $datetime2->diff($datetime1)->format('%h');
                        $intervaldays = $datetime2->diff($datetime1)->format('%days');

                        if ($value->status == 'completed' && $value->payment_status == 'success' && date("Y-m-d", strtotime($value->start_date)) >= date("Y-m-d") && $cancel_permit == 1) {
                            if ($value->service_type != 'RESTAURANT' && $value->service_type != 'MERCHANT') {
                                $OrderMaster[$key]->cancel = 1;
                            }
                        } elseif ($value->status == 'pending' && $value->order_type == 'offline' && $value->payment_gateway == 'hdfc' && ($value->offline_link_expiry < date("Y-m-d H:i:s") || date("Y-m-d", strtotime($value->start_date)) <= date("Y-m-d")) && $cancel_permit == 1) {
                            if ($value->service_type != 'RESTAURANT' && $value->service_type != 'MERCHANT') {
                                $OrderMaster[$key]->cancel = 1;
                            }
                        }
                        // if ($value->status != 'cancelled' && $value->status != 'partially-cancelled' && $value->status != 'pending' && date("Y-m-d", strtotime($value->start_date)) >= date("Y-m-d")) {
                        //     if ($value->service_type != 'RESTAURANT' && $value->service_type != 'MERCHANT') {
                        //         $OrderMaster[$key]->cancel = 1;
                        //     }
                        // }
                        $value->status = strtoupper($value->status);
                    }
                    $responce['status'] = 1;
                    $responce['data'] = $OrderMaster;
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = 'No orders found';
                    $responce['data'] = [];
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        elseif ($request->request_type == 'get_vendor_order_details') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $vendor_id = ($user->role == 2) ? $user->id : $user->vendor_id;
                $OrderMaster = OrderMaster::where(['id' => $request->orderId, 'vendor_id' => $vendor_id])->first();
                if (!empty($OrderMaster)) {
                    $OrderData = array();
                    $UserData = array();
                    if ($OrderMaster->service_type == 'hotel') {
                        $room_html = '';
                        $room_details = json_decode($OrderMaster->room_details, 1);
                        foreach ($room_details as $value) {
                            $room_html .= $value['quantity'] .' '. $value['room_name'] .', ';
                        }
                        $room_html = trim($room_html, ', ');
                        $OrderData['room_types'] = '['. $room_html .']';
                        $OrderData['check_date'] = '['. date("M d Y", strtotime($OrderMaster->start_date)) .' - '. date("M d Y", strtotime($OrderMaster->end_date)) .']';
                        $OrderData['service_charge'] = $OrderMaster->service_charge;
                        $OrderData['need_pickup'] = $OrderMaster->need_pickup;
                        $OrderData['expected_arrival_time'] = !empty($OrderMaster->expected_arrival_time) ? $OrderMaster->expected_arrival_time : 'N/A';
                    }
                    elseif ($OrderMaster->service_type == 'car') {
                        $OrderData['quantity'] = $OrderMaster->service_quantity;
                        $OrderData['check_date'] = '['. date("M d Y", strtotime($OrderMaster->start_date)) .' - '. date("M d Y", strtotime($OrderMaster->end_date)) .']';
                        $OrderData['drop_location'] = $OrderMaster->drop_location;
                        $OrderData['pickup_address'] = $OrderMaster->pickup_address;
                        $OrderData['route_map'] = json_decode($OrderMaster->route, 1);
                    }
                    elseif ($OrderMaster->service_type == 'tour') {
                        $OrderData['category'] = $OrderMaster->service_category;
                        if ($OrderMaster->service_category == 'sight seeing') {
                            $OrderData['total_tickets'] = $OrderMaster->total_guests;
                            $OrderData['check_date'] = '['. date("M d Y", strtotime($OrderMaster->start_date)) .']';
                        } else {
                            $OrderData['adult'] = $OrderMaster->total_adults;
                            $OrderData['child'] = $OrderMaster->total_child;
                            $OrderData['check_date'] = '['. date("M d Y", strtotime($OrderMaster->start_date)) .' - '. date("M d Y", strtotime($OrderMaster->end_date)) .']';
                        }
                    }
                    elseif ($OrderMaster->service_type == 'ticketing') {
