                                                    <AvailRateUpdateRQ hotelCode="'. $MasterHotel->mmt_hotel_id .'" timeStamp="'. time() .'">
                                                        <AvailRateUpdate locatorID="1">
                                                            <DateRange from="'. $MasterInventory->date . '" to="' . $MasterInventory->date .'"/>
                                                            <Availability code="'. $HotelRoom->mmt_room_id .'" count="'. $MasterInventory->total_available .'" closed="'. $closed .'" />
                                                        </AvailRateUpdate>
                                                    </AvailRateUpdateRQ>';
                                        DB::insert("INSERT INTO `mmt_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('cancel_booking', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->mmt_hotel_id ."', '". $HotelRoom->id ."', '". $HotelRoom->mmt_room_id . "', '". $Xml ."', '0', '" . date('Y-m-d H:i:s') . "', 'inventory', '". $MasterInventory->total_available ."', '". $MasterInventory->date ."')");
                                    }
                                    if (!empty($MasterHotel->ctp_hotel_id) && !empty($HotelRoom->ctp_room_id) && $OrderMaster->book_from != 'blocked') {
                                        $BlockedMmt = BlockedMmtInventory::where('hotel_id', $MasterHotel->id)
                                                        ->where('block_date', $MasterInventory->date)
                                                        ->where('rooms', $MasterInventory->room_id)
                                                        ->whereRaw("(platform LIKE 'all' OR platform LIKE 'cleartrip')")
                                                        ->get()->toArray();
                                        $closed = "Open";
                                        if (!empty($FullBlockData) || !empty($BlockedMmt)) {
                                            $closed = "Close";
                                        }
                                        $InvRateplanData = CtpRatePlans::where(['room_type_code' => $HotelRoom->ctp_room_id])->first();
                                        if (!empty($InvRateplanData)) {
                                            // Availability
                                            $Xml = '<OTA_HotelAvailNotifRQ xmlns="http://www.opentravel.org/OTA/2003/05" Version="1.0" EchoToken="1234">
                                                        <AvailStatusMessages HotelCode="'. $MasterHotel->ctp_hotel_id .'">
                                                            <AvailStatusMessage BookingLimit="'. $MasterInventory->total_available .'">
                                                                <StatusApplicationControl Start="'. $MasterInventory->date .'" End="'. $MasterInventory->date .'" InvTypeCode="'. $HotelRoom->ctp_room_id .'" RatePlanCode="'. $InvRateplanData->rate_plan_code .'" />
                                                                <RestrictionStatus Status="'. $closed .'" />
                                                            </AvailStatusMessage>
                                                        </AvailStatusMessages>
                                                    </OTA_HotelAvailNotifRQ>';
                                            DB::insert("INSERT INTO `ctp_availability_logs`(`request_source`, `vendor_id`, `hotel_id`, `hotel_code`, `room_id`, `room_code`, `request_data`, `status`, `created_at`, `request_type`, `quantity`, `date`) VALUES ('cancel_booking', '". $MasterHotel->vender_id ."', '". $MasterHotel->id ."', '". $MasterHotel->ctp_hotel_id ."', '". $HotelRoom->id ."', '". $HotelRoom->ctp_room_id . "', '". $Xml ."', '0', '" . date('Y-m-d H:i:s') . "', 'inventory', '". $MasterInventory->total_available ."', '". $MasterInventory->date ."')");
                                        }
                                    }
                                }

                            }

                            $Tour = Tour::find($OrderMaster->service_name_id);
                            $service_email = $Tour->contact_email;
                            if (!empty($Tour->additional_email)) {
                                $service_email = !empty($service_email) ? $service_email .','. $Tour->additional_email : $Tour->additional_email;
                            }
                            $guest_data = 'Adult: ' . $OrderMaster->total_adults . ', Child: ' . $OrderMaster->total_child;
                            $check_date = date("M d Y", strtotime($OrderMaster->start_date)) . ' - ' . date("M d Y", strtotime($OrderMaster->end_date));
                            $PackageInvoice = EmailTemplate::where('ref_code', 'packageCancelInvoice')->first();
                            $Subject = $PackageInvoice->subject . ' - ' . $OrderMaster->service_name . ' - Booking ID - ' . $OrderMaster->invoice_id;
                            $vendorGSTNo = (!empty($Tour->gst_number)) ? $Tour->gst_number : 'N/A';
                            $Message .= str_replace(array("~otdcLogo~", "~username~", "~usermobile~", "~usermail~", "~useraddress~", "~vendorname~", "~vendorgst~", "~usergst~", "~vendorLogo~", "~invoiceid~", "~canceldate~", "~servicename~", "~checkdate~", "~ordertotal~", "~refundamount~", "~paymentstatus~", "~paymentmethod~", "~txnid~"), array($this->site, $OrderMaster->customer_name, $OrderMaster->customer_phone, $OrderMaster->customer_email, $OrderMaster->customer_address1, $Vendor->company, $vendorGSTNo, $customerGSTNo, $this->site . $Vendor->photo, $OrderMaster->invoice_id, date("M d Y h:i a", strtotime($OrderMaster->cancel_date)), $OrderMaster->service_name, $check_date, number_format($OrderMaster->total_order_price, 2), number_format($refund_amount, 2), 'CANCELLED', $OrderMaster->payment_method, $OrderMaster->transaction_id), $PackageInvoice->source);

                            if (!empty($User) && $User->access_type == 'agent') {
                                $CustomerInvoice = EmailTemplate::where('ref_code', 'packageCancelAgentInvoice')->first();
                                if (!empty($CustomerInvoice)) {
                                    $To = $User->email;
                                    $msg = str_replace(array("~otdcLogo~", "~username~", "~usermobile~", "~usermail~", "~useraddress~", "~vendorLogo~", "~invoiceid~", "~orderdate~", "~servicename~", "~checkdate~", "~ticketquantity~", "~canceldate~"), array($this->site, $OrderMaster->customer_name, $OrderMaster->customer_phone, $OrderMaster->customer_email, $OrderMaster->customer_address1, $this->site . $Vendor->photo, $OrderMaster->invoice_id, date("M d Y h:i a", strtotime($OrderMaster->created_at)), $OrderMaster->service_name, $check_date, $guest_data, date("M d Y h:i a", strtotime($OrderMaster->cancel_date))), $CustomerInvoice->source);
                                    Mail::to($OrderMaster->customer_email)->send(new \App\Mail\RegistrationMailUser($msg, $Subject));
                                }
                            }
                        }
                        elseif ($service_type == 'sight-seeing') {
                            $Tour = Tour::find($OrderMaster->service_name_id);
                            $service_email = $Tour->contact_email;
                            if (!empty($Tour->additional_email)) {
                                $service_email = !empty($service_email) ? $service_email .','. $Tour->additional_email : $Tour->additional_email;
                            }
                            $check_date = date("M d Y", strtotime($OrderMaster->start_date));
                            $SightseenInvoice = EmailTemplate::where('ref_code', 'sightseenCancelInvoice')->first();
                            $Subject = $SightseenInvoice->subject . ' - ' . $OrderMaster->service_name . ' - Booking ID - ' . $OrderMaster->invoice_id;
                            $vendorGSTNo = (!empty($Tour->gst_number)) ? $Tour->gst_number : 'N/A';
                            $Message .= str_replace(array("~otdcLogo~", "~username~", "~usermobile~", "~usermail~", "~useraddress~", "~vendorname~", "~vendorgst~", "~usergst~", "~vendorLogo~", "~invoiceid~", "~canceldate~", "~servicename~", "~checkdate~", "~ordertotal~", "~refundamount~", "~paymentstatus~", "~paymentmethod~", "~txnid~"),
                                    array($this->site, $OrderMaster->customer_name, $OrderMaster->customer_phone, $OrderMaster->customer_email, $OrderMaster->customer_address1, $Vendor->company, $vendorGSTNo, $customerGSTNo, $this->site . $Vendor->photo, $OrderMaster->invoice_id, date("M d Y h:i a", strtotime($OrderMaster->cancel_date)), $OrderMaster->service_name, $check_date, number_format($OrderMaster->total_order_price, 2), number_format($refund_amount, 2), 'CANCELLED', $OrderMaster->payment_method, $OrderMaster->transaction_id), $SightseenInvoice->source);

                            if (!empty($User) && $User->access_type == 'agent') {
                                $CustomerInvoice = EmailTemplate::where('ref_code', 'sightseenCancelAgentInvoice')->first();
                                if (!empty($CustomerInvoice)) {
                                    $To = $User->email;
                                    $msg = str_replace(array("~otdcLogo~", "~username~", "~usermobile~", "~usermail~", "~useraddress~", "~vendorLogo~", "~invoiceid~", "~orderdate~", "~servicename~", "~checkdate~", "~ticketquantity~", "~canceldate~"),
                                                array($this->site, $OrderMaster->customer_name, $OrderMaster->customer_phone, $OrderMaster->customer_email, $OrderMaster->customer_address1, $this->site . $Vendor->photo, $OrderMaster->invoice_id, date("M d Y h:i a", strtotime($OrderMaster->created_at)), $OrderMaster->service_name, $check_date, $OrderMaster->total_guests, date("M d Y h:i a", strtotime($OrderMaster->cancel_date))), $CustomerInvoice->source);
                                    Mail::to($OrderMaster->customer_email)->send(new \App\Mail\RegistrationMailUser($msg, $Subject));
                                }
                            }
                        }
                        elseif ($service_type == 'experience-ticketing' || $service_type == 'events' || $service_type == 'entry-ticket') {
                            $Ticket = Ticket::find($OrderMaster->service_name_id);
                            $service_email = $Ticket->contact_email;
                            if (!empty($Ticket->additional_email)) {
                                $service_email = !empty($service_email) ? $service_email .','. $Ticket->additional_email : $Ticket->additional_email;
                            }
                            $TicketInvoice = EmailTemplate::where('ref_code', 'ticketCancelInvoice')->first();
                            $Subject = $TicketInvoice->subject .' - '. $OrderMaster->service_name .' - Booking ID - '. $OrderMaster->invoice_id;
                            $check_date = date("M d Y", strtotime($OrderMaster->start_date));
                            $guest_data = 'Adult: '. $OrderMaster->total_adults .', Child: '. $OrderMaster->total_child;
                            $duration = (!empty($OrderMaster->start_time)) ? '['. $OrderMaster->start_time .' - '. $OrderMaster->end_time .']' : 'All Day';
                            $vendorGSTNo = (!empty($Ticket->gst_number)) ? $Ticket->gst_number : 'N/A';

                            $Message .= str_replace(array("~otdcLogo~", "~username~", "~usermobile~", "~usermail~", "~useraddress~", "~vendorname~", "~vendorgst~", "~usergst~", "~vendorLogo~", "~invoiceid~", "~canceldate~", "~servicename~", "~checkdate~", "~ordertotal~", "~refundamount~", "~paymentstatus~", "~paymentmethod~", "~txnid~"),
                                    array($this->site, $OrderMaster->customer_name, $OrderMaster->customer_phone, $OrderMaster->customer_email, $OrderMaster->customer_address1, $Vendor->company, $vendorGSTNo, $customerGSTNo, $this->site . $Vendor->photo, $OrderMaster->invoice_id, date("M d Y h:i a", strtotime($OrderMaster->cancel_date)), $OrderMaster->service_name, $check_date, number_format($OrderMaster->total_order_price, 2), number_format($refund_amount, 2), 'CANCELLED', $OrderMaster->payment_method, $OrderMaster->transaction_id), $TicketInvoice->source);


                            if (!empty($User) && $User->access_type == 'agent') {
                                $CustomerInvoice = EmailTemplate::where('ref_code', 'ticketCancelAgentInvoice')->first();
                                if (!empty($CustomerInvoice)) {
                                    $To = $User->email;
                                    $msg = str_replace(array("~otdcLogo~", "~username~", "~usermobile~", "~usermail~", "~useraddress~", "~vendorLogo~", "~invoiceid~", "~orderdate~", "~servicename~", "~checkdate~", "~duration~", "~ticketquantity~", "~canceldate~"),
                                    array($this->site, $OrderMaster->customer_name, $OrderMaster->customer_phone, $OrderMaster->customer_email, $OrderMaster->customer_address1, $this->site . $Vendor->photo, $OrderMaster->invoice_id, date("M d Y h:i a", strtotime($OrderMaster->created_at)), $OrderMaster->service_name, $check_date, $duration, $guest_data, date("M d Y h:i a", strtotime($OrderMaster->cancel_date))), $CustomerInvoice->source);
                                    Mail::to($OrderMaster->customer_email)->send(new \App\Mail\RegistrationMailUser($msg, $Subject));
                                }
                            }
                        }
                        OrderMaster::find($OrderMaster->id)->update(['cancel_voucher' => $Message]);
                        if (!empty($User) && $User->access_type == 'agent') {
                            $SmsTemplate = SmsTemplate::where('ref_code', 'BookingCancelAgent')->first();
                            $sms_txt = str_replace(array("~var1~", "~var2~", "~var3~"), array($OrderMaster->customer_name, $OrderMaster->service_name, $OrderMaster->invoice_id), $SmsTemplate->source);
                            parent::sendSms('91' . $OrderMaster->customer_phone, $sms_txt);
                            $mobileNumber = $User->phone;
                        }
                        $SmsTemplate = SmsTemplate::where('ref_code', 'BookingCancel')->first();
                        $sms_txt = str_replace(array("~var1~", "~var2~", "~var3~", "~var4~"), array($OrderMaster->customer_name, $OrderMaster->service_name, $OrderMaster->invoice_id, number_format($refund_amount, 2)), $SmsTemplate->source);
                        parent::sendSms('91' . $mobileNumber, $sms_txt);

                        $Vendor = User::find($OrderMaster->vendor_id);
                        $admin = User::where('role', 1)->first();
                        $bcc = [$Vendor->email, $admin->email];
                        if (!empty($service_email)) {
                            $bcc = array_merge($bcc, explode(',', $service_email));
                        }
                        try {
                            Mail::to($To)
                                ->bcc($bcc)
                                ->send(new \App\Mail\RegistrationMailUser($Message, $Subject));
                        }
                        catch(\Exception $e) {}

                        $responce['status'] = 1;
                        $responce['message'] = 'Booking cancelled successfully.';
                    }
                // }
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }

        }
        return response()->json($responce);
    }

    public function generateInstantTicket(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'get_all_tickets') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $vendor_id = ($user->role == 2) ? $user->id : $user->vendor_id;

                $sort_column = 'vendor_id';
                $sort_direction = 'asc';
                $TicketingQuery = DB::table('tickets')
                        ->select('id', 'name', 'slug', 'feature_image', 'city', 'adult_price', 'review_score', 'review_count', 'category', 'start_date', 'end_date', 'start_time', 'end_time', 'slots', 'max_ticket_per_txn', 'max_ticket_per_user_per_day', 'show_price')
                        ->where('status', 'publish')
                        ->where('vendor_id', $vendor_id);

                if (($user->role == 3)) {
                    $SubuserAccess = SubuserAccess::where(['user_id' => $user->id, 'service' => 'ticketing'])->pluck('service_id', 'id')->toArray();
                    if (!empty($SubuserAccess)) {
                        $TicketingQuery->whereIn('id', array_values($SubuserAccess));
                    }
                }
                if(!empty($request->property)) {
                    $property = json_decode($request->property, 1);
                    foreach ($property as $terms) {
                        $TicketingQuery->where('property_slug', 'like', '%'. $terms .'%');
                    }
                }
                if(!empty($request->review_score)) {
                    $reviews = json_decode($request->review_score, 1);
                    $TicketingQuery->whereIn('review_score', $reviews);
                }
                if(!empty($request->ticketing_type)) {
                    $ticketing_type = json_decode($request->ticketing_type, 1);
                    $TicketingQuery->whereIn('category', $ticketing_type);
                }
                if(!empty($request->vendorId)) {
                    $vendors = json_decode($request->vendorId, 1);
                    $TicketingQuery->whereIn('vendor_id', $vendors);
                }
                if($request->startPrice != '' && $request->endPrice != '') {
                    $TicketingQuery->whereBetween('adult_price', [$request->startPrice, $request->endPrice]);
                }
                if ($request->city != '') {
                    $TicketingQuery->where('city', $request->city);
                }
                if ($request->sortColumn != '' && $request->direction != '') {
                    $sort_column = $request->sortColumn;
                    $sort_direction = $request->direction;
                }
                $TicketingQuery->orderBy($sort_column, $sort_direction);

                $take = 9;
                $skip = ($request->pageno == 0) ? $request->pageno : $request->pageno * $take;
                $totalData = $TicketingQuery->count();

                $TicketingData = $TicketingQuery->skip($skip)->take($take)->get()->toArray();

                if (!empty($TicketingData)) {
                    foreach ($TicketingData as $key => $value) {
                        $TicketingData[$key]->feature_image = $this->site . $value->feature_image;
                        $duration = '';
                        if (empty($TicketingData[$key]->start_time)) {
                            $slots = json_decode($value->slots, 1);
                            $TicketingData[$key]->start_time = $slots[0]['from_time'];
                        }
                        $TicketingData[$key]->duration = $duration;
                        $value->review_score = !empty($value->review_score) ? $value->review_score : 0;
                        $value->review_count = !empty($value->review_count) ? $value->review_count : 0;
                    }
                    $responce['totalPage'] = ceil($totalData/$take);
                    $responce['length'] = $totalData;
                    $responce['status'] = 1;
                    $responce['data'] = $TicketingData;
                } else {
                    $responce['status'] = 0;
                    $responce['data'] = [];
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        elseif ($request->request_type == 'get_ticketing_details') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $vendor_id = ($user->role == 2) ? $user->id : $user->vendor_id;

                $TicketingData = Ticket::where(['id' => $request->ticketId, 'status' => 'publish', 'vendor_id' => $vendor_id])->first();
                if (!empty($TicketingData)) {
                    $UserData = User::find($TicketingData->vendor_id);
                    $TicketingData->vendor_name = $UserData->company;
                    $TicketingData->vendor_email = $UserData->email;
                    $TicketingData->vendor_image = $this->site . $UserData->photo;
                    $TicketingData->member_since = date("M Y", strtotime($UserData->created_at));
                    $TicketingData->max_people_online = $TicketingData->max_people;
                    if ($request->book_from == 'offline') {
                        $TicketingData->max_people = $TicketingData->max_people_offline;
                    }
                    $order_type = $request->book_from;

                    $vendor_profile = VendorProfile::where('vendor_id', $TicketingData->vendor_id)->first();
                    if (!empty($vendor_profile)) {
                        $TicketingData->vendor_profile = $vendor_profile->profile_type;
                        if ($vendor_profile->profile_type == 'own') {
                            $TicketingData->vendor_slug = !empty($vendor_profile->profile_url) ? $vendor_profile->profile_url : 'javascript:void(0)';
                        } else {
                            $TicketingData->vendor_slug = $vendor_profile->slug;
                        }
                    } else {
                        $TicketingData->vendor_slug = '';
                    }

                    $TicketingData->startdays = 0;
                    if (!empty($TicketingData->book_start_date)) {
                        if ($TicketingData->book_start_date > date("Y-m-d")) {
                            $differ = strtotime($TicketingData->book_start_date) - strtotime(date("Y-m-d"));
                            $day = round($differ / (60 * 60 * 24));
                            $TicketingData->startdays = $day;
                        }
                    }
                    $TicketingData->feature_image = !empty($TicketingData->feature_image) ? $this->site . $TicketingData->feature_image : $TicketingData->feature_image;
                    $TicketingData->banner_image = !empty($TicketingData->banner_image) ? $this->site . $TicketingData->banner_image : $TicketingData->banner_image;
                    if (!empty($TicketingData->gallery)) {
                        $hotel_gallery = json_decode($TicketingData->gallery);
                        $TicketingData->gallery = array_map(function($val) { return $this->site . $val; } , $hotel_gallery);
                    }
                    $TicketingData->faqs = !empty($TicketingData->faqs) ? json_decode($TicketingData->faqs, 1) : $TicketingData->faqs;
                    $TicketingData->property = !empty($TicketingData->property) ? json_decode($TicketingData->property, 1) : $TicketingData->property;
                    $TicketingData->slots = !empty($TicketingData->slots) ? json_decode($TicketingData->slots, 1) : [];
                    if (empty($TicketingData->start_time)) {
                            $TicketingData->start_time = $TicketingData->slots[0]['from_time'];
                    }
                    if ($TicketingData->category == 'Events') {
                        $difference = strtotime($TicketingData->end_date) - strtotime($TicketingData->start_date);
                        $days = round($difference / (60 * 60 * 24));
                        $TicketingData->duration = $days . ' Days';
                    } else {
                        $TicketingData->duration = 'All Day';
                    }
                    $TicketingData->extra_services = !empty($TicketingData->extra_services) ? json_decode($TicketingData->extra_services, 1) : [];
                    if ($request->checkinDate != '') {
                        $BlockData = TicketAvailability::where(['ticket_id' => $TicketingData->id, 'block_date' => date('Y-m-d', strtotime($request->checkinDate))])->first();
                        if (!empty($BlockData)) {
                            $TicketingData->max_people = $TicketingData->max_people_online = $TicketingData->max_people_offline = 0;
                            $TicketingData->slots = [];
                            $responce['message'] = 'No tickets available for this date. Please choose different date!';
                        }
                        else {
                            $weekDay = date("l", strtotime($request->checkinDate));
                            $TicketingData->not_available = !empty($TicketingData->not_available) ? json_decode($TicketingData->not_available, 1) : [];
                            if (in_array($weekDay, $TicketingData->not_available)) {
                                $TicketingData->max_people = $TicketingData->max_people_online = $TicketingData->max_people_offline = 0;
                                $TicketingData->slots = [];
                                $responce['message'] = 'Ticket is not available on ' . $weekDay . '. Please choose different date!';
                            }
                            else {
                                $current_time = date("H:i:s");
                                $booked_data = array();
                                if ($TicketingData->ticket_type == 'Full Day Booking') {
                                    $booked_data = OrderMaster::select('order_type', DB::raw('SUM(total_guests) AS tot_booked'))
                                            ->where('service_name_id', $TicketingData->id)
                                            ->where('service_type', 'ticketing')
                                            ->where('start_date', date("Y-m-d", strtotime($request->checkinDate)))
                                            ->where('status', '!=', 'cancelled')
                                            ->groupBy('order_type')
                                            ->pluck('tot_booked', 'order_type')->toArray();

                                    if (!empty($booked_data)) {
                                        $total_booked = 0;
                                        if ($order_type == 'offline') {
                                            $total_booked = isset($booked_data['offline']) ? $booked_data['offline'] : 0;
                                        } elseif ($order_type == 'online') {
                                            $total_booked = isset($booked_data['online']) ? $booked_data['online'] : 0;
                                        }
                                        $TicketingData->max_people_offline = isset($booked_data['offline']) ? $TicketingData->max_people_offline - $booked_data['offline'] : $TicketingData->max_people_offline;
                                        $TicketingData->max_people_online = isset($booked_data['online']) ? $TicketingData->max_people_online - $booked_data['online'] : $TicketingData->max_people_online;

                                        $TicketingData->max_people = $TicketingData->max_people - (int)$total_booked;
                                        if ($TicketingData->max_people <= 0) {
                                            $responce['message'] = 'No tickets available for this date. Please choose different date!';
                                            $TicketingData->max_people_online = $TicketingData->max_people_offline = 0;
                                        }
                                    }
                                    // $OrderDetails = DB::table('order_masters')
                                    //         ->select('service_name_id', DB::raw('SUM(total_guests) as totQty'))
                                    //         ->where('service_name_id', $TicketingData->id)
                                    //         ->where('start_date', date("Y-m-d", strtotime($request->checkinDate)))
                                    //         ->where('status', '!=', 'cancelled')
                                    //         ->where('order_type', $order_type)
                                    //         ->groupBy('service_name_id')
                                    //         ->get();
                                    // foreach ($OrderDetails as $val) {
                                    //     $booked_data[$val->service_name_id] = $val->totQty;
                                    // }
                                    // if (array_key_exists($TicketingData->id, $booked_data)) {
                                    //     $TicketingData->max_people = $TicketingData->max_people - (int)$booked_data[$TicketingData->id];
                                    //     if ($TicketingData->max_people <= 0) {
                                    //         $responce['message'] = 'No tickets available for this date. Please choose different date!';
                                    //         $TicketingData->max_people_online = $TicketingData->max_people_offline = 0;
                                    //     }
                                    // }
                                } else {
                                    $booked_data = OrderMaster::select('start_time', DB::raw('SUM(total_guests) AS tot_booked'))
                                            ->where('service_name_id', $TicketingData->id)
                                            ->where('service_type', 'ticketing')
                                            ->where('start_date', date("Y-m-d", strtotime($request->checkinDate)))
                                            ->where('status', '!=', 'cancelled')
                                            ->where('order_type', $order_type)
                                            ->groupBy('start_time')
                                            ->pluck('tot_booked', 'start_time')->toArray();
                                    // $OrderDetails = DB::table('order_masters')
                                    //         ->select('service_name_id', DB::raw('SUM(total_guests) as totQty'), 'start_time')
