                            $service_mail = $TicketData->contact_email;
                            $OrderMaster->save();
                            $Message .= '<div style="margin-top:30px;text-align:center;"><p style="font-family: Segoe UI;color:#333;">Feel free to <a href="https://www.bookodisha.com/tourism/contact">contact us</a> for any further questions or clarifications</p><p style="font-family: Segoe UI;color:#333;"><b>bookodisha.com support team</b></p><p style="font-family: Segoe UI;font-size:11px;color:#999;margin: 0px !important; ">Please do not reply to this message. This email address is automated for delivering outbound messages.<br> Please check the web site for more information&nbsp;<a href="https://www.bookodisha.com/" target="_blank">www.bookodisha.com</a> <br>Copyright &copy; 2022 Odisha Tourism. All rights reserved. <br /> <span style="font-size:16px;"> Powered by&nbsp;&nbsp;&copy;2022-2023&nbsp;<b>Privacy Policy</b><b>&nbsp;</b><b>|&nbsp;</b><b>Odisha Tourism Support</b></span></p><p>&nbsp;</p></div>';

                            $admin = User::where('role', 1)->first();
                            $receipent = [$vendorData->email, $admin->email];
                            if (!empty($service_mail)) {
                                $receipent = array_merge($receipent, explode(',', $service_mail));
                            }
                            try {
                                Mail::to($OrderMaster->customer_email)
                                    ->bcc($receipent)
                                    ->send(new \App\Mail\RegistrationMailUser($Message, $Subject));
                            }
                            catch(\Exception $e) {}
                        }

                        $responce['status'] = 1;
                        $responce['success'] = ($OrderMaster->payment_gateway == 'hdfc') ? 2 : 1;
                        $responce['message'] = "Ticket booked successfully.";
                        $responce['invoiceid'] = $OrderMaster->invoice_id;
                        $responce['paymentMethod'] = $OrderMaster->payment_gateway;
                    } else {
                        $responce['status'] = 0;
                        $responce['success'] = 0;
                        $responce['message'] = "unable to book ticket, please try again.";
                    }
                }
            } else {
                $responce['status'] = 0;
                $responce['success'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        return response()->json($responce);
    }

    public function verifyPayment(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'verify_paytm_payment') {
            $responce['message'] = '';
            $user = $request->user();
            if (!empty($user)) {
                $vendor_id = ($user->role == 2) ? $user->id : $user->vendor_id;
                $OrderMaster = OrderMaster::where(['invoice_id' => $request->invoiceId, 'vendor_id' => $vendor_id])->first();
                if (!empty($OrderMaster)) {
                    if ($OrderMaster->status == 'pending' && $OrderMaster->payment_status == 'pending') {
                        $Url = $this->site .'cron/hdfc/check_offline_payment_status.php?order_id='. $OrderMaster->id;
                        $curl = curl_init();
                        curl_setopt_array($curl, array(
                          CURLOPT_URL => $Url,
                          CURLOPT_RETURNTRANSFER => true,
                          CURLOPT_ENCODING => '',
                          CURLOPT_MAXREDIRS => 10,
                          CURLOPT_TIMEOUT => 0,
                          CURLOPT_FOLLOWLOCATION => true,
                          CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
                          CURLOPT_CUSTOMREQUEST => 'GET',
                        ));
                        $response = curl_exec($curl);
                        curl_close($curl);

                        $NewOrdeMaster = OrderMaster::find($OrderMaster->id);
                        if ($NewOrdeMaster->status == 'completed' && $NewOrdeMaster->payment_status == 'success' && !empty($NewOrdeMaster->transaction_id)) {
                            $responce['status'] = 1;
                            $responce['success'] = 1;
                            $responce['message'] = "Payment received successfully.";
                        } else {
                            $responce['status'] = 1;
                            $responce['success'] = 2;
                            $responce['message'] = "Payment not received.";
                        }
                    } elseif ($OrderMaster->status == 'completed' && $OrderMaster->payment_status == 'success') {   // && !empty($OrderMaster->transaction_id)
                        $responce['status'] = 1;
                        $responce['success'] = 1;
                        $responce['message'] = "Payment received successfully.";
                    }
                } else {
                    $responce['status'] = 0;
                    $responce['message'] = "Invalid invoice id.";
                }
            } else {
                $responce['status'] = 0;
                $responce['message'] = "Invalid user details.";
            }
        }
        return response()->json($responce);
    }

    public function searchProperty(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if (!empty($request->search)) {
            $responce['message'] = '';
            $searchResult = array();
            $searchKey = $request->search;
            $MasterHotel = MasterHotel::select(DB::raw('DISTINCT(place) as place'), 'name')
                    ->where('status', 'publish')
                    ->where(function ($query) use($searchKey) {
                        $query->where('name', 'like', '%'. $searchKey .'%');
                        $query->orWhere('place', 'like', '%'. $searchKey .'%');
                    })
                    ->get();

            if (!empty($MasterHotel)) {
                $place_array = array();
                foreach ($MasterHotel as $value) {
                    if (stripos($value->place, $searchKey) != -1 && !in_array($value->place, $place_array)) {
                        $searchResult[] = array(
                            'name' => '',
                            'location' => $value->place,
                            'search_type' => 'location',
                            'type' => 'hotel'
                        );
                    }
                    array_push($place_array, $value->place);
                    if (stripos($value->name, $searchKey) != -1) {
                        $searchResult[] = array(
                            'name' => $value->name,
                            'location' => $value->place,
                            'search_type' => 'name',
                            'type' => 'hotel'
                        );
                    }
                }
            }
            $MasterCar = MasterCar::select(DB::raw('DISTINCT(city) as city'), 'title')
                    ->where('status', 'publish')
                    ->where(function ($query) use($searchKey) {
                        $query->where('title', 'like', '%'. $searchKey .'%');
                        $query->orWhere('city', 'like', '%'. $searchKey .'%');
                    })
                    ->get();
            if (!empty($MasterCar)) {
                $place_array = array();
                foreach ($MasterCar as $value) {
                    if (stripos($value->city, $searchKey) != -1 && !in_array($value->city, $place_array)) {
                        $searchResult[] = array(
                            'name' => '',
                            'location' => $value->city,
                            'search_type' => 'location',
                            'type' => 'rental'
                        );
                    }
                    array_push($place_array, $value->city);
                    if (stripos($value->title, $searchKey) != -1) {
                        $searchResult[] = array(
                            'name' => $value->title,
                            'location' => $value->city,
                            'search_type' => 'name',
                            'type' => 'rental'
                        );
                    }
                }
            }
            $Tour = Tour::select(DB::raw('DISTINCT(city) as city'), 'name')
                    ->where('status', 'publish')
                    ->where(function ($query) use($searchKey) {
                        $query->where('name', 'like', '%'. $searchKey .'%');
                        $query->orWhere('city', 'like', '%'. $searchKey .'%');
                    })
                    ->get();
            if (!empty($Tour)) {
                $place_array = array();
                foreach ($Tour as $value) {
                    if (stripos($value->city, $searchKey) != -1 && !in_array($value->city, $place_array)) {
                        $searchResult[] = array(
                            'name' => '',
                            'location' => $value->city,
                            'search_type' => 'location',
                            'type' => 'tour'
                        );
                    }
                    array_push($place_array, $value->city);
                    if (stripos($value->name, $searchKey) != -1) {
                        $searchResult[] = array(
                            'name' => $value->name,
                            'location' => $value->city,
                            'search_type' => 'name',
                            'type' => 'tour'
                        );
                    }
                }
            }
            $Ticket = Ticket::select(DB::raw('DISTINCT(city) as city'), 'name')
                    ->where('status', 'publish')
                    ->where(function ($query) use($searchKey) {
                        $query->where('name', 'like', '%'. $searchKey .'%');
                        $query->orWhere('city', 'like', '%'. $searchKey .'%');
                    })
                    ->get();
            if (!empty($Ticket)) {
                $place_array = array();
                foreach ($Ticket as $value) {
                    if (stripos($value->city, $searchKey) != -1 && !in_array($value->city, $place_array)) {
                        $searchResult[] = array(
                            'name' => '',
                            'location' => $value->city,
                            'search_type' => 'location',
                            'type' => 'ticket'
                        );
                    }
                    array_push($place_array, $value->city);
                    if (stripos($value->name, $searchKey) != -1) {
                        $searchResult[] = array(
                            'name' => $value->name,
                            'location' => $value->city,
                            'search_type' => 'name',
                            'type' => 'ticket'
                        );
                    }
                }
            }
            $responce['data'] = $searchResult;
        }
        return response()->json($responce);
    }

    public function getVersion(Request $request) {
        $responce = ['status' => 0, 'message' => 'Network error, please try again.'];
        if ($request->request_type == 'ios-version') {
            $data = [
                'version' => '1.2.4',
                'app_url' => 'https://apps.apple.com/in/app/book-odisha/id1599847332'
            ];
            $AppData = PageContent::where(['type' => 'app-details', 'title' => 'ios-version'])->first();
            if (!empty($AppData)) {
                $data = [
                    'version' => $AppData->content,
                    'app_url' => $AppData->url
                ];
            }
            $responce['status'] = 1;
            $responce['data'] = $data;
            $responce['message'] = '';
        }
        return response()->json($responce);
    }

    public function releaseSeatBySp($schedule_id, $date, $adult_count){
        $status = null;
        $message = null;

        DB::statement(
            "CALL sp_release_flight_seats(?, ?, ?, @status, @message)",
            [
                $schedule_id,
                $date,
                $adult_count
            ]
        );
        $result = DB::selectOne(
            "SELECT @status AS status, @message AS message"
        );
        $status = $result->status;
        $message = $result->message;
        return ['status' => $status, 'message' => $message];
    }

    public function image_resize($width = 0, $height = 0, $image_url) {

        $source_path = public_path($image_url);
        list($source_width, $source_height, $source_type) = getimagesize($source_path);
        switch ($source_type) {
            case IMAGETYPE_GIF:
                $source_gdim = imagecreatefromgif($source_path);
                break;
            case IMAGETYPE_JPEG:
                $source_gdim = imagecreatefromjpeg($source_path);
                break;
            case IMAGETYPE_PNG:
                $source_gdim = imagecreatefrompng($source_path);
                break;
        }
        $source_aspect_ratio = $source_width / $source_height;
        $desired_aspect_ratio = $width / $height;

        if ($source_aspect_ratio > $desired_aspect_ratio) {
            /*
             * Triggered when source image is wider
             */
            $temp_height = $height;
            $temp_width = (int) ($height * $source_aspect_ratio);
        } else {
            /*
             * Triggered otherwise (i.e. source image is similar or taller)
             */
            $temp_width = $width;
            $temp_height = (int) ($width / $source_aspect_ratio);
        }
        /*
         * Resize the image into a temporary GD image
         */
        $temp_gdim = imagecreatetruecolor($temp_width, $temp_height);
        imagecopyresampled(
                $temp_gdim, $source_gdim, 0, 0, 0, 0, $temp_width, $temp_height, $source_width, $source_height
        );
        /*
         * Copy cropped region from temporary image into the desired GD image
         */

        $x0 = ($temp_width - $width) / 2;
        $y0 = ($temp_height - $height) / 2;
        $desired_gdim = imagecreatetruecolor($width, $height);
        imagecopy(
                $desired_gdim, $temp_gdim, 0, 0, $x0, $y0, $width, $height
        );
        /*
         * Render the image
         * Alternatively, you can save the image in file-system or database
         */
        // $image_url = $upload_url . $filename;
        imagepng($desired_gdim, $source_path);
        // return $image_url;
    }

